-----------------------------------------------------------------------------------------

/*
Description
   
   This script creates the Announcement Cards class if it doesn't already exists.
   The permissions and settings are updated with the announcement card id. 
*/
EXEC ebps_drop 'procedure', 'ebps_pop_announce_class_objs'
GO
CREATE PROCEDURE ebps_pop_announce_class_objs
(
   @pi_group_id          INT,
   @ps_code              NVARCHAR(255),
   @ps_name              NVARCHAR(255),
   @ps_sys_type          NVARCHAR(255),
   @ps_access_modifiers  NVARCHAR(255),
   @pi_hide_flags        INT,      
   @pi_lock_flags        INT,
   @pi_parent_class_id   INT,
   @pi_class_id          INT OUTPUT -- The newly created class id
    
)
AS
DECLARE
   @li_error           INT
BEGIN
   SET NOCOUNT ON;

   -- Find the Class...
   SELECT @pi_class_id = class_id FROM class_objects WHERE code = @ps_code AND group_id = @pi_group_id
   IF @@ROWCOUNT = 0
   BEGIN
      -- Add class if it does not exists
      EXEC @li_error = ebp_new_id N'class_id', @pi_class_id OUTPUT
      IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure

      INSERT INTO class_objects( class_id, group_id, namespace_id, code, name, sys_type, access_modifiers, prevent_approval_flags, prompt_flags, is_sync_tracked, parent_class_id )
      VALUES( @pi_class_id, @pi_group_id, 1, @ps_code, @ps_name, @ps_sys_type, @ps_access_modifiers, 0, 0, 'N',  @pi_parent_class_id)
      IF @@ERROR <> 0 RETURN 1 -- Failure

      -- Add as an Object (Scope becomes the default Session Scope)
      INSERT INTO objects( guid, object_id, object_type, scope_id, hide_flags, lock_flags, date_added, added_by, date_changed, changed_by )
      VALUES( NULL, @pi_class_id, 185, 1, @pi_hide_flags, @pi_lock_flags, GETDATE(), 1, GETDATE(), 1 )
      IF @@ERROR <> 0 RETURN 1 -- Failure
   END
   ELSE
   BEGIN
      -- Update the Class
      UPDATE class_objects 
      SET name = @ps_name,
          sys_type = @ps_sys_type,
          access_modifiers = @ps_access_modifiers
      WHERE class_id = @pi_class_id  
      IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure 
     
      -- Update hide and lock_flags in table object
      UPDATE objects 
      SET hide_flags = @pi_hide_flags,
          lock_flags = @pi_lock_flags
      WHERE object_id = @pi_class_id AND object_type = 185  
      IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure     
   END
   
   RETURN 0 -- Success
END
GO

DECLARE
   @li_parent_class_id   INT,
   @li_class_id          INT,
   @li_count             INT = 0

BEGIN
   -- Add the parent class for announcement events; hide the classes from modifications or adding child classes by the user.
   EXEC ebps_pop_announce_class_objs 13, N'$ANNOUNCEMENTS', N'Announcements', N'F', N'A', 0, 18, NULL, @li_parent_class_id OUT

    -- add the Id of the class to system setting "AnnouncementClassId"
   SELECT @li_count = COUNT(*) FROM settings s WHERE s.setting_id = (SELECT sd.setting_id FROM setting_defs sd WHERE sd.object_type = 20 AND sd.code = N'AnnouncementClassId') 
   IF @li_count = 0
   BEGIN
      INSERT INTO settings (setting_id, object_id, value)
         SELECT a.setting_id, 1, @li_parent_class_id
         FROM setting_defs a WHERE a.object_type = 20 AND a.code = N'AnnouncementClassId'
   END    
   ELSE
   BEGIN
     SELECT @li_parent_class_id = CONVERT(INT, s.value)
     FROM settings s WITH (NOLOCK)
     INNER JOIN setting_defs sd WITH (NOLOCK) ON sd.setting_id = s.setting_id AND
            sd.object_type = 20 AND sd.code = N'AnnouncementClassId'
   END

   IF @li_parent_class_id IS NOT NULL
   BEGIN
     -- Update the parent class to allow adding of child classes
     UPDATE class_objects
     SET access_modifiers = N'A'
     WHERE class_id = @li_parent_class_id

     -- Add child classes for notification events 
     EXEC ebps_pop_announce_class_objs 13, N'$ANNOUNCEMENT-RED', N'01-Red', N'F', N'S', 0, 18, @li_parent_class_id, @li_class_id OUT
     EXEC ebps_pop_announce_class_objs 13, N'$ANNOUNCEMENT-GREEN', N'02-Green', N'F', N'S', 0, 18, @li_parent_class_id, @li_class_id OUT
     EXEC ebps_pop_announce_class_objs 13, N'$ANNOUNCEMENT-BLUE', N'03-Blue', N'F', N'S', 0, 18, @li_parent_class_id, @li_class_id OUT
   
     -- Update the parent class to not allow adding of child classes
     UPDATE class_objects
     SET access_modifiers = N'S'
     WHERE class_id = @li_parent_class_id
  END

END
GO

EXEC ebps_drop 'procedure', 'ebps_pop_announce_class_objs'
GO


GO


