/*
Description
   Creates templates for notification card events.
Note
*/
EXEC ebps_drop 'procedure', 'ebps_pop_announce_evt_templ'
GO
CREATE PROCEDURE ebps_pop_announce_evt_templ
(
   @ps_class_code                           NVARCHAR(255),
   @ps_announce_evt_templ_name              NVARCHAR(255),
   @ps_template_description                 NVARCHAR(255),
   @ps_mask                                 NVARCHAR(100),
   @pi_hide_flags                           INT,      
   @pi_lock_flags                           INT
)
AS
DECLARE
   @li_error           INT,
   @ls_name            NVARCHAR(255),
   @ls_msg             NVARCHAR(1024),
   @li_template_id     INT,
   @li_class_id        INT,
   @li_event_id        INT,
   @lany_attributes    ebtype_dictionary
BEGIN
   SET NOCOUNT ON;

   -- check if template name exists 
   -- get the class_id for notification_events
   SELECT @li_class_id = co.class_id
   FROM class_objects co WITH (NOLOCK) 
   WHERE co.code = @ps_class_code

   SELECT @li_template_id = t.template_id
         ,@li_event_id = t.object_id
   FROM templates t WITH (NOLOCK)
   WHERE class_id = @li_class_id AND object_type = 94

   IF @li_template_id IS NULL
   BEGIN
     DECLARE @pdt_start_date    DATETIME = getdate()
            ,@pdt_end_date      DATETIME = null

     -- Add the template   
     EXEC @li_error = ebp_add_template @ps_announce_evt_templ_name, @ps_template_description, @ps_mask, @li_class_id, NULL, 94, 0, 'N', NULL, NULL, 0, 1, @li_template_id OUT
     IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure

     -- Approve the template
     EXEC @li_error = ebp_chg_template @li_template_id, '%', '%', '%', -1, 'A', -1, -1, '%', '%', '%', -1, 1
     IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure

      -- want the event id here
      SELECT @li_event_id = t.object_id 
      FROM templates t WITH (NOLOCK) 
      WHERE template_id = @li_template_id

    END

    BEGIN
      -- Update lock and hide flags for templates
      UPDATE objects
      SET lock_flags = @pi_lock_flags
         ,hide_flags = @pi_hide_flags
      WHERE object_id = @li_template_id
      AND object_type = 188
      IF @@ERROR <> 0 RETURN 1 -- Failure

      -- update events to restrict deletion and modification
      UPDATE objects
      SET lock_flags = @pi_lock_flags
         ,hide_flags = @pi_hide_flags
      WHERE object_id = @li_event_id
      AND object_type = 94
      IF @@ERROR <> 0 RETURN 1 -- Failure

    END;

   RETURN 0 -- Success
 
END
GO

BEGIN

   EXEC ebps_pop_announce_evt_templ N'$ANNOUNCEMENT-RED', N'ANNOUNCEMENT-RED-T', N'Announcement, Red, Template', NULL, 1, 18
   EXEC ebps_pop_announce_evt_templ N'$ANNOUNCEMENT-GREEN',N'ANNOUNCEMENT-GREEN-T', N'Announcement, Green, Template', NULL , 1, 18
   EXEC ebps_pop_announce_evt_templ N'$ANNOUNCEMENT-BLUE',N'ANNOUNCEMENT-BLUE-T', N'Announcement, BLUE, Template', NULL , 1, 18

END
GO
EXEC ebps_drop 'procedure', 'ebps_pop_announce_evt_templ'
GO

GO


-- =====================================================================
-- FILE: attribute_domain_sources.sql
-- =====================================================================

-----------------------------------------------------------------------------------------
-- $Copyright: (c) 2018 Bentley Systems, Incorporated. All rights reserved. $
-----------------------------------------------------------------------------------------

/*
Description
   Populates intrinsic_properties as attribute domain sources. Only properties listed here may be used to further restrict 
   the intrinsic relationship based on the clas of the object related to it.

   As an example, Tag.InstallableItem must be registered to limit which class of physical item may be related to a specific tag.
   Or Condition.Applies to must be registered to limit which class of <object> may be related to the condition.
   
Parameters:
   ps_char_name:
      The name of the Intrinsic attribute the attribute domain can apply to


   pi_object_type:
      The type for the attribute. 

   pi_attrib_object_type:
      The object type for the attribute.
      Typically this is null, the pi_object_type is the same type but in cases where there is a strong dependant relationship where the parent controls the class then 
      pi_attrib_object_type would refer to the dependant object containing the intrinsic property and pi_object_type refer to the parent.

      For example:
         TaskOrder (has a class)
            TaskOrderItem (has no class) -- (has property) -- Task (has a class)

         The domain restriction ON TaskOrderItem.Task but BETWEEN the TaskOrder Class and Task Class.

   pi_source_object_type:
      What sort of types will be allowed in this relationship.
*/
EXEC ebps_drop 'procedure', 'ebps_pop_attrib_domain_source'
GO
CREATE PROCEDURE ebps_pop_attrib_domain_source
(
   @ps_char_name             NVARCHAR(100),   
   @pi_object_type           INT,
   @pi_attrib_object_type    INT,
   @pi_source_object_type    INT   
)
AS
DECLARE
   @li_attrib_id         INT,
   @li_id                INT,
   @ls_error             NVARCHAR(2000),
   @li_attrib_type       INT
BEGIN
   SET NOCOUNT ON;

   SET @li_attrib_type = @pi_object_type;
   IF COALESCE(@pi_attrib_object_type, 0) > 0 SET @li_attrib_type = @pi_attrib_object_type;

   -- Find the char_id based on the name
   SELECT @li_attrib_id = char_id FROM characteristics WHERE char_name = @ps_char_name AND object_type = @li_attrib_type AND is_intrinsic = N'Y' AND char_data_type = N'RF';
   IF COALESCE(@li_attrib_id, 0) = 0
   BEGIN
      SET @ls_error ='<No intrinsic attribute called ''' + @ps_char_name + ''' for the object type ''' + CAST(@li_attrib_type AS NVARCHAR(100)) + ''' can be found.>';
      EXEC ebp_raise_error @ls_error, 1
   END

   -- Check for an existing row using the unique/ak           
   INSERT INTO attribute_domain_sources(char_id, object_type, source_object_type)
   SELECT @li_attrib_id, @pi_object_type, @pi_source_object_type  
   WHERE NOT EXISTS(SELECT 1 FROM attribute_domain_sources WITH (NOLOCK) WHERE char_id = @li_attrib_id AND object_type = @pi_object_type AND source_object_type = @pi_source_object_type)
   
   IF @@ERROR <> 0 RETURN 1 -- Failure
END
GO

BEGIN
   -- Tags
   --    InstallableItem
   --    ScheduleDefinition
   EXEC ebps_pop_attrib_domain_source N'Intrinsic/InstallableItems', 212, NULL, 1
   -- TODO: Intrinsic/ScheduleDefinition is not a real intrinsic property - it will not be found on a datacontract - it is needed to create attribute domain definitions that act as 'definitions' for which type of task may be created by the schedule
   -- This really says, when schedules are used, what type of task should be created depending on the schedule for the type of tag. There is no Tag.ScheduleDefinition property.
   EXEC ebps_pop_attrib_domain_source N'Intrinsic/ScheduleDefinition', 212, NULL, 340

   -- Condition
   --    AppliesTo
   EXEC ebps_pop_attrib_domain_source N'Intrinsic/AppliesTo', 322, NULL, 212
   EXEC ebps_pop_attrib_domain_source N'Intrinsic/AppliesTo', 322, NULL, 333
   --    IdentifiedBy
   EXEC ebps_pop_attrib_domain_source N'Intrinsic/IdentifiedBy', 322, NULL, 340
   --    ProvisionalTasks
   EXEC ebps_pop_attrib_domain_source N'Intrinsic/ProvisionalTasks', 322, NULL, 340
   --    ClosingTasks
   EXEC ebps_pop_attrib_domain_source N'Intrinsic/ClosingTasks', 322, NULL, 340

   -- Task
   --    PhysicalItems
   EXEC ebps_pop_attrib_domain_source N'Intrinsic/PhysicalItems', 340, NULL, 1
   --    Documents
   EXEC ebps_pop_attrib_domain_source N'Intrinsic/Documents', 340, NULL, 3
   --    ChangeRequests
   EXEC ebps_pop_attrib_domain_source N'Intrinsic/ChangeRequests', 340, NULL, 6
   --    DistributionOrders
   EXEC ebps_pop_attrib_domain_source N'Intrinsic/DistributionOrders', 340, NULL, 25
   --    Events
   EXEC ebps_pop_attrib_domain_source N'Intrinsic/Events', 340, NULL, 94
   --    Tags
   EXEC ebps_pop_attrib_domain_source N'Intrinsic/Tags', 340, NULL, 212
   --    Child Task Classes
   EXEC ebps_pop_attrib_domain_source N'Intrinsic/Children', 340, NULL, 340

   -- TaskOrderItem (Limited by Parent TaskOrder.Class)
   --    Task
   EXEC ebps_pop_attrib_domain_source N'Intrinsic/Task', 341, 342, 340

   -- ProgramItem (Limited by Program.Class)
   -- Object [ Tag / SerialItem ]
   EXEC ebps_pop_attrib_domain_source N'Intrinsic/Object', 349, 350, 212
   -- EXEC ebps_pop_attrib_domain_source N'Intrinsic/Object', 349, 350, 18  // Not used and not classified at present

END
GO

EXEC ebps_drop 'procedure', 'ebps_pop_attrib_domain_source'
GO

GO


