EXEC ebps_drop 'procedure', 'ebps_pop_audit_info_def'
GO
CREATE PROCEDURE ebps_pop_audit_info_def
(
   @pi_object_type INT,
   @pi_action_type INT,
   @ps_name        NVARCHAR(255),
   @pc_track       CHAR(1),
   @pc_must_track  CHAR(1),
   @pi_purge_flags INT      -- 0: can't purge, 1:leave one entry when purged, 2:purge all
)
AS
DECLARE
   @li_action_type INT
BEGIN
   SET NOCOUNT ON;

   SELECT @li_action_type = ISNULL(action_type, 0)
   FROM audit_info_defs
   WHERE action_type = @pi_action_type AND object_type = @pi_object_type

   IF ISNULL(@li_action_type, 0) = 0
   BEGIN
      INSERT INTO audit_info_defs( object_type, action_type, name, track, must_track, purge_flags )
      VALUES ( @pi_object_type, @pi_action_type, @ps_name, @pc_track, @pc_must_track, @pi_purge_flags )
      IF @@ERROR <> 0 RETURN 1 -- Failure
   END
   ELSE
   BEGIN
      UPDATE audit_info_defs
      SET name = @ps_name
      WHERE action_type = @pi_action_type AND object_type = @pi_object_type
      IF @@ERROR <> 0 RETURN 1 -- Failure
   END

   RETURN 0 -- Success
END
GO

BEGIN
   -- Documents
   EXEC ebps_pop_audit_info_def 3, 1, N'Created', N'Y', N'Y', 0
   EXEC ebps_pop_audit_info_def 3, 2, N'Approved', N'Y', N'Y', 0
