/*
Description
   Populates the Audit Property Definitions.

Parameters:
   ps_track -  Only set when an entry is populated the first time, do not want to reset user defined configuration by updating each time it's executed
*/
EXEC ebps_drop 'procedure', 'ebps_populate_audit_prop_defs'
GO
CREATE PROCEDURE ebps_populate_audit_prop_defs
(
   @pi_object_type      INT,
   @ps_collection_name  NVARCHAR(255),
   @ps_field_name       NVARCHAR(255),
   @pi_ref_type         INT,
   @ps_track            NCHAR(1) = N'N'
)
AS
DECLARE
   @li_property_id INT
BEGIN
   SET NOCOUNT ON;

   SELECT @li_property_id = MAX( property_id ) FROM audit_property_defs

   SET @li_property_id = COALESCE( @li_property_id, 0 ) + 1;

   IF NOT EXISTS ( SELECT 1 FROM audit_property_defs
                   WHERE object_type = @pi_object_type
                   AND dbo.ebfs_compare_s( collection_name, @ps_collection_name ) = 1
                   AND field_name = @ps_field_name )
   BEGIN
      INSERT INTO audit_property_defs( property_id, object_type, collection_name, field_name, ref_type, track )
      VALUES ( @li_property_id, @pi_object_type, @ps_collection_name, @ps_field_name, @pi_ref_type, @ps_track )
      IF @@ERROR <> 0 RETURN 1 -- Failure
   END
   ELSE
   BEGIN
      -- Note 'track' isn't updated but only set when populated the first time, do not want to reset user defined configuration
      UPDATE audit_property_defs
      SET ref_type = @pi_ref_type
      WHERE object_type = @pi_object_type
      AND dbo.ebfs_compare_s( collection_name, @ps_collection_name ) = 1
      AND field_name = @ps_field_name
      IF @@ERROR <> 0 RETURN 1 -- Failure
   END

   RETURN 0 -- Success
END
GO
-- Populate some standard things
CREATE PROCEDURE ebps_populate_audit_prop_std
(
   @pi_object_type INT,
   @pi_option      INT
)
AS
DECLARE
   @li_property_id INT
BEGIN
   SET NOCOUNT ON;

   -- We want the RelationshipType to be first in the list
   EXEC ebps_populate_audit_prop_defs @pi_object_type, N'ChangeRequests',N'RelationshipType', 87
   EXEC ebps_populate_audit_prop_defs @pi_object_type, N'Documents',N'RelationshipType', 87
   EXEC ebps_populate_audit_prop_defs @pi_object_type, N'Events',N'RelationshipType', 87
   EXEC ebps_populate_audit_prop_defs @pi_object_type, N'GroupedVirtualItems',N'RelationshipType', 87
   EXEC ebps_populate_audit_prop_defs @pi_object_type, N'Locations',N'RelationshipType', 87
   EXEC ebps_populate_audit_prop_defs @pi_object_type, N'Organizations',N'RelationshipType', 87
   EXEC ebps_populate_audit_prop_defs @pi_object_type, N'Persons',N'RelationshipType', 87
   EXEC ebps_populate_audit_prop_defs @pi_object_type, N'PhysicalItems',N'RelationshipType', 87
   EXEC ebps_populate_audit_prop_defs @pi_object_type, N'Projects',N'RelationshipType', 87
   EXEC ebps_populate_audit_prop_defs @pi_object_type, N'SerializedItems',N'RelationshipType', 87
   EXEC ebps_populate_audit_prop_defs @pi_object_type, N'SharePointItems',N'RelationshipType', 87
   EXEC ebps_populate_audit_prop_defs @pi_object_type, N'ProjectWiseItems',N'RelationshipType', 87
   EXEC ebps_populate_audit_prop_defs @pi_object_type, N'Tags',N'RelationshipType', 87
   EXEC ebps_populate_audit_prop_defs @pi_object_type, N'VirtualItemGroups',N'RelationshipType', 87
   EXEC ebps_populate_audit_prop_defs @pi_object_type, N'ExternalObjects',N'RelationshipType', 87
   
   -- Relationships
   IF @pi_option = 1
   BEGIN
      IF @pi_object_type <> 6 EXEC ebps_populate_audit_prop_defs @pi_object_type, N'ChangeRequests',N'ChangeRequest', 6
      IF @pi_object_type <> 3 EXEC ebps_populate_audit_prop_defs @pi_object_type, N'Documents',N'Document', 3
      IF @pi_object_type <> 94 EXEC ebps_populate_audit_prop_defs @pi_object_type, N'Events',N'Event', 94
      IF @pi_object_type <> 123 EXEC ebps_populate_audit_prop_defs @pi_object_type, N'GroupedVirtualItems',N'GroupedVirtualItem', 123
      IF @pi_object_type <> 12 EXEC ebps_populate_audit_prop_defs @pi_object_type, N'Locations',N'Location', 12
      IF @pi_object_type <> 5 EXEC ebps_populate_audit_prop_defs @pi_object_type, N'Organizations',N'Organization', 5
      IF @pi_object_type <> 4 EXEC ebps_populate_audit_prop_defs @pi_object_type, N'Persons',N'Person', 4
      IF @pi_object_type <> 1 EXEC ebps_populate_audit_prop_defs @pi_object_type, N'PhysicalItems',N'PhysicalItem', 1
      IF @pi_object_type <> 9 EXEC ebps_populate_audit_prop_defs @pi_object_type, N'Projects',N'Project', 9
      IF @pi_object_type <> 18 EXEC ebps_populate_audit_prop_defs @pi_object_type, N'SerializedItems',N'SerializedItem', 18
      IF @pi_object_type <> 223 EXEC ebps_populate_audit_prop_defs @pi_object_type, N'SharePointItems',N'SharePointItem', 223
      IF @pi_object_type <> 251 EXEC ebps_populate_audit_prop_defs @pi_object_type, N'ProjectWiseItems',N'ProjectWiseItem', 251
      IF @pi_object_type <> 212 EXEC ebps_populate_audit_prop_defs @pi_object_type, N'Tags',N'Tag', 212
      IF @pi_object_type <> 182 EXEC ebps_populate_audit_prop_defs @pi_object_type, N'VirtualItemGroups',N'VirtualItemGroup', 182
      IF @pi_object_type <> 313 EXEC ebps_populate_audit_prop_defs @pi_object_type, N'ExternalObjects',N'ExternalObject', 313
   END

   RETURN 0 -- Success
END
GO

