   EXEC ebps_populate_audit_prop_defs 402, N'Holidays', N'Name', NULL   


   -- Populate all Custom Attributes. New ones will be updated by the Add/Chg/Del Attribute procedures.
   SELECT @li_property_id = MAX( property_id ) FROM audit_property_defs

   DECLARE lcur_prop_defs CURSOR LOCAL FAST_FORWARD FOR
   SELECT a.char_id, a.object_type, a.char_name, a.multi_valued, b.name, a.char_data_type
   FROM characteristics a  WITH (NOLOCK) 
   INNER JOIN namespaces b  WITH (NOLOCK) ON b.namespace_id = a.namespace_id
   WHERE a.is_intrinsic = N'N'
   OPEN lcur_prop_defs
   FETCH NEXT FROM lcur_prop_defs INTO @li_attrib_id, @li_object_type, @ls_field_name, @ls_multi_valued, @ls_namespace_name, @ls_datatype
   WHILE (@@FETCH_STATUS = 0)
   BEGIN

      IF @ls_multi_valued = N'Y' OR @ls_datatype = N'TB'
      BEGIN
         SET @ls_collection_name = N'Attributes["' + @ls_namespace_name + N'", "' + @ls_field_name + N'"]';
         SET @ls_field_name = N'Value';
      END
      ELSE
      BEGIN
         SET @ls_collection_name = NULL;
         SET @ls_field_name = N'Attributes["' + @ls_namespace_name + N'", "' + @ls_field_name + N'"].Value';
      END

      IF NOT EXISTS ( SELECT 1 FROM audit_property_defs WHERE attrib_id = @li_attrib_id AND object_type = @li_object_type )
      BEGIN
         SET @li_property_id = COALESCE( @li_property_id, 0 ) + 1;

         INSERT INTO audit_property_defs( property_id, object_type, collection_name, field_name, ref_type, track, attrib_id )
         VALUES ( @li_property_id, @li_object_type, @ls_collection_name, @ls_field_name, NULL, N'N', @li_attrib_id )
      END
      ELSE
      BEGIN
         UPDATE audit_property_defs
         SET object_type = @li_object_type,
             collection_name = @ls_collection_name,
             field_name = @ls_field_name,
             ref_type = NULL
         WHERE attrib_id = @li_attrib_id
         AND object_type = @li_object_type
      END

      -- Special case for Vig, add all document attributes as type 182 as well.
      IF @li_object_type = 3
      BEGIN
         IF NOT EXISTS ( SELECT 1 FROM audit_property_defs WHERE attrib_id = @li_attrib_id and object_type = 182 )
         BEGIN
            SET @li_property_id = COALESCE( @li_property_id, 0 ) + 1;

            -- Set the track prooperty based on what it is for the document attribute at this time
            SELECT @ls_track = COALESCE( track, N'N' ) FROM audit_property_defs WITH (NOLOCK) WHERE attrib_id = @li_attrib_id AND object_type = 3;

            INSERT INTO audit_property_defs( property_id, object_type, collection_name, field_name, ref_type, track, attrib_id )
            VALUES ( @li_property_id, 182, @ls_collection_name, @ls_field_name, NULL, @ls_track, @li_attrib_id )
         END
         ELSE
         BEGIN
            UPDATE audit_property_defs
            SET object_type = 182,
                collection_name = @ls_collection_name,
                field_name = @ls_field_name,
                ref_type = NULL
            WHERE attrib_id = @li_attrib_id
            AND object_type = 182
         END
      END

      FETCH NEXT FROM lcur_prop_defs INTO @li_attrib_id, @li_object_type, @ls_field_name, @ls_multi_valued, @ls_namespace_name, @ls_datatype
   END
   CLOSE lcur_prop_defs
   DEALLOCATE lcur_prop_defs

END
GO
