-- =====================================================================

-----------------------------------------------------------------------------------------
-- $Copyright: (c) 2019 Bentley Systems, Incorporated. All rights reserved. $
-----------------------------------------------------------------------------------------

/*
Description
   Pluggable methods for use in eQL EXEC automations.

Note:
   These methods are provided as out-of-the-box examples for derived attribute automation methods:
      ebp_basic_arithmetic
      ebp_basic_trigonometry
*/

BEGIN
   DECLARE @li_method_id INT
   SELECT @li_method_id = method_id FROM method_info WHERE code_ref = N'ebp_basic_arithmetic'
   IF @li_method_id > 0
   BEGIN
      EXEC ebp_del_method_info @li_method_id, 1
   END

   EXEC ebp_add_method_info 'ebp_basic_arithmetic',
                            1, -- Indicates a Stored Procedure
                            'N', -- Y if the method should run in a transaction, N should only be used when the method will make no updates and only retrieve data.
                            'ebp_basic_arithmetic',
                            1, -- Option 1 registers parameters, 0 to register them manually
                            1, -- Session Id used to make the call
                            @li_method_id OUT
END
GO

BEGIN
   DECLARE @li_method_id INT
   SELECT @li_method_id = method_id FROM method_info WHERE code_ref = N'ebp_basic_trigonometry'
   IF @li_method_id > 0
   BEGIN
      EXEC ebp_del_method_info @li_method_id, 1
   END

   EXEC ebp_add_method_info 'ebp_basic_trigonometry',
                            1, -- Indicates a Stored Procedure
                            'N', -- Y if the method should run in a transaction, N should only be used when the method will make no updates and only retrieve data.
                            'ebp_basic_trigonometry',
                            1, -- Option 1 registers parameters, 0 to register them manually
                            1, -- Session Id used to make the call
                            @li_method_id OUT
END
GO

GO


