*/
EXEC ebps_drop 'procedure', 'ebps_populate_class_groups'
GO
CREATE PROCEDURE ebps_populate_class_groups
(   
   @pi_group_id    INT,
   @pi_object_type INT,
   @ps_name        NVARCHAR(255),
   @ps_status      CHAR(1)
)
AS
BEGIN
   SET NOCOUNT ON;

   INSERT INTO class_groups( group_id, object_type, name, status )
   SELECT @pi_group_id, @pi_object_type, @ps_name, @ps_status
   WHERE NOT EXISTS( SELECT 1 FROM class_groups WHERE group_id = @pi_group_id )
   IF @@ERROR <> 0 RETURN 1 -- Failure
   
   UPDATE class_groups SET object_type = @pi_object_type , name = @ps_name, status = @ps_status
   WHERE group_id = @pi_group_id 
   IF @@ERROR <> 0 RETURN 1 -- Failure
   
   -- Add as an Object (Scope becomes 'Global')
   INSERT INTO objects( guid, object_id, object_type, scope_id, hide_flags, lock_flags, date_added, added_by, date_changed, changed_by )
   SELECT NULL, @pi_group_id, 184, 1, 0, 0, GETDATE(), 1, GETDATE(), 1
   WHERE NOT EXISTS ( SELECT 1 FROM objects WHERE object_id = @pi_group_id AND object_type = 184 )   
   IF @@ERROR <> 0 RETURN 1 -- Failure   

   RETURN 0 -- Success
END
GO

