-- Populate default cost categories so we do't start with an empty database
EXEC ebps_drop 'procedure', 'ebps_populate_cost_category'
GO
CREATE PROCEDURE ebps_populate_cost_category
(
    @pi_namespace_id INT,
    @pi_scope_id     INT,
    @ps_name         NVARCHAR(255),
    @ps_description  NVARCHAR(2000)
)
AS
DECLARE
    @li_id           INT
BEGIN
    SET NOCOUNT ON;

    -- ebp_new_id may not exist at this point 
    --EXEC @li_error = ebp_new_id 'cc_type_id', @@li_id OUTPUT
    SELECT @li_id = cc_type_id FROM cost_categories WHERE namespace_id = @pi_namespace_id AND name = @ps_name;
    IF @li_id IS NULL
    BEGIN
        SELECT @li_id = COALESCE( MAX( cc_type_id ), 0 ) + 1 FROM cost_categories

        INSERT INTO cost_categories ( cc_type_id, namespace_id, name, description )
        SELECT @li_id, @pi_namespace_id, @ps_name, @ps_description
        IF @@ERROR <> 0 RETURN 1 -- Failure
    END
    ELSE
    BEGIN
        UPDATE cost_categories SET description = @ps_description
        WHERE cc_type_id = @li_id
        IF @@ERROR <> 0 RETURN 1 -- Failure
    END

    IF NOT EXISTS (SELECT 1 FROM objects WHERE object_type = 336 AND object_id = @li_id)
    BEGIN
        INSERT INTO objects ( object_id, object_type, scope_id, hide_flags, lock_flags )
        SELECT @li_id, 336, @pi_scope_id, 0, 0
        IF @@ERROR <> 0 RETURN 1 -- Failure
    END
    ELSE
    BEGIN
        UPDATE objects SET scope_id = @pi_scope_id
        WHERE object_type = 336 AND object_id = @li_id
        IF @@ERROR <> 0 RETURN 1 -- Failure
    END
END
GO

BEGIN
    SET NOCOUNT ON;
  
    -- Labor is the preferred spelling in USA, in the rest of the world it might be Labour.
    EXEC ebps_populate_cost_category 1, 1, 'Labor', 'Cost of Labor'
    EXEC ebps_populate_cost_category 1, 1, 'Materials', 'Cost of Materials'
END
GO

EXEC ebps_drop 'procedure', 'ebps_populate_cost_category'
GO

GO


-- =====================================================================
-- FILE: coversheet_file_cntr_template.sql
-- =====================================================================

-----------------------------------------------------------------------------------------
-- $Copyright: (c) 2019 Bentley Systems, Incorporated. All rights reserved. $
-----------------------------------------------------------------------------------------

/*
Description
   This populate procedure is used to populate a CoverSheet file container class and a CoverSheet file container template.
   We want to hide these default classes and templates, but currently we don't have the hide functionality needed to do that.
*/

EXEC ebps_drop 'procedure', 'ebps_pop_coversheet_file_cntr'
GO
CREATE PROCEDURE ebps_pop_coversheet_file_cntr
(
   @pi_called_by INT
)
AS
DECLARE
   @li_error           INT,
   @li_class_id        INT,
   @li_template_id     INT,
   @ls_template_id     NVARCHAR(255),
   @li_document_id     INT,
   @li_hide_flags      INT,
   @li_lock_flags      INT,
   @ls_copy_no         NVARCHAR(100),
   @li_copy_id         INT
BEGIN   
   -- Check if the 'CoverSheetFileContainerTemplateId' setting already exists
   IF(COALESCE(dbo.ebf_setting_i( 1, 20, 'CoverSheetFileContainerTemplateId', 0, @pi_called_by ),0) < 1 )
   BEGIN
      SELECT @li_class_id = class_id FROM class_objects WHERE group_id = 1 AND code = N'CoverSheetFileContainerClass';    

      -- CoverSheet File container class
      IF COALESCE(@li_class_id, 0) < 1
      BEGIN
         EXEC @li_error = ebp_add_class 1, NULL, 'CoverSheetFileContainerClass','CoverSheet File Container Class', 'CoverSheet class for creating file container templates for Distribution orders and Transmittals', 'F', NULL, '0', 'V', 'N', @pi_called_by, @li_class_id OUT
         IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure
         -- Add hide and lock flags so the above class can't be viewed, modified or deleted.       
         EXEC @li_error = ebp_chg_object @li_class_id, 185, N'00000000-0000-0000-0000-000000000000', -1, -1, -1, 8, 18, @pi_called_by
         IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure

         -- Create a template of the above file container class
        EXEC @li_error = ebp_add_template 'CoverSheetFileContainerTemplate', 'CoverSheet template for creating file containers', 'CS-#######', @li_class_id, 0, 0, 0, N'N', NULL, NULL, 0, @pi_called_by, @li_template_id OUT
        IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure      
        -- Approve template
        EXEC @li_error = ebp_chg_template @li_template_id, '%', '%','%', -1,'A', -1, -1, '%','%', '%',-1, @pi_called_by
        IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure
      
        -- Add hide and lock flags so the above template can't be viewed, modified or deleted.       
        EXEC @li_error = ebp_chg_object @li_template_id, 188, N'00000000-0000-0000-0000-000000000000', -1, -1, -1, 8, 18, @pi_called_by
        IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure
      
        SELECT @li_document_id = object_id FROM templates WHERE object_type = 3 AND template_id = @li_template_id 

        -- set hide_flags/lock_flags
        SET @li_hide_flags = 8 -- (Internal, hide the document)
        SET @li_lock_flags = 2|16 -- may not modify | may not delete
        EXEC @li_error = ebp_chg_object @li_document_id, 3, N'00000000-0000-0000-0000-000000000000', -1, -1, -1, @li_hide_flags, @li_lock_flags, @pi_called_by
        IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure

        -- add one document copy
        EXEC @li_error = ebp_get_next_no2 N'ESOURCE_####', 36, N'copy_no', N'%', N'%', @li_document_id, -1, 1, @ls_copy_no OUTPUT
        IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure

        EXEC @li_error = ebp_add_doc_copy @li_document_id, @ls_copy_no, N'M', NULL, 1, 0, 1, N'A', NULL, @pi_called_by, @li_copy_id OUTPUT
        IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure 
        
        SET @ls_template_id = CONVERT(VARCHAR, @li_template_id);
        -- Set the template id as the CoverSheet file container template id. 
        INSERT INTO settings (setting_id, object_id, value)
        SELECT a.setting_id, 1, @ls_template_id
        FROM setting_defs a WHERE a.object_type = 20 AND a.code = N'CoverSheetFileContainerTemplateId'
        IF @@ERROR <> 0 RETURN 1 -- Failure
      END
   END
END
GO

