/*
Description
   Populates things required by the Import and Export engine
*/

BEGIN
   -- Settings ---
   --Switch, enabling import/export processing, by default - disabled.
   EXEC ebps_add_setting_def 20, N'ImportExportEnabled', N'Enable Import/Export service', 1, N'N', N'Y', N'Y', 2, NULL
   EXEC ebp_set_setting 'ImportExportEnabled', 1, 20, 1, 'N', 1

   -- Methods ---
   IF NOT EXISTS ( SELECT 1 FROM method_info WHERE code_ref = N'ebp_get_export_data' )
   BEGIN
      DECLARE @li_method_id INT
      EXEC ebp_add_method_info 'ebp_get_export_data',
                               1, -- Indicates a Stored Procedure
                               'N', -- Y if the method should run in a transaction, N should only be used when the method will make no updates and only retrieve data.
                               'ebp_get_export_data',
                               1, -- Option 1 registeres parameters, 0 to register them manually
                               1, -- Session Id used to make the call
                              @li_method_id OUT

      EXEC ebp_chg_parameter_info @li_method_id, N'pi_called_by', N'pi_called_by', N'INT', N'Y', N'N', N'N', '$Session.Id', N'Y', 1
   END

   IF NOT EXISTS ( SELECT 1 FROM method_info WHERE code_ref = N'ebp_get_exp_comments_data' )
   BEGIN
      DECLARE @li_method_id1 INT
      EXEC ebp_add_method_info 'ebp_get_exp_comments_data',
                               1, -- Indicates a Stored Procedure
                               'N', -- Y if the method should run in a transaction, N should only be used when the method will make no updates and only retrieve data.
                               'ebp_get_exp_comments_data',
                               1, -- Option 1 registeres parameters, 0 to register them manually
                               1, -- Session Id used to make the call
                              @li_method_id1 OUT

      EXEC ebp_chg_parameter_info @li_method_id1, N'pi_called_by', N'pi_called_by', N'INT', N'Y', N'N', N'N', '$Session.Id', N'Y', 1
   END

END
