EXEC ebps_drop 'procedure', 'ebps_populate_db_events'
GO
CREATE PROCEDURE ebps_populate_db_events
(
   @pi_event_id    INT,
   @ps_name        NVARCHAR(255),
   @ps_description NVARCHAR(2000),
   @ps_param_list  NVARCHAR(2000),
   @ps_bind_args   NVARCHAR(2000)
)
AS
BEGIN
   SET NOCOUNT ON;

   INSERT INTO db_events ( event_id, name, description, param_list, bind_args )
   SELECT @pi_event_id, @ps_name, @ps_description, @ps_param_list, @ps_bind_args
   WHERE NOT EXISTS ( SELECT 1 FROM db_events WHERE event_id = @pi_event_id )
   IF @@ERROR <> 0 RETURN 1 -- Failure

   UPDATE db_events SET name = @ps_name, description = @ps_description,
                        param_list = @ps_param_list, bind_args = @ps_bind_args
   WHERE event_id = @pi_event_id
   IF @@ERROR <> 0 RETURN 1 -- Failure
END
GO

