-- =====================================================================
-- FILE: default_file_container_template.sql
-- =====================================================================

-----------------------------------------------------------------------------------------
-- $Copyright: (c) 2018 Bentley Systems, Incorporated. All rights reserved. $
-----------------------------------------------------------------------------------------

/*
Description
   This populate procedure is used to populate a default file container class and a default file container template.
   We want to hide these default classes and templates, but currently we don't have the hide functionality needed to do that.
*/

EXEC ebps_drop 'procedure', 'ebps_pop_file_container'
GO
CREATE PROCEDURE ebps_pop_file_container
(
   @pi_called_by INT
)
AS
DECLARE
   @li_error           INT,
   @li_parent_class_id INT,
   @li_child_class_id  INT,
   @li_template_id     INT,
   @ls_template_id     NVARCHAR(255)
BEGIN   
   -- Check if the 'DefaultFileContainerTemplateId' setting already exists
   IF(COALESCE(dbo.ebf_setting_i( 1, 20, 'DefaultFileContainerTemplateId', 0, @pi_called_by ),0) < 1 )
   BEGIN
      SELECT @li_parent_class_id = class_id FROM class_objects WHERE group_id = 1 AND code = N'DEFAULT';
      SELECT @li_child_class_id = class_id FROM class_objects WHERE group_id = 1 AND code = N'DefaultFileContainerClass';

      -- Create a default system class if one doesn't already exist then create a child class of sys type file container 
      IF COALESCE(@li_parent_class_id, 0) < 1
      BEGIN
         -- Default System Class.
         EXEC @li_error = ebp_add_class 1, NULL, N'DEFAULT', N'Default System Class', N'Default System Class', 'U', NULL, NULL, 'V', 'N', @pi_called_by, @li_parent_class_id OUT
         IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure
         -- Add hide and lock flags so the above class can't be seen or modified by users.       
         EXEC @li_error = ebp_chg_object @li_parent_class_id, 185, N'00000000-0000-0000-0000-000000000000', -1, -1, -1, 18, 18, @pi_called_by
         IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure
      END

      -- Default File container class child of DEFAULT class.
      IF COALESCE(@li_child_class_id, 0) < 1
      BEGIN
         EXEC @li_error =ebp_add_class 1, @li_parent_class_id,'DefaultFileContainerClass','Default File Container Class', 'Default class for creating file container templates','F', NULL, '0','V', 'N',@pi_called_by, @li_child_class_id OUT
         IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure
         -- Add hide and lock falgs so the above class can't be seen or modified by users.       
         EXEC @li_error = ebp_chg_object @li_child_class_id, 185, N'00000000-0000-0000-0000-000000000000', -1, -1, -1, 18, 18, @pi_called_by
         IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure
      END

       -- Create a template of the above file container class
      EXEC @li_error = ebp_add_template 'DefaultFileContainerTemplate', 'Default template for creating file containers', 'D-#######', @li_child_class_id, 0, 0, 0, N'N', NULL, NULL, 0, @pi_called_by, @li_template_id OUT
      IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure      
      -- Approve template
      EXEC @li_error = ebp_chg_template @li_template_id, '%', '%','%', -1,'A', -1, -1, '%','%', '%',-1, @pi_called_by
      IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure
      
      -- Add hide and lock falgs so the above template can't be seen or modified by users.       
      EXEC @li_error = ebp_chg_object @li_template_id, 188, N'00000000-0000-0000-0000-000000000000', -1, -1, -1, 18, 18, @pi_called_by
      IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure
      
      SET @ls_template_id = CONVERT(VARCHAR, @li_template_id);
      -- Set the template id as the default file container template id. 
      INSERT INTO settings (setting_id, object_id, value)
      SELECT a.setting_id, 1, @ls_template_id
      FROM setting_defs a WHERE a.object_type = 20 AND a.code = N'DefaultFileContainerTemplateId'
      IF @@ERROR <> 0 RETURN 1 -- Failure
   END
END
GO

BEGIN
   EXEC ebps_pop_file_container 1  -- Current Session set to admin session
END  
GO

EXEC ebps_drop 'procedure', 'ebps_pop_file_container'
GO

GO


-- =====================================================================
-- FILE: dsa_query_templates.sql
-- =====================================================================

-----------------------------------------------------------------------------------------
-- $Copyright: (c) 2017 Bentley Systems, Incorporated. All rights reserved. $
-----------------------------------------------------------------------------------------

BEGIN
   --if the DefaultLanguage is set to other than English, then dsa_query_templates names are in that language. So compare names in English before inserting.
   SET NOCOUNT ON;
   
   INSERT INTO dsa_query_templates( name, description, sql_query, monitor )
   SELECT 
      N'Corrective Action Active WO Task', 
      N'Will return all persons and the events they are allowed to work on given that the Event is of a specific class, linked to a work order (as subject data) and attached to a Active task with a specific name.',
      N'SELECT b.event_id object_id, 94 object_type, c.person_id
      FROM work_references a
      INNER JOIN events b
      ON a.child_id = b.event_id
      AND a.child_type = 94 
      AND a.subject_data = ''Y'' 
      INNER JOIN work_steps c
      ON a.parent_id = c.wo_id
      AND a.parent_type = 140
      AND c.status = ''A''
      AND c.ws_number = ''' + NCHAR(36) + N'(Work Task Name)''
      INNER JOIN class_objects d 
      ON d.class_id = b.class_id
      AND d.code = ''' + NCHAR(36) + N'(Event Class Code)''
      INNER JOIN class_groups e 
      ON e.group_id = d.group_id
      AND e.object_type = 94',
         N'<monitors>
      <monitor><object_type>142</object_type><action_type>29</action_type></monitor>
      <monitor><object_type>142</object_type><action_type>30</action_type></monitor>
      <monitor><object_type>142</object_type><action_type>31</action_type></monitor>
      </monitors>'
      WHERE NOT EXISTS ( SELECT 1 FROM dsa_query_templates WHERE name = dbo.ebf_language_translate(1033, dbo.ebf_setting_i( 1, 20, 'DefaultLanguage', '1033', 1 ) , N'Corrective Action Active WO Task') )

   INSERT INTO dsa_query_templates( name, description, sql_query, monitor )
   SELECT
      N'Corrective Action WO Creation', 
      N'Will return all persons allowed to work on given that the Event when it is linked to a work order (as subject data) and that WO is not Active.',
      N'SELECT a.child_id object_id, 94 object_type, c.person_id
      FROM work_references a
      INNER JOIN work_orders b
      ON a.parent_id = b.wo_id
      AND a.parent_type = 140
      AND a.child_type = 94
      AND a.subject_data = ''Y''
      AND b.approval <> ''A''
      INNER JOIN object_audit_info c
      ON b.wo_id = c.object_id
      AND c.object_type = 140
      AND c.action_type = 1',
      N'<monitors>
      <monitor><object_type>140</object_type><action_type>1</action_type></monitor>
      <monitor><object_type>140</object_type><action_type>2</action_type></monitor>
      </monitors>'
      WHERE NOT EXISTS ( SELECT 1 FROM dsa_query_templates WHERE name = dbo.ebf_language_translate(1033, dbo.ebf_setting_i( 1, 20, 'DefaultLanguage', '1033', 1 ) , N'Corrective Action WO Creation') )      

   INSERT INTO dsa_query_templates( name, description, sql_query, monitor )
   SELECT
      N'Active CAP Task', 
      N'Will return Event objects and the persons allowed to work on them, given that the Event is linked to a Work Order (as subject data) and that the Persons tasks is Active.',
      N'SELECT a.child_id object_id, 94 object_type, b.person_id
      FROM work_references a
      INNER JOIN work_steps b
      ON a.parent_id = b.wo_id
      AND a.parent_type = 140
      AND a.subject_data = ''Y''
      AND a.child_type = 94
      AND b.status = ''A''',
      N'<monitors>
      <monitor><object_type>142</object_type><action_type>29</action_type></monitor>
      <monitor><object_type>142</object_type><action_type>30</action_type></monitor>
      <monitor><object_type>142</object_type><action_type>31</action_type></monitor>
      </monitors>'
      WHERE NOT EXISTS ( SELECT 1 FROM dsa_query_templates WHERE name = dbo.ebf_language_translate(1033, dbo.ebf_setting_i( 1, 20, 'DefaultLanguage', '1033', 1 ) , N'Active CAP Task') )       
END
