-- =====================================================================

-----------------------------------------------------------------------------------------
-- $Copyright: (c) Bentley Systems, Incorporated. All rights reserved. $
-----------------------------------------------------------------------------------------

EXEC ebps_drop 'procedure', 'ebps_pop_engine'
GO
CREATE PROCEDURE ebps_pop_engine
(
   @ps_name        NVARCHAR(255),
   @ps_description NVARCHAR(2000),
   @pi_iface_id    INT,
   @ps_code_ref    NVARCHAR(255),
   @ps_assembly    NVARCHAR(255),
   @pi_timeout     INT,
   @pi_engine_id   INT OUTPUT
)
AS
BEGIN
   SET NOCOUNT ON;

   IF @pi_iface_id <> 2
   BEGIN
      EXEC ebp_raise_error N'Populate/Engines.sql should only register database engines', 1
      RETURN 1; -- Failure
   END

   SELECT @pi_engine_id = COALESCE( MAX( engine_id ), 0 ) FROM engines WITH (NOLOCK)
   WHERE iface_id = @pi_iface_id AND UPPER( code_ref ) = UPPER( @ps_code_ref ) AND
   UPPER( COALESCE( assembly, N'()' ) ) = UPPER( COALESCE( @ps_assembly, N'()' ) ) -- special N'()' is just to be consistent with Oracle version.

   IF @pi_engine_id = 0 -- Engine is not registered
   BEGIN
      EXEC ebp_add_engine @ps_name, @ps_description, @pi_iface_id, @ps_code_ref, @ps_assembly, @pi_timeout, 1, @pi_engine_id OUT
   END

   RETURN 0 -- Success
END
GO

/*
   The 'name' column must be a valid stored procedure name (Name is limited to 30 chars).
   The 'engine_id' column refers to an existing engine.
   The 'type' column may be any of the following values:
      1 - PRE_ENGINE_ACTION  - Executes procedure in its own transaction before the main engine
      2 - BEFORE_ENGINE      - Executes procedure in the same transaction as the engine but before the main engine
      3 - AFTER_ENGINE       - Executes procedure in the same transaction as the engine but after the main engine
      4 - POST_ENGINE_ACTION - Executes procedure in its own transaction after the main engine
      5 - ERROR_HANDLER      - Executes if execution encountered an error
      6 - ON_ENGINE_FINALIZE - Executes at the end of execution even if an error occurred

   The provided values will be registered in 'engine_procedures' table.
   */
EXEC ebps_drop 'procedure', 'ebps_pop_engine_procedure'
GO
CREATE PROCEDURE ebps_pop_engine_procedure
(
   @ps_name      NVARCHAR(30),
   @pi_engine_id INT,
   @pi_type      INT
)
AS
DECLARE
   @li_error INT
BEGIN
   SET NOCOUNT ON;

   -- Create if it does not exist
   IF NOT EXISTS( SELECT 1 FROM engine_procedures WITH(NOLOCK) WHERE UPPER(name) = UPPER(@ps_name) AND engine_id = @pi_engine_id AND type = @pi_type )
   BEGIN
      EXEC @li_error = ebp_add_engine_procedure @ps_name, @pi_engine_id, @pi_type, 1
      IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1
   END

   RETURN 0 -- Success
END
GO

DECLARE
   @li_engine_id INT
BEGIN
   -- Register 'Add Prototype Engine' and its default procedures
   EXEC ebps_pop_engine N'Add Prototype Engine', N'Used to asynchronously call Add Prototype procedure', 2, N'ebp_add_prototype_engine', NULL, 0, @li_engine_id OUT
   EXEC ebps_pop_engine_procedure N'ebp_prototype_pre_engine', @li_engine_id, 1 -- PRE_ENGINE_ACTION
   EXEC ebps_pop_engine_procedure N'ebp_prototype_pre_engine', @li_engine_id, 6 -- ON_ENGINE_FINALIZE

   -- Register 'Merge Prototype Engine' and its default procedures
   EXEC ebps_pop_engine N'Merge Prototype Engine', N'Used to asynchronously call Merge Prototype procedure', 2, N'ebp_merge_prototype_engine', NULL, 0, @li_engine_id OUT
   EXEC ebps_pop_engine_procedure N'ebp_prototype_pre_engine', @li_engine_id, 1 -- PRE_ENGINE_ACTION
   EXEC ebps_pop_engine_procedure N'ebp_prototype_pre_engine', @li_engine_id, 6 -- ON_ENGINE_FINALIZE
END
GO

-- Clean up.
EXEC ebps_drop 'procedure', 'ebps_pop_engine'
EXEC ebps_drop 'procedure', 'ebps_pop_engine_procedure'
GO

GO


