CREATE PROCEDURE ebps_populate_systems
(
   @pi_system_id           INT,
   @ps_name                NVARCHAR(255),
   @ps_description         NVARCHAR(2000),
   @pc_enabled             CHAR(1),
   @ps_on_object_adding    NVARCHAR(32),
   @ps_on_object_added     NVARCHAR(32),
   @ps_on_object_deleting  NVARCHAR(32),
   @ps_on_object_deleted   NVARCHAR(32),
   @ps_on_object_changing  NVARCHAR(32),
   @ps_on_object_changed   NVARCHAR(32)
)
AS
BEGIN
   SET NOCOUNT ON;
   IF EXISTS ( SELECT 1 FROM external_systems WHERE system_id = @pi_system_id ) RETURN 0

   INSERT INTO [dbo].[external_systems]
           ( [system_id]
           , [name]
           , [description]
           , [is_enabled]
           , [on_object_adding]
           , [on_object_added]
           , [on_object_deleting]
           , [on_object_deleted]
           , [on_object_changing]
           , [on_object_changed] )
     VALUES
           (
             @pi_system_id
           , @ps_name
           , @ps_description
           , @pc_enabled
           , @ps_on_object_adding
           , @ps_on_object_added
           , @ps_on_object_deleting
           , @ps_on_object_deleted
           , @ps_on_object_changing
           , @ps_on_object_changed )
   IF @@ERROR <> 0 RETURN 1 -- Failure
   RETURN 0 -- Success
END
GO
BEGIN
   -- Populate the "well known" External Systems.
   EXEC ebps_populate_systems 1, N'eB','eB External Objects', 'Y', NULL, NULL, NULL, NULL, NULL, NULL
