/*
Description
   There MUST always be a root 'System' Folder with gui_folder_id = 1.
*/
BEGIN
   SET NOCOUNT ON;
   
   INSERT INTO gui_folders( gui_folder_id, namespace_id, name )
   SELECT 1, 1, 'System Root' WHERE NOT EXISTS( SELECT 1 FROM gui_folders WHERE gui_folder_id = 1 AND namespace_id = 1 )

   UPDATE gui_folders SET name = 'System Root'
   WHERE gui_folder_id = 1 AND namespace_id = 1

   -- Add as an Object (Scope becomes 'Global')
   -- lock_flags = 16 to prevent anyone deleting it (Modify will be allowed because we'd still want users to configure security against the folder and there will be logic specific to this folder that prevents renaming it)
   INSERT INTO objects( object_id, object_type, scope_id, hide_flags, lock_flags )
   SELECT 1, 170, 1, 0, 16
   WHERE NOT EXISTS ( SELECT 1 FROM objects WHERE object_id = 1 AND object_type = 170 )
END
