-----------------------------------------------------------------------------------------

/*
Description
   Adds Bentley IMS
*/
EXEC ebps_drop 'procedure', 'ebps_populate_id_providers'
GO
CREATE PROCEDURE ebps_populate_id_providers
(   
   @ps_name                   NVARCHAR(255),
   @ps_claim_issuer           NVARCHAR(50),
   @ps_claim_type             NVARCHAR(200),
   @pi_hide_flags             INT
)
AS
DECLARE
   @li_identity_provider_id   INT
BEGIN
   SET NOCOUNT ON;

   IF EXISTS (SELECT 1 FROM identity_providers WHERE name = @ps_name)
   BEGIN
      UPDATE identity_providers SET claim_issuer = @ps_claim_issuer, claim_type = @ps_claim_type WHERE name = @ps_name
      IF @@ERROR <> 0 RETURN 1 -- Failure
   END
   ELSE
   BEGIN
      SET @li_identity_provider_id = (SELECT MAX(identity_provider_id) FROM identity_providers) + 1
      IF @li_identity_provider_id IS NULL
      BEGIN
         SET @li_identity_provider_id = 1
      END

      INSERT INTO identity_providers (identity_provider_id, name, claim_issuer, claim_type) 
      SELECT @li_identity_provider_id, @ps_name, @ps_claim_issuer, @ps_claim_type
      IF @@ERROR <> 0 RETURN 1 -- Failure

      INSERT INTO objects(object_id, object_type, scope_id, hide_flags, lock_flags, date_added, added_by, date_changed, changed_by) SELECT @li_identity_provider_id, 326, 1, @pi_hide_flags, 0, GETDATE(), 1, GETDATE(), 1
      IF @@ERROR <> 0 RETURN 1 -- Failure
   END

   RETURN 0
END
GO

BEGIN
   SET NOCOUNT ON;
   EXEC ebps_populate_id_providers N'Bentley IMS', N'https://imsoidc.bentley.com', N'email', 0
   EXEC ebps_populate_id_providers N'Bentley IMS QA', N'https://qa-imsoidc.bentley.com', N'email', 8
   EXEC ebps_populate_id_providers N'Basic ALIM Authentication', N'eB', N'http://schemas.bentley.com/ws/2011/03/identity/claims/ebusername', 8
   EXEC ebps_populate_id_providers N'Windows Authentication', N'AD AUTHORITY', N'http://schemas.xmlsoap.org/ws/2005/05/identity/claims/name', 8
END
GO

