-- =====================================================================
-- FILE: interop_methods.sql
-- =====================================================================

-----------------------------------------------------------------------------------------
-- $Copyright: (c) 2016 Bentley Systems, Incorporated. All rights reserved. $
-----------------------------------------------------------------------------------------

/*
Description
   Enables required base_types to populate GUID values
*/
BEGIN
   IF EXISTS ( SELECT 1 FROM base_types WITH (NOLOCK) WHERE object_type = 1 AND has_guid = N'N' )
   BEGIN
      EXEC ebp_chg_base_type 1, N'Y', 1 -- Item
   END

   IF EXISTS ( SELECT 1 FROM base_types WITH (NOLOCK) WHERE object_type = 2 AND has_guid = N'N' )
   BEGIN
      EXEC ebp_chg_base_type 2, N'Y', 1 -- Virtual Item
   END

   IF EXISTS ( SELECT 1 FROM base_types WITH (NOLOCK) WHERE object_type = 3 AND has_guid = N'N' )
   BEGIN
      EXEC ebp_chg_base_type 3, N'Y', 1 -- Document
   END

