-- This updates federation guid values for interoperability and SyncSites
BEGIN
   DECLARE @li_method_id INT
   SELECT @li_method_id = method_id FROM method_info WHERE code_ref = N'ebp_chg_interop_object'
   IF @li_method_id > 0
   BEGIN
      EXEC ebp_del_method_info @li_method_id, 1
   END

   EXEC ebp_add_method_info 'ebp_chg_interop_object',
                            1, -- Indicates a Stored Procedure
                            'Y', -- Y if the method should run in a transaction, N should only be used when the method will make no updates and only retrieve data.
                            'ebp_chg_interop_object',
                            1, -- Option 1 registeres parameters, 0 to register them manually
                            1, -- Session Id used to make the call
                           @li_method_id OUT

   EXEC ebp_chg_parameter_info @li_method_id, N'pi_session_id', N'pi_session_id', N'INT', N'Y', N'N', N'N', '$Session.Id', N'Y', 1
END
