EXEC ebps_drop 'procedure', 'ebps_populate_intrinsic_prop'
GO
CREATE PROCEDURE ebps_populate_intrinsic_prop
(
   @ps_char_name             NVARCHAR(100),
   @ps_char_data_type        NVARCHAR(2),
   @pi_char_length           INT,
   @pi_no_dec_places         INT,
   @ps_char_base_unit        NVARCHAR(255),
   @pi_object_type           INT,
   @ps_change_controlled     CHAR(1),
   @ps_mandatory             CHAR(1),
   @ps_multi_valued          CHAR(1),
   @ps_mask                  NVARCHAR(255),
   @ps_lookup                CHAR(1),
   @ps_data_source           NVARCHAR(255),
   @ps_edit_query            NVARCHAR(MAX),
   @ps_search_query          NVARCHAR(MAX),
   @ps_has_value_description CHAR(1),
   @pi_state_machine_id      INT,
   @pi_data_type_constraints INT,
   @pi_perm_mask             INT
)
AS
DECLARE
   @li_error             INT,
   @li_attrib_id         INT
BEGIN
   SET NOCOUNT ON;

    -- Check Namespace is Valid
   IF dbo.ebf_session_namespace_id ( 1 ) <> 1
   BEGIN
      EXEC ebp_raise_error N'<The current Namespace is not set to ''Global'' for the ''ADMIN'' user.>', 1
   END

   -- Check for an existing row using the unique/ak
   SELECT @li_attrib_id = char_id FROM characteristics WITH (NOLOCK) WHERE namespace_id = 1 AND char_name = @ps_char_name AND object_type = @pi_object_type;
   IF @@ROWCOUNT = 0
   BEGIN
      -- new row, request new PK then insert
      EXEC @li_error = ebp_add_characteristic @ps_char_name, @ps_char_data_type ,@pi_char_length, @pi_no_dec_places, @ps_char_base_unit, @pi_object_type, @ps_change_controlled, @ps_mandatory, @ps_multi_valued, @ps_mask, @ps_lookup, @ps_data_source, @ps_edit_query, @ps_search_query, @ps_has_value_description, @pi_state_machine_id, @pi_data_type_constraints, @pi_perm_mask, 1, @li_attrib_id OUTPUT
      IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure 
       
      -- Set the Intrinsic column to Y
      UPDATE characteristics SET is_intrinsic = N'Y'
      WHERE char_id = @li_attrib_id
      IF @@ERROR <> 0 RETURN 1 -- Failure
      
      -- Don't need audit property defs for Intrinsic. Also, it's causing duplicate entries for Document/VIG.
      DELETE FROM audit_property_defs WHERE attrib_id = @li_attrib_id
   END
   ELSE
   BEGIN          
      -- Set the Intrinsic column to N (just to work around the validation in ebp_chg_characteristic)
      UPDATE characteristics SET is_intrinsic = N'N'
      WHERE char_id = @li_attrib_id
      IF @@ERROR <> 0 RETURN 1 -- Failure

      -- Update existing entry
      EXEC @li_error = ebp_chg_characteristic @li_attrib_id, @ps_char_name, @ps_char_data_type, @pi_char_length, @pi_no_dec_places, @ps_char_base_unit, @ps_change_controlled, @ps_mandatory, @ps_multi_valued, @ps_mask, @ps_lookup, @ps_data_source, @ps_edit_query, @ps_search_query, @ps_has_value_description, @pi_state_machine_id, @pi_data_type_constraints, @pi_perm_mask, 1
      IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure 

      -- Set the Intrinsic column to Y
      UPDATE characteristics SET is_intrinsic = N'Y'
      WHERE char_id = @li_attrib_id
      IF @@ERROR <> 0 RETURN 1 -- Failure
   END  
   RETURN 0 -- Success
END
GO

EXEC ebps_drop 'procedure', 'ebps_pop_state_machine_prop'
