CREATE PROCEDURE ebps_pop_state_machine_prop
   (
   @ps_char_name            NVARCHAR(100),
   @pi_object_type          INT,
   @ps_state_machine_name   NVARCHAR(100)
   )
AS
DECLARE
   @li_state_machine_id    INT;
BEGIN
   SET NOCOUNT ON;
     --Add state machine
   SELECT @li_state_machine_id = state_machine_id FROM state_machines WITH(NOLOCK) WHERE name = @ps_state_machine_name;

   IF COALESCE(@li_state_machine_id, 0) =0 
   BEGIN
      EXEC ebp_raise_error_1  N'<State Machine ''{0}'' Not Found. Please make sure that Populate\state_machines script is called before this script.>', @ps_state_machine_name, null, null, 1;
   END;

   EXEC ebps_populate_intrinsic_prop @ps_char_name, N'ST', 100, NULL, NULL, @pi_object_type, N'N', N'N', N'N', NULL, N'N', NULL, NULL, NULL, N'N', @li_state_machine_id, 0, 0 ;
   
   RETURN 0;
   END
GO


