BEGIN
   SET NOCOUNT ON;
   DELETE FROM char_data WHERE char_id IN ( SELECT char_id FROM characteristics WITH (NOLOCK) WHERE is_intrinsic = N'Y' )

   DELETE FROM audit_property_defs WHERE attrib_id IN ( SELECT char_id FROM characteristics WITH (NOLOCK) WHERE is_intrinsic = N'Y' )

   --add the edit_query + search query for all intrinsic attributes that have values in the static_lookup table
   UPDATE characteristics SET lookup = N'Y', data_source = N'provider=(local);', edit_query = lt.query, search_query = lt.query
   FROM characteristics c INNER JOIN
   (
      SELECT b.object_type, otname, l.char_name, N'provider=(local);' datasource,
         N'SELECT LOOKUP_KEY VALUE, LOOKUP_VALUE VALUE_DESCRIPTION, N''N'' OBSOLETE FROM STATIC_LOOKUPS WHERE NAME=N''' + lookupName + ''' ORDER BY VALUE' query
      FROM
         (SELECT 
            SUBSTRING ( name ,1 , CHARINDEX('.', name)-1 
         ) otname, 
         'Intrinsic/' + SUBSTRING ( name ,CHARINDEX('.', name)+1 , 10000 
         ) char_name,
         name lookupName FROM static_lookups) l, 
         base_types b
      WHERE 
         l.otname = b.name
      GROUP BY otname, char_name, lookupName, b.object_type
   ) lt
   ON c.char_name = lt.char_name and lt.object_type = c.object_type
   WHERE c.is_intrinsic = N'Y'

END
GO

