/*
Description
   Pre-populate system jobtypes

   See Procedures\ebp_add_jobtype.sql for valid service_id's

Specification
   TODO
*/
EXEC ebps_drop 'procedure', 'ebps_populate_jobtypes'
GO
CREATE PROCEDURE ebps_populate_jobtypes
(
   @pi_jobtype_id  INT,
   @pi_service_id  INT,
   @ps_description NVARCHAR(2000)
)
AS
BEGIN
   SET NOCOUNT ON;

   INSERT INTO jobtypes ( jobtype_id, service_id, description )
   SELECT @pi_jobtype_id, @pi_service_id, @ps_description
   WHERE NOT EXISTS( SELECT 1 FROM jobtypes WHERE jobtype_id = @pi_jobtype_id )
   IF @@ERROR <> 0 RETURN 1 -- Failure

   UPDATE jobtypes SET service_id = @pi_service_id, description = @ps_description
   WHERE jobtype_id = @pi_jobtype_id
   IF @@ERROR <> 0 RETURN 1 -- Failure

   -- Add as an Object (Scope becomes 'Global')
   -- lock_flags=2|16 because these are system types that can't be modified or deleted
   INSERT INTO objects ( guid, object_id, object_type, scope_id, hide_flags, lock_flags, date_added, added_by, date_changed, changed_by )
   SELECT NULL, @pi_jobtype_id, 233, 1, 0, 18, GETDATE(), 1, GETDATE(), 1
   WHERE NOT EXISTS ( SELECT 1 FROM objects WHERE object_id = @pi_jobtype_id AND object_type = 233 )
   IF @@ERROR <> 0 RETURN 1 -- Failure

   RETURN 0 -- Success
END
GO
BEGIN
   SET NOCOUNT ON;

   EXEC ebps_populate_jobtypes 1, 1, N'Generic'
   EXEC ebps_populate_jobtypes 2, 7, N'SharePoint'
   EXEC ebps_populate_jobtypes 3, 2, N'Ftr'
   EXEC ebps_populate_jobtypes 4, 3, N'Email'
   EXEC ebps_populate_jobtypes 5, 4, N'Print'
   EXEC ebps_populate_jobtypes 6, 5, N'Publish'
   EXEC ebps_populate_jobtypes 7, 6, N'Render'
   EXEC ebps_populate_jobtypes 8, 8, N'Snapshot Capture'
   EXEC ebps_populate_jobtypes 9, 9, N'Document Creation'
   EXEC ebps_populate_jobtypes 10, 1,N'Active Directory'
   EXEC ebps_populate_jobtypes 11, 1, N'Bulk Transaction'
   EXEC ebps_populate_jobtypes 12, 1, N'Asynchronous Automation'
   EXEC ebps_populate_jobtypes 14, 1, 'Copy Object'
   -- service_id 10 is the 'Sync' service
   -- service_id 10 is the 'Storage' service
   EXEC ebps_populate_jobtypes 15, 11, 'Interoperability'
   EXEC ebps_populate_jobtypes 16, 1, 'Distribution'
   EXEC ebps_populate_jobtypes 17, 5, 'Publisher - File Download'
END
GO
EXEC ebps_drop 'procedure', 'ebps_populate_jobtypes'
