   CLOSE lcur_populate
   DEALLOCATE lcur_populate

   -- SharePoint
   DECLARE lcur_populate CURSOR LOCAL FAST_FORWARD FOR
   SELECT 'ebp_add_language_text N''' + REPLACE(name,CHAR(39),char(39)+CHAR(39)) + ''',NULL,NULL,''Y'',N''15.5.1'',1' FROM sharepoint_items WHERE item_id IN (1,2)
   OPEN lcur_populate
   FETCH NEXT FROM lcur_populate INTO @ls_query
   WHILE (@@FETCH_STATUS = 0)
   BEGIN
      EXEC sp_executesql @ls_query       
      FETCH NEXT FROM lcur_populate INTO @ls_query
   END
   CLOSE lcur_populate
   DEALLOCATE lcur_populate

   DECLARE lcur_populate CURSOR LOCAL FAST_FORWARD FOR
   SELECT 'ebp_add_language_text N''' + REPLACE(description,CHAR(39),char(39)+CHAR(39)) + ''',NULL,NULL,''Y'',N''15.5.1'',1' FROM sharepoint_items WHERE item_id IN (1,2)
   OPEN lcur_populate
   FETCH NEXT FROM lcur_populate INTO @ls_query
   WHILE (@@FETCH_STATUS = 0)
   BEGIN
      EXEC sp_executesql @ls_query       
      FETCH NEXT FROM lcur_populate INTO @ls_query
   END
   CLOSE lcur_populate
   DEALLOCATE lcur_populate

   -- Staticlookup
   DECLARE lcur_populate CURSOR LOCAL FAST_FORWARD FOR
   SELECT 'ebp_add_language_text N''' + REPLACE(lookup_value,CHAR(39),char(39)+CHAR(39)) + ''',NULL,NULL,''Y'',N''15.5.1'',1' FROM static_lookups 
   OPEN lcur_populate
   FETCH NEXT FROM lcur_populate INTO @ls_query
   WHILE (@@FETCH_STATUS = 0)
   BEGIN
      EXEC sp_executesql @ls_query       
