/*
Description
   Populates the languages. 
   
Note
   We use the .NET CultureInfo to get the values by using some code similar to this:
   
     public static void GetCultureInfo()
     {
         System.IO.StringWriter sw = new System.IO.StringWriter();
         sw.WriteLine( "INSERT INTO languages( local_id, code, name, parent_id )" );

         foreach ( CultureInfo ci in CultureInfo.GetCultures( CultureTypes.AllCultures ).OrderBy( p => p.LCID ) )
         {
             if ( ci.LCID == 127 ) continue;
             sw.WriteLine( "SELECT {0}, '{1}', '{2}', {3} UNION ", ci.LCID, ci.IetfLanguageTag, ci.DisplayName, ci.Parent.LCID == 127 ? "NULL" : ci.Parent.LCID.ToString() );
         }
     }   
*/
