-----------------------------------------------------------------------------------------

EXEC ebps_drop 'procedure', 'ebppop_locking_strategy'
GO
CREATE PROCEDURE ebppop_locking_strategy
(
   @pi_method_id       NVARCHAR(100), 
   @pi_object_type     INT,
   @ps_semaphore       NVARCHAR(255)
)
WITH ENCRYPTION
AS
DECLARE
   @li_cnt   INT,
   @ls_name  NVARCHAR(255)
BEGIN 
   SET NOCOUNT ON;
   
   INSERT INTO locking_strategy(method_id, semaphore, object_type)
   SELECT @pi_method_id, @ps_semaphore, @pi_object_type
   WHERE NOT EXISTS(SELECT 1 FROM locking_strategy WHERE method_id = @pi_method_id AND semaphore = @ps_semaphore AND object_type = @pi_object_type)
END
GO

BEGIN
   -- The following is the v15 equivalent behavior
   --EXEC ebppop_locking_strategy N'ebp_add_affected_object', 0, N'ChangeRequest'
   
   --EXEC ebppop_locking_strategy N'ebp_add_document', 0, N'Document'
   --EXEC ebppop_locking_strategy N'ebp_copy_document', 0, N'Document'
   --EXEC ebppop_locking_strategy N'ebp_del_document', 0, N'Document'
   --EXEC ebppop_locking_strategy N'ebp_uprev_document', 0, N'Document' 
     
   --EXEC ebppop_locking_strategy N'ebp_add_dist_item_file', 0, N'DistributionOrder'
   --EXEC ebppop_locking_strategy N'ebp_add_dist_order_document', 0, N'DistributionOrder'
   --EXEC ebppop_locking_strategy N'ebp_add_dist_order_recipient', 0, N'DistributionOrder'
   --EXEC ebppop_locking_strategy N'ebp_add_doc_issue_item', 0, N'DistributionOrder'
   --EXEC ebppop_locking_strategy N'ebp_add_doc_issue_order', 0, N'DistributionOrder'
   --EXEC ebppop_locking_strategy N'ebp_add_transmittal', 0, N'DistributionOrder'
   --EXEC ebppop_locking_strategy N'ebp_add_transmittal_item', 0, N'DistributionOrder'
   --EXEC ebppop_locking_strategy N'ebp_chg_dist_order_recipient', 0, N'DistributionOrder'
   --EXEC ebppop_locking_strategy N'ebp_chg_doc_issue_order', 0, N'DistributionOrder'
   --EXEC ebppop_locking_strategy N'ebp_chg_transmittal', 0, N'DistributionOrder'
   --EXEC ebppop_locking_strategy N'ebp_del_dist_item_file', 0, N'DistributionOrder'
   --EXEC ebppop_locking_strategy N'ebp_del_dist_order_document', 0, N'DistributionOrder'
   --EXEC ebppop_locking_strategy N'ebp_del_dist_order_recipient', 0, N'DistributionOrder'  
    
   --EXEC ebppop_locking_strategy N'ebp_add_doc_copy', 0, N'DocumentCopy'
      
   --EXEC ebppop_locking_strategy N'ebp_add_file', 0, N'File'
   --EXEC ebppop_locking_strategy N'ebp_cancel_checkout', 0, N'File'
   --EXEC ebppop_locking_strategy N'ebp_checkin_doc', 0, N'File'
   --EXEC ebppop_locking_strategy N'ebp_checkout_doc', 0, N'File'
   --EXEC ebppop_locking_strategy N'ebp_checkout_file', 0, N'File'
   --EXEC ebppop_locking_strategy N'ebp_del_file', 0, N'File'
   --EXEC ebppop_locking_strategy N'm3_get_sa_job', 0, N'File'
   --EXEC ebppop_locking_strategy N'm3_request_file_allocation', 0, N'File'
   --EXEC ebppop_locking_strategy N'm3_secure_file', 0, N'File'
   --EXEC ebppop_locking_strategy N'm3_set_sa_job', 0, N'File'
   
   --EXEC ebppop_locking_strategy N'ebp_copy_work_order', 0, N'WorkOrder'
   --EXEC ebppop_locking_strategy N'ebp_work_accept', 0, N'WorkOrder'
   --EXEC ebppop_locking_strategy N'ebp_work_complete', 0, N'WorkOrder'
   --EXEC ebppop_locking_strategy N'ebp_work_skip', 0, N'WorkOrder'
      
   --EXEC ebppop_locking_strategy N'ebp_get_queue_job', 0, N'QueueJob'
   --EXEC ebppop_locking_strategy N'ebp_set_queue_job', 0, N'QueueJob'   
   
   --EXEC ebppop_locking_strategy N'ebp_approve_dist_order', 0, N'DistributionOrder'
   --EXEC ebppop_locking_strategy N'ebp_approve_dist_order', 0, N'Document'
   --EXEC ebppop_locking_strategy N'ebp_approve_dist_order', 0, N'DocumentCopy'
   
   --EXEC ebppop_locking_strategy N'ebp_create_from_template', 3, N'Document'
   --EXEC ebppop_locking_strategy N'ebp_create_from_template', 6, N'ChangeRequest'
   --EXEC ebppop_locking_strategy N'ebp_create_from_template', 25, N'DistributionOrder'
   --EXEC ebppop_locking_strategy N'ebp_create_from_template', 140, N'WorkOrder'
   
   --EXEC ebppop_locking_strategy N'ebp_instantiate_package', 3, N'Document'
   --EXEC ebppop_locking_strategy N'ebp_instantiate_package', 6, N'ChangeRequest'
   --EXEC ebppop_locking_strategy N'ebp_instantiate_package', 25, N'DistributionOrder'
   --EXEC ebppop_locking_strategy N'ebp_instantiate_package', 140, N'WorkOrder'
   
   --EXEC ebppop_locking_strategy N'ebp_approve', 3, N'Document'
   --EXEC ebppop_locking_strategy N'ebp_approve', 6, N'ChangeRequest'
   --EXEC ebppop_locking_strategy N'ebp_approve', 25, N'DistributionOrder'
   --EXEC ebppop_locking_strategy N'ebp_approve', 140, N'WorkOrder'
   
   --EXEC ebppop_locking_strategy N'ebp_add_template', 3, N'Document'
   --EXEC ebppop_locking_strategy N'ebp_add_template', 6, N'ChangeRequest'
   --EXEC ebppop_locking_strategy N'ebp_add_template', 25, N'DistributionOrder'
   --EXEC ebppop_locking_strategy N'ebp_add_template', 140, N'WorkOrder'
   
   -- Special lock for sessions that wants to imply they perform bulk import operations, this allows sessions of this type to prevent deadlocks against
   -- each other without locking other normal transactions
   EXEC ebppop_locking_strategy N'BulkSession', 0, N'*'
END
GO

BEGIN
   EXEC ebps_drop 'procedure', 'ebppop_locking_strategy', NULL
END
GO


