/*
Description
   Pre-populate file format types
*/
EXEC ebps_drop 'procedure', 'ebps_populate_m3_formats'
GO
CREATE PROCEDURE ebps_populate_m3_formats
(   
   @ps_mime_type NVARCHAR(255),
   @ps_file_ext  NVARCHAR(128),
   @ps_name      NVARCHAR(255)
)
AS
DECLARE 
   @li_format_id INT
BEGIN
   SET NOCOUNT ON;

   SELECT @li_format_id = COALESCE( MAX( format_id ), 0 ) + 1 FROM m3_formats

   IF NOT EXISTS( SELECT 1 FROM m3_formats WHERE mime_type = @ps_mime_type )
   BEGIN
      INSERT INTO m3_formats( format_id, mime_type, file_ext, name )
      VALUES( @li_format_id, @ps_mime_type, @ps_file_ext, @ps_name )
   END
END
GO

BEGIN
   EXEC ebps_populate_m3_formats N'UNKNOWN MIME TYPE', N' ', N'UNKNOWN MIME TYPE'
   EXEC ebps_populate_m3_formats N'IMAGE/TIFF', N'.TIF.TIFF', N'IMAGE/TIFF'
   EXEC ebps_populate_m3_formats N'IMAGE/JPEG', N'.JPG.JPE.JPEG', N'IMAGE/JPEG'
   EXEC ebps_populate_m3_formats N'IMAGE/GIF', N'.GIF', N'IMAGE/GIF'
   EXEC ebps_populate_m3_formats N'APPLICATION/ACAD', N'.DWG.RND', N'APPLICATION/ACAD'
   EXEC ebps_populate_m3_formats N'APPLICATION/DWF', N'.DWF', N'APPLICATION/DWF'   
   EXEC ebps_populate_m3_formats N'APPLICATION/PDF', N'.PDF', N'APPLICATION/PDF'
   EXEC ebps_populate_m3_formats N'APPLICATION/EBA', N'.EBA', N'APPLICATION/EBA'
   EXEC ebps_populate_m3_formats N'TEXT/PLAIN', N'.TXT.SQL.INI.LOG', N'TEXT/PLAIN'
   EXEC ebps_populate_m3_formats N'APPLICATION/MSWORD', N'.DOC.RTF.DOT', N'APPLICATION/MSWORD'
   EXEC ebps_populate_m3_formats N'APPLICATION/VND.MS-EXCEL', N'.XLS.XLB', N'APPLICATION/VND.MS-EXCEL'
