   EXEC ebps_populate_m3_formats N'TEXT/XSLT', N'.XSLT', N'XSL Stylesheet'
   EXEC ebps_populate_m3_formats N'TEXT/XSD', N'.XSD', N'XML Schema File'
   EXEC ebps_populate_m3_formats N'APPLICATION/OCTET-STREAM', N'.CTB', N'AutoCAD Color-dependent Plot Style Table'
   EXEC ebps_populate_m3_formats N'APPLICATION/SSIS', N'.DTSX', N'Integration Services Package'
   EXEC ebps_populate_m3_formats N'APPLICATION/DBF', N'.DBF', N'APPLICATION/DBF'
   EXEC ebps_populate_m3_formats N'APPLICATION/SHX', N'.SHX', N'APPLICATION/SHX'
   EXEC ebps_populate_m3_formats N'APPLICATION/SHP', N'.SHP', N'APPLICATION/SHP'
   EXEC ebps_populate_m3_formats N'APPLICATION/X-IGC-CSF', N'.CSF', N'Content Sealed Format'
   
   IF NOT EXISTS( SELECT 1 FROM m3_formats WHERE file_ext like N'%.LOG%' )
   BEGIN
      UPDATE m3_formats SET file_ext = file_ext + N'.LOG' WHERE mime_type=N'TEXT/PLAIN'      
   END
   IF NOT EXISTS( SELECT 1 FROM m3_formats WHERE file_ext like N'%.DTSCONFIG%' )
   BEGIN
      UPDATE m3_formats SET file_ext = file_ext + N'.DTSCONFIG' WHERE mime_type=N'TEXT/XML'      
   END   
   IF EXISTS( SELECT 1 FROM m3_formats WHERE file_ext = N'XSLT' )
   BEGIN
      UPDATE m3_formats SET file_ext = N'.' + file_ext + N'.XSL' WHERE mime_type=N'TEXT/XSLT' and file_ext = N'XSLT'   
   END
   IF EXISTS( SELECT 1 FROM m3_formats WHERE file_ext = N'.XSLT' )
   BEGIN
      UPDATE m3_formats SET file_ext = file_ext + N'.XSL' WHERE mime_type=N'TEXT/XSLT' and file_ext = N'.XSLT'   
   END
END
GO

EXEC ebps_drop 'procedure', 'ebps_populate_m3_formats'
GO

BEGIN
   SET NOCOUNT ON;
   
   -- Add as an Object (Scope becomes 'Global')
   --    Simply assume that is there is no Scope info it must go into 'Global'
   INSERT INTO objects( guid, object_id, object_type, scope_id, hide_flags, lock_flags, date_added, added_by, date_changed, changed_by )
   SELECT NULL, format_id, 38, 1, 0, 0, GETDATE(), 1, GETDATE(), 1
   FROM m3_formats
   WHERE format_id NOT IN ( SELECT object_id FROM objects WHERE object_type = 38 )
END
GO

