/*
Description
   Populates the Supported Ftr Formats.
*/   
EXEC ebps_drop 'procedure', 'ebps_populate_ftr_formats'
GO
CREATE PROCEDURE ebps_populate_ftr_formats
(
   @ps_format      NVARCHAR(100), 
   @ps_engine_name NVARCHAR(100)
)
AS
DECLARE
   @pi_format_id INT, 
   @pi_engine_id INT
BEGIN
   SET NOCOUNT ON;
   
   SELECT TOP 1 @pi_format_id = format_id FROM m3_formats WHERE file_ext LIKE @ps_format
   SELECT TOP 1 @pi_engine_id = engine_id FROM m3_engines WHERE engine_name = @ps_engine_name
   IF @pi_format_id > 0 AND @pi_engine_id > 0
      AND NOT EXISTS ( SELECT 1 FROM m3_supported_ftr_formats 
                       WHERE format_id = @pi_format_id )
   BEGIN
      INSERT INTO m3_supported_ftr_formats( format_id, engine_id )
      VALUES( @pi_format_id, @pi_engine_id )
      IF @@ERROR <> 0 RETURN 1 -- Failure
   END
                      
   RETURN 0 -- Success
END
GO

-- Define Supported Rendition Formats
BEGIN
   SET NOCOUNT ON;

   EXEC ebps_populate_ftr_formats N'%.TIF%', N'FTR'
   EXEC ebps_populate_ftr_formats N'%.PDF%', N'FTR'
