-----------------------------------------------------------------------------------------

/*
Description
   Populates the Supported Rendition Formats.
*/   
EXEC ebps_drop 'procedure', 'ebps_populate_rend_formats'
GO
CREATE PROCEDURE ebps_populate_rend_formats
(
   @ps_source_fmt  NVARCHAR(100), 
   @ps_dest_fmt    NVARCHAR(100), 
   @ps_engine_name NVARCHAR(100)
)
AS
DECLARE
   @pi_source_fmt_id INT, 
   @pi_dest_fmt_id   INT, 
   @pi_engine_id     INT
BEGIN
   SET NOCOUNT ON;
   
   SELECT TOP 1 @pi_source_fmt_id = format_id FROM m3_formats WHERE file_ext LIKE @ps_source_fmt
   SELECT TOP 1 @pi_dest_fmt_id = format_id FROM m3_formats WHERE file_ext LIKE @ps_dest_fmt
   SELECT TOP 1 @pi_engine_id = engine_id FROM m3_engines WHERE engine_name = @ps_engine_name
   
   IF @pi_source_fmt_id > 0 AND @pi_dest_fmt_id > 0 AND @pi_engine_id > 0
      AND NOT EXISTS ( SELECT 1 FROM m3_supported_rendition_formats 
                   WHERE source_fmt_id = @pi_source_fmt_id 
                   AND dest_fmt_id = @pi_dest_fmt_id )
   BEGIN
      INSERT INTO m3_supported_rendition_formats( source_fmt_id, dest_fmt_id, engine_id )
      VALUES( @pi_source_fmt_id, @pi_dest_fmt_id, @pi_engine_id )
      IF @@ERROR <> 0 RETURN 1 -- Failure
   END

   RETURN 0 -- Success
END
GO

-- Define Supported Rendition Formats
BEGIN
   SET NOCOUNT ON;

   EXEC ebps_populate_rend_formats N'%.DOC%', N'%.PDF%', N'INTERPLOT'
   EXEC ebps_populate_rend_formats N'%.DOCX%', N'%.PDF%', N'INTERPLOT'    
   EXEC ebps_populate_rend_formats N'%.XLS%', N'%.PDF%', N'INTERPLOT' 
   EXEC ebps_populate_rend_formats N'%.XLSX%', N'%.PDF%', N'INTERPLOT'  
   EXEC ebps_populate_rend_formats N'%.DGN%', N'%.PDF%', N'INTERPLOT'
   EXEC ebps_populate_rend_formats N'%.DWG%', N'%.PDF%', N'INTERPLOT'
   EXEC ebps_populate_rend_formats N'%.TIF%', N'%.PDF%', N'INTERPLOT'
   EXEC ebps_populate_rend_formats N'%.JPG%', N'%.PDF%', N'INTERPLOT'
   
   /*
   commenting this out because we eventually want to support the
   the below rendition pairs
    
   EXEC ebps_populate_rend_formats N'%.DWG%', N'%.TIF%', N'INTERPLOT'
   EXEC ebps_populate_rend_formats N'%.DGN%', N'%.TIF%', N'INTERPLOT'
   EXEC ebps_populate_rend_formats N'%.DWG%', N'%.TXT%', N'INTERPLOT'
   EXEC ebps_populate_rend_formats N'%.DGN%', N'%.TXT%', N'INTERPLOT'
   EXEC ebps_populate_rend_formats N'%.DOC%', N'%.TIF%', N'INTERPLOT'
   EXEC ebps_populate_rend_formats N'%.DOCX%', N'%.TIF%', N'INTERPLOT'
   EXEC ebps_populate_rend_formats N'%.DOTX%', N'%.TIF%', N'INTERPLOT' 
   */
END
GO
EXEC ebps_drop 'procedure', 'ebps_populate_rend_formats'
GO

