/*
Description
   Populates the default MediaTypes.
*/
BEGIN 
   SET NOCOUNT ON;
   
   INSERT INTO media_types( media_type_id, description, sys_type )
   SELECT 1, '{eBElectronicCopy}', 'E' 
   WHERE NOT EXISTS( SELECT 1 FROM media_types WHERE media_type_id = 1 )

   -- Add as an Object (Scope becomes 'Global')
   INSERT INTO objects( guid, object_id, object_type, scope_id, hide_flags, lock_flags, date_added, added_by, date_changed, changed_by )
   SELECT NULL, 1, 27, 1, 0, 0, GETDATE(), 1, GETDATE(), 1
   WHERE NOT EXISTS ( SELECT 1 FROM objects WHERE object_id = 1 AND object_type = 27 )    
END
GO

