/*
Description
   Adds the default 'Global' Namespace.

Specification
   ...
*/
BEGIN
   SET NOCOUNT ON;

   INSERT INTO namespaces( namespace_id, name )
   SELECT 1, 'Global' WHERE 1 NOT IN ( SELECT namespace_id FROM namespaces )

   UPDATE namespaces SET name = 'Global'
   WHERE namespace_id = 1
   
   -- NOTE: The Namespace Scope will only be added later (by the scope.sql populate script)
END
GO

