EXEC ebps_drop 'procedure', 'ebps_pop_object_behaviors'
GO
CREATE PROCEDURE ebps_pop_object_behaviors
(   
   @pi_object_id     INT, 
   @pi_object_type   INT, 
   @pi_behavior_type INT, 
   @ps_value         NVARCHAR(MAX)
)
AS
BEGIN
   SET NOCOUNT ON;

   IF NOT EXISTS( SELECT 1 FROM object_behaviors 
                  WHERE object_id = @pi_object_id
                  AND object_type = @pi_object_type
                  AND behavior_type = @pi_behavior_type )
   BEGIN
      INSERT INTO object_behaviors ( object_id, object_type, behavior_type, value, default_value, use_default )
      SELECT @pi_object_id, @pi_object_type, @pi_behavior_type, @ps_value, @ps_value, 'Y' -- Note, we have to set value; it cannot be null
      WHERE NOT EXISTS( SELECT 1 FROM object_behaviors 
                        WHERE object_id = @pi_object_id 
                        AND object_type = @pi_object_type 
                        AND behavior_type = @pi_behavior_type )
   IF @@ERROR <> 0 RETURN 1 -- Failure
   END
   ELSE
   BEGIN
      UPDATE object_behaviors SET default_value = @ps_value
      WHERE object_id = @pi_object_id 
      AND object_type = @pi_object_type 
      AND behavior_type = @pi_behavior_type 
      IF @@ERROR <> 0 RETURN 1 -- Failure
   END
   
   RETURN 0 -- Success
END
GO

BEGIN
   SET NOCOUNT ON;
   
   -- ******************************** Default Copy Options ********************************   
