-- Script used to populate objects with id = 0 for base type objects 

BEGIN
   -- System Data
   INSERT INTO objects( object_id, object_type, scope_id, hide_flags, lock_flags )
   SELECT 0, 20, 1, 0, 0 
   WHERE NOT EXISTS ( SELECT 1 FROM objects b WHERE b.object_type = 20 AND b.object_id = 0 )
END
