EXEC ebps_drop 'procedure', 'ebps_populate_perm_g0a'
GO
CREATE PROCEDURE ebps_populate_perm_g0a
(   
   @pi_perm_type    INT,
   @ps_name         NVARCHAR(256),
   @ps_description  NVARCHAR(2000),
   @ps_global_only  CHAR(1),
   @pi_class        INT
)
AS
BEGIN
   SET NOCOUNT ON;

   INSERT INTO perm_g0a( perm_type, name, description, class, global_only )
   SELECT @pi_perm_type, '', '', 0, @ps_global_only
   WHERE NOT EXISTS( SELECT 1 FROM perm_g0a WHERE perm_type = @pi_perm_type )
   IF @@ERROR <> 0 RETURN 1 -- Failure
   
   UPDATE perm_g0a SET name = @ps_name, 
                       description = @ps_description,
                       global_only = @ps_global_only,
                       class = @pi_class
   WHERE perm_type = @pi_perm_type
   IF @@ERROR <> 0 RETURN 1 -- Failure

   RETURN 0 -- Success
END
GO

BEGIN
   SET NOCOUNT ON;
   
   -- New Object Instance (Class 1)
   EXEC ebps_populate_perm_g0a 5, N'Organization', N'This permission will allow the user to add a new Organization.', N'N', 1
