-- FILE: persons.sql
-- =====================================================================

-----------------------------------------------------------------------------------------
-- $Copyright: (c) 2015 Bentley Systems, Incorporated. All rights reserved. $
-----------------------------------------------------------------------------------------

/*
Description
   Adds the 'ADMIN' person
*/
BEGIN
   SET NOCOUNT ON;
   
   -- There must always be one person called ADMIN
   INSERT INTO persons ( person_id, namespace_id, person_code, surname, initials )
   SELECT 1, 1, 'ADMIN', 'ADMIN person', 'A' 
   WHERE NOT EXISTS( SELECT 1 FROM persons WHERE person_id = 1 )

   -- Update it in case anyone had the mind to go and change it.   
   UPDATE persons
   SET person_code = 'ADMIN',
       surname = 'ADMIN person',
       initials = 'A'
   WHERE person_id = 1
   
   -- Add as an Object (Scope becomes 'Global')
   INSERT INTO objects( object_id, object_type, scope_id, hide_flags, lock_flags )
   SELECT 1, 4, 1, 0, 0
   WHERE NOT EXISTS ( SELECT 1 FROM objects WHERE object_id = 1 AND object_type = 4 )   
   
END
GO

DECLARE 
   @li_gui_folder_id INT,
   @li_error         INT,
   @li_setting_id    INT,
   @ps_key_value     NVARCHAR(255)
BEGIN
   SELECT @ps_key_value = CAST(a.value AS NVARCHAR(255)) 
   FROM settings a, setting_defs b
   WHERE a.setting_id = b.setting_id
   AND b.object_type = 4 AND a.object_id = 1
   AND b.code = N'PersonalFolderId'

   IF @ps_key_value IS NULL 
   BEGIN   
      -- Favorites and Baskets, create the folder for the person
      
      -- ebp_new_id won't exist at this point and not sure we can move it before this proc
      --EXEC @li_error = ebp_new_id 'gui_folder_id', @li_gui_folder_id OUTPUT
      SELECT @li_gui_folder_id = MAX(gui_folder_id) + 1 FROM gui_folders
      IF @@ERROR <> 0 OR @li_error <> 0 RETURN -- Failure

      INSERT INTO gui_folders( gui_folder_id, namespace_id, name ) 
      VALUES( @li_gui_folder_id, 1, N'{MyeBName}' )
      IF @@ERROR <> 0 RETURN -- Failure

     -- Add as an Object (Scope becomes 'Global')
      --    Simply assume that is there is no Scope info it must go into 'Global'
     --    lock_flags=2|16 because it cannot be modified or deleted
      INSERT INTO objects( object_id, object_type, scope_id, hide_flags, lock_flags )
      SELECT @li_gui_folder_id, 170, 1, 0, 18

      SET @ps_key_value = CONVERT(VARCHAR, @li_gui_folder_id);

      --EXEC @li_error = ebp_set_setting 'PersonalFolderId', 1, 4, @ps_key_value, 'N', 1
      --IF @@ERROR <> 0 OR @li_error <> 0 RETURN -- Failure
      -- ebp_set_setting won't exist here or has other dependencies that does not
      INSERT INTO settings (setting_id, object_id, value)
      SELECT a.setting_id, 1, @ps_key_value
      FROM setting_defs a WHERE a.object_type = 4 AND a.code = N'PersonalFolderId'

      -- Basket
      SELECT @li_gui_folder_id = MAX(gui_folder_id) + 1 FROM gui_folders
      IF @@ERROR <> 0 OR @li_error <> 0 RETURN -- Failure

      INSERT INTO gui_folders( gui_folder_id, namespace_id, name ) 
      VALUES( @li_gui_folder_id, 1, N'{MyeBName}' )
      IF @@ERROR <> 0 RETURN -- Failure

     -- Add as an Object (Scope becomes 'Global')
      --    Simply assume that is there is no Scope info it must go into 'Global'
     --    lock_flags=2|16 because it cannot be modified or deleted
      INSERT INTO objects( object_id, object_type, scope_id, hide_flags, lock_flags )
      SELECT @li_gui_folder_id, 170, 1, 0, 18

      SET @ps_key_value = CONVERT(VARCHAR, @li_gui_folder_id);

      --EXEC @li_error = ebp_set_setting 'PersonalBasketId', 1, 4, @ps_key_value, 'N', 1
      --IF @@ERROR <> 0 OR @li_error <> 0 RETURN -- Failure
      -- ebp_set_setting won't exist here or has other dependencies that does not
      INSERT INTO settings (setting_id, object_id, value)
      SELECT a.setting_id, 1, @ps_key_value
      FROM setting_defs a WHERE a.object_type = 4 AND a.code = N'PersonalBasketId'
   END
END
GO

BEGIN
   -- Add as an Object (Scope becomes 'Global')
   --    Simply assume that is there is no Scope info it must go into 'Global'
   INSERT INTO objects( object_id, object_type, scope_id, hide_flags, lock_flags )
   SELECT gui_folder_id, 170, 1, 0, 0
   FROM gui_folders
   WHERE gui_folder_id NOT IN ( SELECT object_id FROM objects WHERE object_type = 170 )
END
GO

