-- =====================================================================
-- FILE: priorities.sql
-- =====================================================================

-----------------------------------------------------------------------------------------
-- $Copyright: (c) Bentley Systems, Incorporated. All rights reserved. $
-----------------------------------------------------------------------------------------

-- Populate default condition priorities so we don't start with an empty database
DECLARE
   @li_error            INT,
   @li_priority_id      INT
BEGIN
   SET NOCOUNT ON;
   SELECT @li_priority_id = priority_id FROM priorities WITH (NOLOCK) WHERE object_type = 322 AND class_id IS NULL
   IF @@ROWCOUNT = 0
   BEGIN
      EXEC ebp_add_priority 'Low', NULL, NULL, 1, 322, NULL, 1, @li_priority_id OUT
      EXEC ebp_add_priority 'Medium', NULL, NULL, 2, 322, NULL, 1, @li_priority_id OUT
      EXEC ebp_add_priority 'High', NULL, NULL, 3, 322, NULL, 1, @li_priority_id OUT
      EXEC ebp_add_priority 'Critical', NULL, NULL, 4, 322, NULL, 1, @li_priority_id OUT
   END
END
GO

GO


