/*
Description
   
   This script creates the $ReferenceCards folder if it doesn't already exists.
   The permissions and settings are updated with the reference card id. 
*/

DECLARE
   @li_error                INT,
   @li_folder_id            INT,
   @li_all_reports_id       INT,
   @li_qs_reports_id        INT,
   @li_es_reports_id        INT,
   @li_reference_card_id    INT,
   @ls_reference_card_name  NVARCHAR(255),
   @ls_folder_name          NVARCHAR(255)
BEGIN
   SET NOCOUNT ON;

   -- If setting set assume folders exists -- For Reference Card Folder Id
   SET @li_reference_card_id = dbo.ebf_setting_i(1, 20, 'ReferenceCardFolderId', 0, NULL);

   SET @ls_reference_card_name = N'$ReferenceCards'

   IF ISNULL(@li_reference_card_id, 0) < 1 
   BEGIN
      -- Reference card folder (should only return one)
      SELECT TOP 1 @li_reference_card_id = gui_folder_id
      FROM gui_folders WITH (NOLOCK)
      WHERE name = @ls_reference_card_name
      -- It can't have a parent, if it does it may be a custom folder
      AND gui_folder_id NOT IN ( SELECT object_id FROM gui_structures WHERE object_type = 170 )

      IF ISNULL(@li_reference_card_id, 0) < 1 
      BEGIN
         EXEC @li_error = ebp_new_id N'gui_folder_id', @li_reference_card_id OUTPUT
         IF @@ERROR <> 0 OR @li_error <> 0 RETURN -- Failure

         INSERT INTO gui_folders( gui_folder_id, namespace_id, name ) 
         VALUES( @li_reference_card_id, 1, @ls_reference_card_name )
         IF @@ERROR <> 0 RETURN -- Failure  

         -- Add as an Object (Scope becomes 'Global')
         -- lock_flags = 2|16 to prevent anyone modifying or deleting 
         INSERT INTO objects( guid, object_id, object_type, scope_id, hide_flags, lock_flags, date_added, added_by, date_changed, changed_by )
         SELECT NULL, @li_reference_card_id, 170, 1, 0, 18, GETDATE(), 1, GETDATE(), 1
         IF @@ERROR <> 0 RETURN -- Failure 
      END

      -- Ensure the setting is updated
      EXEC @li_error = ebp_set_setting N'ReferenceCardFolderId', 1, 20, @li_reference_card_id, N'Y', 1    
      IF @li_error <> 0 OR @@ERROR <> 0 RETURN -- Failure   
   END


END
GO

GO


