-----------------------------------------------------------------------------------------

/*
Description
   Creates default templates for inherent relationhip types.
   
Note
*/
EXEC ebps_drop 'procedure', 'ebps_pop_relationship_template'
GO
CREATE PROCEDURE ebps_pop_relationship_template
(
   @ps_rel_type_code     NVARCHAR(255),
   @ps_mask              NVARCHAR(100)
)
AS
DECLARE
   @li_error           INT,
   @ls_rel_type_code   NVARCHAR(255),
   @ls_name            NVARCHAR(255),
@ls_msg            NVARCHAR(1024),
   @li_template_id     INT,
   @li_rel_type_id     INT,
   @li_rel_id          INT,
   @li_left_type       INT,
   @li_right_type      INT,
   @li_class_id        INT,
   @lany_attributes    ebtype_dictionary
BEGIN
   SET NOCOUNT ON;

   -- Find relationship type based on the IR name
   SELECT @li_class_id = b.class_id, @ls_name = b.name,
      @li_rel_type_id = rel_type_id, @li_left_type = left_object_type, @li_right_type = right_object_type
   FROM relationship_types a, class_objects b
   WHERE a.class_id = b.class_id
   AND b.code = @ps_rel_type_code

   IF COALESCE(@li_rel_type_id, 0) < 1
   BEGIN
     EXEC ebp_raise_error_1 N'<Invalid relationship type class Id for {0}>', @ps_rel_type_code, NULL, NULL, 1
      RETURN 1 -- Failure
   END

   -- Check if ANY template already exists then do not create one...we only want to 
   -- create templates for inherent relationships so users can immediately create those
   -- relationships without additional admin work, but if it's already been done ignore.
   SET @ls_rel_type_code = @ps_rel_type_code + '-T' -- Append -T to indicate template;
   --IF EXISTS(SELECT 1 FROM templates WHERE name = @ls_rel_type_code AND object_type = 210)
   IF EXISTS(SELECT 1 FROM templates WHERE class_id = @li_class_id AND object_type = 210)
   BEGIN
      RETURN 0 -- Success
   END

   -- Add the underlying object
   EXEC @li_error = ebp_add_relationship @li_rel_type_id, 0, @li_left_type, 0, @li_right_type, @lany_attributes, 1, @li_rel_id OUT

   -- Add the template   
   EXEC @li_error = ebp_add_template @ls_rel_type_code, @ls_name, @ps_mask, @li_class_id, 
                        @li_rel_id, 210, 
                        0, 'N', NULL, NULL, 0, 1, @li_template_id OUT
   IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure

   -- Approve the template
   EXEC @li_error = ebp_chg_template @li_template_id, '%', '%', '%', -1, 'A', -1, -1, '%', '%', '%', -1, 1
   IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure

   RETURN 0 -- Success
 
END
GO

BEGIN

   EXEC ebps_pop_relationship_template N'IR-CHANGE_DOCS', '####'   
   EXEC ebps_pop_relationship_template N'IR-DEVIATION_DOCS', '####'
   EXEC ebps_pop_relationship_template N'IR-DOCUMENT_LOCATIONS', '####'
