CREATE PROCEDURE ebps_populate_relationship_type_constraints
(
   @pi_left_object_type    INT,
   @pi_right_object_type   INT
)
AS
DECLARE
   @li_error               INT,
   @li_attribute_domain_id INT
BEGIN
   SET NOCOUNT ON;

   IF NOT EXISTS (SELECT 1 FROM attribute_domains WITH (NOLOCK) WHERE object_id = 0 AND object_type = @pi_left_object_type AND source_object_id = 0 AND source_object_type = @pi_right_object_type AND property_name = N'RelationshipTypeConstraints' )
   BEGIN
      EXEC @li_error =  ebp_add_attribute_domain 0, @pi_left_object_type, N'RelationshipTypeConstraints', N'I', 0, @pi_right_object_type, 0, N'L', N'A', 1, @li_attribute_domain_id OUTPUT
      IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure
   END
         
   IF NOT EXISTS (SELECT 1 FROM attribute_domains WITH (NOLOCK) WHERE object_id = 0 AND object_type = @pi_right_object_type AND source_object_id = 0 AND source_object_type = @pi_left_object_type AND property_name = N'RelationshipTypeConstraints' )
   BEGIN
      EXEC @li_error =  ebp_add_attribute_domain 0, @pi_right_object_type, N'RelationshipTypeConstraints', N'I', 0, @pi_left_object_type, 0, N'L', N'A', 1, @li_attribute_domain_id OUTPUT
      IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure
   END
   RETURN 0 -- Success
END
