   EXEC ebps_populate_relationship_type_constraints 140,140
   EXEC ebps_populate_relationship_type_constraints 299,302 -- LinearLocation-Restriction
   EXEC ebps_populate_relationship_type_constraints 302,299 -- LinearLocation-Restriction
   EXEC ebps_populate_relationship_type_constraints 185,185 -- Class-Class
   EXEC ebps_populate_relationship_type_constraints 302,185 -- Restriction-Class
   EXEC ebps_populate_relationship_type_constraints 185,302 -- Restriction-Class
   EXEC ebps_populate_relationship_type_constraints 303,185 -- RestrictionClass-Class
   EXEC ebps_populate_relationship_type_constraints 185,303 -- RestrictionClass-Class    
