-- =====================================================================

-----------------------------------------------------------------------------------------
-- $Copyright: (c) 2017 Bentley Systems, Incorporated. All rights reserved. $
-----------------------------------------------------------------------------------------

/*
Description
   Populates the relationship_types table with compatibity (to older version) RelationshipTypes.
   
   The function ebf_get_comp_rel_type will assume that these relationhips exist.
   
Note
   See ebf_get_comp_rel_type for the required structure.
   
   We will run this script at the end (because we are depending on a few procedures
*/
EXEC ebps_drop 'procedure', 'ebps_pop_relationship_types'
GO
CREATE PROCEDURE ebps_pop_relationship_types
(
   @ps_code              NVARCHAR(255),
   @ps_name              NVARCHAR(255),
   @pi_left_object_type  INT,      
   @pi_right_object_type INT,
   @ps_left_name         NVARCHAR(255),
   @ps_right_name        NVARCHAR(255)   
)
AS
DECLARE
   @li_error           INT,
   @li_parent_class_id INT,
   @li_class_id        INT,
   @li_rel_type_id     INT
BEGIN
   SET NOCOUNT ON;

   -- Find the parent Class...
   SELECT @li_parent_class_id = class_id FROM class_objects WHERE code = N'IR' AND group_id = 22
   -- ...but it it doen't exist then...
   IF @@ROWCOUNT = 0
   BEGIN
      -- ...add it.
      EXEC @li_error = ebp_new_id N'class_id', @li_parent_class_id OUTPUT
      IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure

      INSERT INTO class_objects( class_id, group_id, namespace_id, code, name, sys_type, access_modifiers, prevent_approval_flags, prompt_flags, is_sync_tracked )
      VALUES( @li_parent_class_id, 22, 1, N'IR', N'Inherent Relations', N'U', N'A', 0, 0, 'N' )
      IF @@ERROR <> 0 RETURN 1 -- Failure

      -- Add as an Object (Scope becomes the default Session Scope)
      INSERT INTO objects( guid, object_id, object_type, scope_id, hide_flags, lock_flags, date_added, added_by, date_changed, changed_by )
      VALUES( NULL, @li_parent_class_id, 185, 1, 0, 0, GETDATE(), 1, GETDATE(), 1 )
      IF @@ERROR <> 0 RETURN 1 -- Failure
   END
   ELSE
   BEGIN
      -- Update the Class
      UPDATE class_objects 
      SET name = N'Inherent Relations',
          sys_type = N'U',
          access_modifiers = N'A'
      WHERE class_id = @li_parent_class_id  
      IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure     
   END   

   -- Find the child Class...
   SELECT @li_class_id = class_id FROM class_objects WHERE code = @ps_code AND group_id = 22
   -- ...but it it doen't exist then...
   IF @@ROWCOUNT = 0
   BEGIN
      -- ...add it.
      EXEC @li_error = ebp_new_id N'class_id', @li_class_id OUTPUT
      IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure

      INSERT INTO class_objects( parent_class_id, class_id, group_id, namespace_id, code, name, sys_type, access_modifiers, prevent_approval_flags, prompt_flags, is_sync_tracked )
      VALUES( @li_parent_class_id, @li_class_id, 22, 1, @ps_code, @ps_name, N'U', N'S', 0, 0, 'N')
      IF @@ERROR <> 0 RETURN 1 -- Failure

      -- Add as an Object (Scope becomes the default Session Scope)
      INSERT INTO objects( guid, object_id, object_type, scope_id, hide_flags, lock_flags, date_added, added_by, date_changed, changed_by )
      VALUES( NULL, @li_class_id, 185, 1, 0, 0, GETDATE(), 1, GETDATE(), 1 )
      IF @@ERROR <> 0 RETURN 1 -- Failure
   END
   ELSE
   BEGIN
      -- Update the Class
      UPDATE class_objects 
      SET name = @ps_name,
          sys_type = N'U',
          access_modifiers = N'S'
      WHERE class_id = @li_class_id  
      IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure  
   END
   
   -- Find the child RelationhipType...
   SELECT @li_rel_type_id = rel_type_id FROM relationship_types WHERE class_id = @li_class_id
   -- ...but it it doen't exist then...
   IF @@ROWCOUNT = 0
   BEGIN
      -- ...add it.
      EXEC @li_error = ebp_new_id N'rel_type_id', @li_rel_type_id OUTPUT
      IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure

      INSERT INTO relationship_types( rel_type_id, class_id, left_name, right_name, left_object_type, right_object_type, 
                                      controlled_by, presentation, num_left, num_right, is_directed, allow_circ_ref )
      VALUES( @li_rel_type_id, @li_class_id, @ps_left_name, @ps_right_name, @pi_left_object_type, @pi_right_object_type, 
              N'N', N'L', 0, 0, N'Y', N'N' )
      IF @@ERROR <> 0 RETURN 1 -- Failure

      -- Add as an Object (Scope becomes the default Session Scope)
      INSERT INTO objects( guid, object_id, object_type, scope_id, hide_flags, lock_flags, date_added, added_by, date_changed, changed_by )
      VALUES( NULL, @li_rel_type_id, 87, 1, 0, 0, GETDATE(), 1, GETDATE(), 1 )
      IF @@ERROR <> 0 RETURN 1 -- Failure
   END
   ELSE
   BEGIN
      -- Update the Class
      UPDATE relationship_types 
      SET left_name = @ps_left_name,
          right_name = @ps_right_name
      WHERE rel_type_id = @li_rel_type_id  
      IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure  
   END   
   
   RETURN 0 -- Success
END
GO

BEGIN
   -- !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
   -- *** ALWAYS USE THE SMALLER OF THE TWO TYPES AS THE LEFT OBJECT ***
   -- *** The upgrade scripts will assume this was done correctly    ***
   -- !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!   
   EXEC ebps_pop_relationship_types N'IR-CHANGE_DOCS', N'ChangeRequest to Document', 3, 6, N'Document', N'Change Request'   
   EXEC ebps_pop_relationship_types N'IR-DEVIATION_DOCS', N'DeviationWaiver to Document', 3, 11, N'Document', N'Deviation/Waiver'
   EXEC ebps_pop_relationship_types N'IR-DOCUMENT_LOCATIONS', N'Document to Location', 3, 12, N'Document', N'Location'  
   EXEC ebps_pop_relationship_types N'IR-ITEM_LOCATIONS', N'Location to PhysicalItem', 1, 12, N'Physical Item', N'Location'     
   EXEC ebps_pop_relationship_types N'IR-PERSON_LOCATIONS', N'Location to Person', 4, 12, N'Person', N'Location'    
   EXEC ebps_pop_relationship_types N'IR-ORG_UNIT_LOCATIONS', N'Location to Organization', 5, 12, N'Organization', N'Location'    
   EXEC ebps_pop_relationship_types N'IR-VITEM_LOCATIONS', N'GroupedVirtualItem to Location', 12, 123, N'Location', N'Virtual Item'
   EXEC ebps_pop_relationship_types N'IR-VITEM_DOCUMENTS', N'Document to GroupedVirtualItem', 3, 123, N'Document', N'Virtual Item'
   EXEC ebps_pop_relationship_types N'IR-MOD_ORDER_DOCS', N'Document to Modification', 3, 10, N'Document', N'Modification'
   EXEC ebps_pop_relationship_types N'IR-SERIAL_DOCS', N'Document to SerializedItem', 3, 18, N'Document', N'Serialized Item'
   EXEC ebps_pop_relationship_types N'IR-CHANGE_REQUEST_PROJECTS_OWNER', N'ChangeRequest to Owner Project', 6, 9, N'Owned Change Request', N'Owner Project'
   EXEC ebps_pop_relationship_types N'IR-CHANGE_REQUEST_PROJECTS_SHARED', N'ChangeRequest to Shared Project', 6, 9, N'Shared Change Request', N'Shared Project'
   EXEC ebps_pop_relationship_types N'IR-DOCUMENT_PROJECTS_OWNER', N'Document to Owner Project', 3, 9, N'Owned Document', N'Owner Project'
   EXEC ebps_pop_relationship_types N'IR-DOCUMENT_PROJECTS_SHARED', N'Document to Shared Project', 3, 9, N'Shared Document', N'Shared Project'
   EXEC ebps_pop_relationship_types N'IR-VITEMGROUP_PROJECTS_OWNER', N'Owner Project to VirtualItemGroup', 9, 182, N'Owned Project', N'Owner Virtual Item Group'
   EXEC ebps_pop_relationship_types N'IR-VITEMGROUP_PROJECTS_SHARED', N'Shared Project to VirtualItemGroup', 9, 182, N'Shared Project', N'Shared Virtual Item Group'   
   EXEC ebps_pop_relationship_types N'IR-EVENT_PROJECTS_OWNER', N'Owner Project to Event', 9, 94, N'Owner Project', N'Owned Event'
   EXEC ebps_pop_relationship_types N'IR-EVENT_PROJECTS_SHARED', N'Shared Project to Event', 9, 94, N'Shared Project', N'Shared Event'
   EXEC ebps_pop_relationship_types N'IR-ITEM_PROJECTS_OWNER', N'PhysicalItem to Owner Project', 1, 9, N'Owned Physical Item', N'Owner Project'
   EXEC ebps_pop_relationship_types N'IR-ITEM_PROJECTS_SHARED', N'PhysicalItem to Shared Project', 1, 9, N'Shared Physical Item', N'Shared Project'
   EXEC ebps_pop_relationship_types N'IR-ORG_PROJECTS_OWNER', N'Organization to Owner Project', 5, 9, N'Owned Organization', N'Owner Project'
   EXEC ebps_pop_relationship_types N'IR-ORG_PROJECTS_SHARED', N'Organization to Shared Project', 5, 9, N'Shared Organization', N'Shared Project'
   EXEC ebps_pop_relationship_types N'IR-PERSON_PROJECTS_OWNER', N'Person to Owner Project', 4, 9, N'Owned Person', N'Owner Project'
   EXEC ebps_pop_relationship_types N'IR-PERSON_PROJECTS_SHARED', N'Person to Shared Project', 4, 9, N'Shared Person', N'Shared Project'
   EXEC ebps_pop_relationship_types N'IR-TAG_PROJECTS_OWNER', N'Owner Project to Tag', 9, 212, N'Owner Project', N'Owned Tag'
   EXEC ebps_pop_relationship_types N'IR-TAG_PROJECTS_SHARED', N'Shared Project to Tag', 9, 212, N'Shared Project', N'Shared Tag'
   EXEC ebps_pop_relationship_types N'IR-VITEM_PROJECTS_OWNER', N'Owner Project to GroupedVirtualItem', 9, 123, N'Owner Project', N'Owned Virtual Item'
   EXEC ebps_pop_relationship_types N'IR-VITEM_PROJECTS_SHARED', N'Shared Project to GroupedVirtualItem', 9, 123, N'Shared Project', N'Shared Virtual Item'
   EXEC ebps_pop_relationship_types N'IR-WORK_ORDER_PROJECTS_OWNER', N'Owner Project to WorkOrder', 9, 140, N'Owner Project', N'Owned Work Order'
   EXEC ebps_pop_relationship_types N'IR-WORK_ORDER_PROJECTS_SHARED', N'Shared Project to WorkOrder', 9, 140, N'Shared Project', N'Shared Work Order'
   EXEC ebps_pop_relationship_types N'IR-CHANGE_RELATIONS', N'ChangeRequest to ChangeRequest', 6, 6, N'Related Change', N'Related Change'   
   EXEC ebps_pop_relationship_types N'IR-VITEM_ITEMS', N'PhysicalItem to GroupedVirtualItem', 1, 123, N'Physical Item', N'Virtual Item'
   EXEC ebps_pop_relationship_types N'IR-VITEM_SERIALS', N'SerializedItem to GroupedVirtualItem', 18, 123, N'Serialized Item', N'Virtual Item'      
   EXEC ebps_pop_relationship_types N'IR-DOC_STRUCTURES_CONTAINED', N'Document Structure', 3, 3, N'Parent', N'Child'         
   EXEC ebps_pop_relationship_types N'IR-DOC_STRUCTURES_REFERENCED', N'Referenced Document', 3, 3, N'Referenced By', N'Reference To'         
   EXEC ebps_pop_relationship_types N'IR-DOC_STRUCTURES_PROPAGATED', N'Propagated Document', 3, 3, N'Propagated From', N'Propagated To'
   EXEC ebps_pop_relationship_types N'IR-VITEMGROUP_STRUCTURES_CONTAINED', N'VirtualItemGroup Structure', 182, 182, N'Parent', N'Child'         
   EXEC ebps_pop_relationship_types N'IR-VITEMGROUP_STRUCTURES_REFERENCED', N'Referenced VirtualItemGroup', 182, 182, N'Referenced By', N'Reference To'         
   EXEC ebps_pop_relationship_types N'IR-VITEMGROUP_STRUCTURES_PROPAGATED', N'Propagated VirtualItemGroup', 182, 182, N'Propagated From', N'Propagated To'
   EXEC ebps_pop_relationship_types N'IR-DOC_VITEMGROUP', N'Document to VirtualItemGroup', 3, 182, N'Document', N'Virtual Item Group'    
   EXEC ebps_pop_relationship_types N'IR-ITEM_DOCUMENTS', N'PhysicalItem to Document', 1, 3, N'Physical Item', N'Document'       
   EXEC ebps_pop_relationship_types N'IR-ITEM_VITEMGROUPS', N'PhysicalItem to VirtualItemGroup', 1, 182, N'Physical Item', N'Virtual Item Group'          
   EXEC ebps_pop_relationship_types N'IR-VITEM_VITEMGROUPS', N'GroupedVirtualItem to VirtualItemGroup', 123, 182, N'Virtual Item', N'Virtual Item Group'
   EXEC ebps_pop_relationship_types N'IR-WORK-ORDER_RELATIONS', N'WorkOrder to WorkOrder', 140, 140, N'Related Work Order', N'Related Work Order'   
END
GO
EXEC ebps_drop 'procedure', 'ebps_pop_relationship_types'
GO

BEGIN
   SET NOCOUNT ON;
   
   -- Update all then...
   UPDATE relationship_types SET controlled_by = N'N', allow_circ_ref = N'N', presentation = N'L'
   WHERE class_id IN ( SELECT a.class_id FROM class_objects a
                       INNER JOIN class_objects b ON b.class_id = a.parent_class_id
                       WHERE b.code = N'IR'   -- Inherent Relations
                       AND b.group_id = 22 ) -- Relationships
                       
   -- ... fix the exceptions.
   --   Only 'Document Structure' and 'VirtualItemGroup Structure' gets Controlled By the Left.
   UPDATE relationship_types SET controlled_by = N'L', presentation = N'T'
   WHERE class_id IN ( SELECT a.class_id FROM class_objects a
                       INNER JOIN class_objects b ON b.class_id = a.parent_class_id
                       WHERE b.code = N'IR'  -- Inherent Relations
                       AND b.group_id = 22  -- Relationships
                       AND a.code IN ( N'IR-DOC_STRUCTURES_CONTAINED', N'IR-VITEMGROUP_STRUCTURES_CONTAINED' ) )
                       
   --   'Referenced Document', 'Referenced VirtualItemGroup' and 'Related Changes' allows Circular References
   UPDATE relationship_types SET allow_circ_ref = N'Y'
   WHERE class_id IN ( SELECT a.class_id FROM class_objects a
                       INNER JOIN class_objects b ON b.class_id = a.parent_class_id
                       WHERE b.code = N'IR'  -- Inherent Relations
                       AND b.group_id = 22  -- Relationships
                       AND a.code IN ( N'IR-DOC_STRUCTURES_REFERENCED', N'IR-VITEMGROUP_STRUCTURES_REFERENCED', N'IR-CHANGE_RELATIONS' ) )
END
GO

