-- FILE: reports.sql
-- =====================================================================

-----------------------------------------------------------------------------------------
-- $Copyright: (c) Bentley Systems, Incorporated. All rights reserved. $
-----------------------------------------------------------------------------------------

/*
Description
   
   To populate a new search, create a quick search in the eQl editor including all formatting. 
   Add to the last section where quick searches are populated by copyign the 'reports.content_data' clumn.

   Extended searches will usually follow the same pattern and can be copied from the quick search, but importantly
   the content_data needs to be modified, change the <ReportType> tag from 'QuickSearch' to 'ExtendedSearch' to match
   the reporttype when adding the report to the table.
*/

EXEC ebps_drop 'procedure', 'ebps_pop_report_folder'
GO
CREATE PROCEDURE ebps_pop_report_folder
(   
   @pi_parent_id       INT,
   @ps_name            NVARCHAR(255),
   @ps_description     NVARCHAR(255),
   @pi_called_by       INT,
   @pi_new_folder_id   INT OUTPUT
)
AS
DECLARE 
   @li_error     INT,
   @li_folder_id INT
BEGIN
   SET NOCOUNT ON;

   SET @pi_new_folder_id = NULL ;

   -- Find the folder if it exists
   SELECT @li_folder_id = a.gui_folder_id 
   FROM gui_folders a, gui_structures b
   WHERE a.name = @ps_name
   AND a.gui_folder_id = b.object_id AND b.object_type = 170
   AND b.gui_folder_id = @pi_parent_id

   SET @pi_new_folder_id = @li_folder_id;
   IF COALESCE(@li_folder_id, 0) = 0
   BEGIN
      EXEC @li_error = ebp_add_gui_object NULL, 170, @pi_parent_id, @ps_name, @ps_description, NULL, @pi_called_by, @pi_new_folder_id OUT
      IF @li_error <> 0 OR @@ERROR <> 0 RETURN 1 -- Failure

      -- Only allow ADMIN to change/delete, ideally would like to give to admin/system users but we won't know who those are
      EXEC @li_error = ebp_set_perm_gb @pi_new_folder_id, 170, 1, 4, -- To person 1(ADMIN) 
                                                          18, 1      -- 18 = 2(modify) and 16(delete)
      IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure   
   END
END
GO

DECLARE
   @li_error          INT,
   @li_folder_id      INT,
   @li_all_reports_id INT,
   @li_qs_reports_id  INT,
   @li_es_reports_id  INT,
   @ls_folder_name    NVARCHAR(255)
BEGIN
   SET NOCOUNT ON;

   -- If setting set assume folders exists
   SET @li_all_reports_id = dbo.ebf_setting_i(1, 20, 'AllReportsFolderId', 0, NULL);

   IF ISNULL(@li_all_reports_id, 0) < 1 
   BEGIN
      -- All Reports
      -- TODO: create the folder and set as a setting, this is too vague and a custom folder with the
      -- same name can interfere
      SELECT TOP 1 @li_all_reports_id = gui_folder_id -- Bug in earlier version meant there could be many
      FROM gui_folders 
      WHERE name = 'All Reports'
      -- It can't have a parent, if it does it may be a custom folder
      AND gui_folder_id NOT IN ( SELECT object_id FROM gui_structures WHERE object_type = 170 )

      IF ISNULL(@li_all_reports_id, 0) < 1 
      BEGIN
         EXEC @li_error = ebp_new_id N'gui_folder_id', @li_all_reports_id OUTPUT
         IF @@ERROR <> 0 OR @li_error <> 0 RETURN -- Failure

         INSERT INTO gui_folders( gui_folder_id, namespace_id, name ) 
         VALUES( @li_all_reports_id, 1, 'All Reports' )
         IF @@ERROR <> 0 RETURN -- Failure  

       -- Add as an Object (Scope becomes 'Global')
         -- lock_flags = 2|16 to prevent anyone modifying or deleting 
         INSERT INTO objects( guid, object_id, object_type, scope_id, hide_flags, lock_flags, date_added, added_by, date_changed, changed_by )
         SELECT NULL, @li_all_reports_id, 170, 1, 0, 18, GETDATE(), 1, GETDATE(), 1
         IF @@ERROR <> 0 RETURN -- Failure 
      END

      -- Ensure the setting is updated
      EXEC @li_error = ebp_set_setting N'AllReportsFolderId', 1, 20, @li_all_reports_id, N'Y', 1    
      IF @li_error <> 0 OR @@ERROR <> 0 RETURN -- Failure   
   END

   BEGIN
      SELECT @ls_folder_name = dbo.ebf_static_lookup(N'Folder.Name', N'QUICK_SEARCH')
      EXEC @li_error = ebps_pop_report_folder @li_all_reports_id, @ls_folder_name, NULL, 1, @li_folder_id OUT
      IF @@ERROR <> 0 OR @li_error <> 0 RETURN -- Failure
      SELECT @ls_folder_name = dbo.ebf_static_lookup(N'Folder.Name', N'EXT_SEARCH')
      EXEC @li_error = ebps_pop_report_folder @li_all_reports_id, @ls_folder_name, NULL, 1, @li_folder_id OUT
      IF @@ERROR <> 0 OR @li_error <> 0 RETURN -- Failure
      SELECT @ls_folder_name = dbo.ebf_static_lookup(N'Folder.Name', N'REPORTS')
      EXEC @li_error = ebps_pop_report_folder @li_all_reports_id, @ls_folder_name, NULL, 1, @li_folder_id OUT
      IF @@ERROR <> 0 OR @li_error <> 0 RETURN -- Failure
   END    

   -- Find the 'Quick Search' folder and add subfolders folder under it
   SELECT @li_qs_reports_id = a.gui_folder_id 
   FROM gui_folders a, gui_structures b
   WHERE a.name = dbo.ebf_static_lookup(N'Folder.Name', N'QUICK_SEARCH')
   AND a.gui_folder_id = b.object_id AND b.object_type = 170
   AND b.gui_folder_id = @li_all_reports_id

   SELECT @ls_folder_name = dbo.ebf_static_lookup(N'Folder.Name', N'DISTRIBUTION')
   EXEC @li_error = ebps_pop_report_folder @li_qs_reports_id, @ls_folder_name, NULL, 1, @li_folder_id OUT
   IF @@ERROR <> 0 OR @li_error <> 0 RETURN -- Failure
   SELECT @ls_folder_name = dbo.ebf_static_lookup(N'Folder.Name', N'RECORD_MNGMENT')
   EXEC @li_error = ebps_pop_report_folder @li_qs_reports_id, @ls_folder_name, NULL, 1, @li_folder_id OUT
   IF @@ERROR <> 0 OR @li_error <> 0 RETURN -- Failure
   SELECT @ls_folder_name = dbo.ebf_static_lookup(N'Folder.Name', N'MORE')
   EXEC @li_error = ebps_pop_report_folder @li_qs_reports_id, @ls_folder_name, NULL, 1, @li_folder_id OUT
   IF @@ERROR <> 0 OR @li_error <> 0 RETURN -- Failure

   -- Find the 'Extended Search' folder and add subfolders folder under it
   SELECT @li_es_reports_id = a.gui_folder_id 
   FROM gui_folders a, gui_structures b
   WHERE a.name = dbo.ebf_static_lookup(N'Folder.Name', N'EXT_SEARCH') 
   AND a.gui_folder_id = b.object_id AND b.object_type = 170
   AND b.gui_folder_id = @li_all_reports_id

   SELECT @ls_folder_name = dbo.ebf_static_lookup(N'Folder.Name', N'DISTRIBUTION')
   EXEC @li_error = ebps_pop_report_folder @li_es_reports_id, @ls_folder_name, NULL, 1, @li_folder_id OUT
   IF @@ERROR <> 0 OR @li_error <> 0 RETURN -- Failure
   SELECT @ls_folder_name = dbo.ebf_static_lookup(N'Folder.Name', N'RECORD_MNGMENT')
   EXEC @li_error = ebps_pop_report_folder @li_es_reports_id, @ls_folder_name, NULL, 1, @li_folder_id OUT
   IF @@ERROR <> 0 OR @li_error <> 0 RETURN -- Failure
   SELECT @ls_folder_name = dbo.ebf_static_lookup(N'Folder.Name', N'MORE')
   EXEC @li_error = ebps_pop_report_folder @li_es_reports_id, @ls_folder_name, NULL, 1, @li_folder_id OUT
   IF @@ERROR <> 0 OR @li_error <> 0 RETURN -- Failure
END
GO

BEGIN
   EXEC ebps_drop 'procedure', 'ebps_pop_report_folder'
END
GO

BEGIN
   -- Add as an Object (Scope becomes 'Global')
   --    Simply assume that is there is no Scope info it must go into 'Global'
   INSERT INTO objects( guid, object_id, object_type, scope_id, hide_flags, lock_flags, date_added, added_by, date_changed, changed_by )
   SELECT NULL, gui_folder_id, 170, 1, 0, 0, GETDATE(), 1, GETDATE(), 1 FROM gui_folders
   WHERE gui_folder_id NOT IN ( SELECT object_id FROM objects WHERE object_type = 170 )
END
GO

EXEC ebps_drop 'procedure', 'ebps_pop_report'
GO
CREATE PROCEDURE ebps_pop_report
(   
   @pi_folder_id       INT,
   @pi_extension_of    INT,
   @ps_code            NVARCHAR(255),
   @ps_name            NVARCHAR(255),
   @ps_description     NVARCHAR(2000),
   @pi_report_type     INT,
   @pi_out_object_type INT,
   @ps_content_data    NVARCHAR(MAX),
   @pi_new_report_id   INT OUTPUT
)
AS
DECLARE 
   @li_error     INT,
   @li_gui_id    INT
BEGIN
   SET NOCOUNT ON;

   SET @pi_new_report_id = NULL;

   -- Is there an existing search in the relevant folder?   
   IF COALESCE(@pi_folder_id, 0) = 0
   BEGIN
      SELECT @pi_new_report_id = report_id 
      FROM reports a
      LEFT OUTER JOIN gui_structures b ON a.report_id = b.object_id AND b.object_type = 171 
      WHERE b.gui_folder_id IS NULL
      AND a.code = @ps_code
   END
   ELSE
   BEGIN
      SELECT @pi_new_report_id = report_id 
      FROM reports a, gui_structures b
      WHERE a.report_id = b.object_id AND b.object_type = 171
      AND b.gui_folder_id = @pi_folder_id
      AND a.code = @ps_code
   END
   
   -- If no report found, look if it exists regardless of which folder it is linked to. If the folder data is invalid at this point rather update the report and relink
   -- to the correct folder instead of causing an error by attempting to insert a duplicate
   IF COALESCE(@pi_new_report_id, 0) = 0 
   BEGIN
      SELECT @pi_new_report_id = report_id
      FROM reports WHERE code = @ps_code AND namespace_id = 1      
   END

   IF COALESCE(@pi_new_report_id, 0) = 0 
   BEGIN
      EXEC @li_error = ebp_add_report @ps_code, @ps_name, @ps_description, @pi_report_type, 1, 
            @ps_content_data, 2, 'N', @pi_out_object_type, @pi_extension_of, 1, @pi_new_report_id OUT
      IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure

      IF COALESCE(@pi_folder_id, 0) > 0
      BEGIN
         EXEC @li_error = ebp_add_gui_object @pi_new_report_id, 171, @pi_folder_id, NULL, NULL, NULL, 1, @li_gui_id OUT
         IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure
      END

      -- Only allow ADMIN to change/delete, ideally would like to give to admin/system users but we won't know who those are
      EXEC @li_error = ebp_set_perm_gb @pi_new_report_id, 171, 1, 4, -- To person 1(ADMIN) 
                                                          18, 1      -- 18 = 2(modify) and 16(delete)
      IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure   
   END
   ELSE
   BEGIN
      -- Update
      EXEC @li_error = ebp_chg_report @pi_new_report_id, @ps_code, @ps_name, @ps_description, @pi_report_type, 1, 
            @ps_content_data, 2, 'N', @pi_out_object_type, @pi_extension_of, 1
      IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure
      
      -- Ensure it is correctly linked to the folder (if it's not it is bad data or uers interfered with these system reports)      
      IF COALESCE(@pi_folder_id, 0) > 0 AND 
         (SELECT COUNT(*) FROM gui_structures WHERE object_id = @pi_new_report_id AND object_type = 171 AND gui_folder_id = @pi_folder_id) = 0
      BEGIN
         EXEC @li_error = ebp_add_gui_object @pi_new_report_id, 171, @pi_folder_id, NULL, NULL, NULL, 1, @li_gui_id OUT
         IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1 -- Failure
      END
   END
END
GO

-- Populate quick/extended searches
DECLARE
   @li_error          INT,
   @li_qs_folder_id   INT,
   @li_es_folder_id   INT,
   @li_all_reports_id INT,
   @li_qs_report_id   INT,
   @li_es_report_id   INT,
   @li_qs_more_folder_id INT,
   @li_es_more_folder_id INT,
   @li_qs_fp_folder_id   INT,
   @li_es_fp_folder_id   INT,
   @li_qs_dist_folder_id INT,
   @li_es_dist_folder_id INT
BEGIN
   -- Find the reports folder
   SELECT @li_all_reports_id = dbo.ebf_setting_i(1, 20, N'AllReportsFolderId', 0, 1)
 
   -- Find the quicksearch folder
   SELECT @li_qs_folder_id = a.gui_folder_id 
   FROM gui_folders a, gui_structures b
   WHERE a.name = dbo.ebf_static_lookup(N'Folder.Name', N'QUICK_SEARCH')
   AND a.gui_folder_id = b.object_id AND b.object_type = 170
   AND b.gui_folder_id = @li_all_reports_id

   -- Find the extended search folder
   SELECT @li_es_folder_id = a.gui_folder_id 
   FROM gui_folders a, gui_structures b
   WHERE a.name = dbo.ebf_static_lookup(N'Folder.Name', N'EXT_SEARCH')
   AND a.gui_folder_id = b.object_id AND b.object_type = 170
   AND b.gui_folder_id = @li_all_reports_id

   -- Document searches
   EXEC @li_error = ebps_pop_report @li_qs_folder_id, NULL, 'CORE-QS-DOCUMENTS', 'Documents', 'Quicksearch for Documents', 1, 3, 
   '<Report xmlns:xs="http://www.w3.org/2001/XMLSchema" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"><ReportType>QuickSearch</ReportType><Search><EqlText>START WITH Document SELECT     Id,    Code + '' '' + IFNULL( Middle, '''' ) Number,    Revision,    Name,    Class.Path,    ApprovalStatus,    DISPLAY_NAME( ApprovalStatus ) ApprovalStatusDisplay,    State,    DISPLAY_NAME( State ) StateDisplay,    DateEffective,    Scope.Name  WHERE     (       Code LIKE @SearchString       OR Middle LIKE @SearchString       OR Name CONTAINS @SearchString    )    AND IsTemplate = ''N''  ORDER BY     Code,    Middle,    Revision </EqlText></Search><Parameters><Parameter><Name>SearchString</Name><DataType>System.String</DataType><Description>Please enter the QuickSearch string</Description><DefaultValue /><ValueSource><Type>None</Type><Definition /><DefinitionEx>Document.Code</DefinitionEx></ValueSource></Parameter></Parameters><OptionalCriteria /><Layout><Columns><Column><Code>Id</Code><Name>Id</Name><DataType>System.Int32</DataType><Width>*</Width><IsVisible>false</IsVisible><TextWrap>false</TextWrap></Column><Column><Code>Number</Code><Name>Number</Name><DataType>System.String</DataType><Width>2*</Width><IsVisible>true</IsVisible><TextWrap>false</TextWrap></Column><Column><Code>Revision</Code><Name>Revision</Name><DataType>System.String</DataType><Width>1*</Width><IsVisible>true</IsVisible><TextWrap>false</TextWrap></Column><Column><Code>Name</Code><Name>Title</Name><DataType>System.String</DataType><Width>4*</Width><IsVisible>true</IsVisible><TextWrap>false</TextWrap></Column><Column><Code>ClassPath</Code><Name>Class</Name><DataType>System.String</DataType><Width>1*</Width><IsVisible>true</IsVisible><TextWrap>false</TextWrap></Column><Column><Code>ApprovalStatus</Code><Name>Status</Name><DataType>System.String</DataType><Width>1*</Width><IsVisible>false</IsVisible><TextWrap>false</TextWrap></Column><Column><Code>ApprovalStatusDisplay</Code><Name>Approval Status</Name><DataType>System.String</DataType><Width>1*</Width><IsVisible>true</IsVisible><TextWrap>false</TextWrap></Column><Column><Code>State</Code><Name>Document Status</Name><DataType>System.String</DataType><Width>1*</Width><IsVisible>false</IsVisible><TextWrap>false</TextWrap></Column><Column><Code>StateDisplay</Code><Name>Document Status</Name><DataType>System.String</DataType><Width>1*</Width><IsVisible>true</IsVisible><TextWrap>false</TextWrap></Column><Column><Code>DateEffective</Code><Name>Date Effective</Name><DataType>System.Nullable`1[System.DateTime]</DataType><Width>*</Width><IsVisible>true</IsVisible><TextWrap>false</TextWrap></Column><Column><Code>ScopeName</Code><Name>Scope Name</Name><DataType>System.String</DataType><Width>*</Width><IsVisible>true</IsVisible><TextWrap>false</TextWrap></Column></Columns><DefaultActionObject><IdColumn>Id</IdColumn><TypeColumn>3</TypeColumn></DefaultActionObject></Layout></Report>', @li_qs_report_id OUT
   EXEC @li_error = ebps_pop_report @li_es_folder_id, @li_qs_report_id, 'CORE-ES-DOCUMENTS', 'Documents', 'Extended search for Documents', 2, 3, 
   '<Report xmlns:xs="http://www.w3.org/2001/XMLSchema" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"><ReportType>ExtendedSearch</ReportType><Search><EqlText>START WITH Document SELECT     Id,    Code + '' '' + IFNULL( Middle, '''' ) Number,    Revision,    Name,    Class.Path,    ApprovalStatus,    DISPLAY_NAME( ApprovalStatus ) ApprovalStatusDisplay,    State,    DISPLAY_NAME( State ) StateDisplay,    DateEffective,    Scope.Name  WHERE     (       Code LIKE @code OR  @code IS NULL )    AND        (        Middle LIKE @middle      OR @middle IS NULL        )    AND Name CONTAINS @name    AND Files.ContentData FREETEXT @ftr    AND DateEffective &gt;= @dateEffStart    AND DateEffective &lt;= @dateEffEnd    AND AuditDetails.AuditDate &gt;= @dateModifiedStart    AND AuditDetails.AuditDate &lt;= @dateModifiedEnd    AND AuditDetails.AuditDef.ActionType = 3    AND Class.Path LIKE ''%'' + @classPath + ''%''    AND ApprovalStatus = @approvalStatus    AND State = @state    AND IsTemplate = ''N''  ORDER BY     Code,    Middle,    Revision </EqlText></Search><Parameters><Parameter><Name>code</Name><DataType>System.String</DataType><Description>Prefix</Description><DefaultValue /><ValueSource><Type>None</Type><Definition /><DefinitionEx>Document.Code</DefinitionEx></ValueSource></Parameter><Parameter><Name>middle</Name><DataType>System.String</DataType><Description>Middle</Description><DefaultValue /><ValueSource><Type>None</Type><Definition /><DefinitionEx>Document.Middle</DefinitionEx></ValueSource></Parameter><Parameter><Name>name</Name><DataType>System.String</DataType><Description /><DefaultValue /><ValueSource><Type>None</Type><Definition /><DefinitionEx>Document.Name</DefinitionEx></ValueSource></Parameter><Parameter><Name>ftr</Name><DataType>System.Object</DataType><Description>Full Text Search</Description><DefaultValue /><ValueSource><Type>None</Type><Definition /><DefinitionEx>Document.Files.ContentData</DefinitionEx></ValueSource></Parameter><Parameter><Name>dateEffStart</Name><DataType>System.DateTime</DataType><Description>Effective Between</Description><DefaultValue>DATECALC($Today, -1, MONTHS)</DefaultValue><ValueSource><Type>Special</Type><Definition>Calendar</Definition><DefinitionEx>Document.DateEffective</DefinitionEx></ValueSource></Parameter><Parameter><Name>dateEffEnd</Name><DataType>System.DateTime</DataType><Description>and</Description><DefaultValue>$Today</DefaultValue><ValueSource><Type>Special</Type><Definition>Calendar</Definition><DefinitionEx>Document.DateEffective</DefinitionEx></ValueSource></Parameter><Parameter><Name>classPath</Name><DataType>System.String</DataType><Description /><DefaultValue /><ValueSource><Type>Search</Type><Definition>START WITH Class SELECT     Path,    Code + '' - '' + Name  WHERE     ( Code LIKE @StringValue OR Name LIKE @StringValue )    AND ClassGroup.ObjectType = 3    AND SysType NOT IN  ( ''V'', ''W'' )   ORDER BY     Code </Definition><DefinitionEx>Document.Class.Code</DefinitionEx></ValueSource></Parameter><Parameter><Name>approvalStatus</Name><DataType>System.String</DataType><Description /><DefaultValue>A</DefaultValue><ValueSource><Type>StaticLookup</Type><Definition>Document.ApprovalStatus</Definition><DefinitionEx>Document.ApprovalStatus</DefinitionEx></ValueSource></Parameter><Parameter><Name>dateModifiedStart</Name><DataType>System.DateTime</DataType><Description>Modified Between</Description><DefaultValue>DATECALC($Today, -1, MONTHS)</DefaultValue><ValueSource><Type>Special</Type><Definition>Calendar</Definition><DefinitionEx>Document.AuditDetails.AuditDate</DefinitionEx></ValueSource></Parameter><Parameter><Name>dateModifiedEnd</Name><DataType>System.DateTime</DataType><Description>and</Description><DefaultValue>$Today</DefaultValue><ValueSource><Type>Special</Type><Definition>Calendar</Definition><DefinitionEx>Document.AuditDetails.AuditDate</DefinitionEx></ValueSource></Parameter><Parameter><Name>state</Name><DataType>System.String</DataType><Description /><DefaultValue>Current</DefaultValue><ValueSource><Type>StaticLookup</Type><Definition>Document.State</Definition><DefinitionEx>Document.State</DefinitionEx></ValueSource></Parameter></Parameters><OptionalCriteria><OptionalCriterion><Name /><Description>Title</Description><Include>False</Include><VerticalOrientation>True</VerticalOrientation><EqlCriteriaKeys><EqlCriteriaKeys>WIInaHTeYSH/Z5bk3zFeTw==</EqlCriteriaKeys><EqlCriteriaKeys>dtzpKvrefSrNL1NrhHZc4w==</EqlCriteriaKeys><EqlCriteriaKeys>K/HYUMrayQ10cVtozantEZxG6kLOqz8/hLbj7pONWCs=</EqlCriteriaKeys></EqlCriteriaKeys></OptionalCriterion><OptionalCriterion><Name /><Description>Number</Description><Include>False</Include><VerticalOrientation>False</VerticalOrientation><EqlCriteriaKeys><EqlCriteriaKeys>XEhOMElGdocSYFPKoThxmg==</EqlCriteriaKeys><EqlCriteriaKeys>grzp3XY+HAKbjqiFG0Bwng==</EqlCriteriaKeys><EqlCriteriaKeys>7jbNaUcJdjidLlNimalJfA==</EqlCriteriaKeys><EqlCriteriaKeys>PHjUXkps8rPcgYwHlZZYFw==</EqlCriteriaKeys><EqlCriteriaKeys>3KFZfZlArTvOHz8+RDb/MniG2LLVA5ZJDnuYZNtsNCs=</EqlCriteriaKeys><EqlCriteriaKeys>L7OrsWILgEkd+gwIj0HC/ocVvaIiLFVUv7xGjRAlAFg=</EqlCriteriaKeys><EqlCriteriaKeys>Srh9sWCkEUeJuRkff4VX5xkxzbZgRTCeif620YTZzZo=</EqlCriteriaKeys></EqlCriteriaKeys></OptionalCriterion><OptionalCriterion><Name /><Description>Full Text Search</Description><Include>False</Include><VerticalOrientation>True</VerticalOrientation><EqlCriteriaKeys><EqlCriteriaKeys>2RY0QEUZlasnqf89ns6vxw==</EqlCriteriaKeys><EqlCriteriaKeys>2dofI2eGnW1iF40VTtWqAw==</EqlCriteriaKeys><EqlCriteriaKeys>SNozsoFK2MmVsuubg6dv/w==</EqlCriteriaKeys><EqlCriteriaKeys>egO+Tkee1hZbDtz14U5R9A==</EqlCriteriaKeys><EqlCriteriaKeys>DqfS/NuCyjgDZhdVcjSMr9Z2z1e+Z0a2T1UTfmn1Eq0=</EqlCriteriaKeys></EqlCriteriaKeys></OptionalCriterion><OptionalCriterion><Name /><Description>Date Effective</Description><Include>False</Include><VerticalOrientation>True</VerticalOrientation><EqlCriteriaKeys><EqlCriteriaKeys>vp78eWfwCHC8UaCTpo+p3Q==</EqlCriteriaKeys><EqlCriteriaKey