   -- Find the 'Distribution' folder
   SET @li_qs_dist_folder_id = NULL;
   SELECT @li_qs_dist_folder_id = a.gui_folder_id 
   FROM gui_folders a, gui_structures b
   WHERE a.name =  dbo.ebf_static_lookup(N'Folder.Name', N'DISTRIBUTION')
   AND a.gui_folder_id = b.object_id AND b.object_type = 170
   AND b.gui_folder_id = @li_qs_folder_id

   SET @li_es_dist_folder_id = NULL;
   SELECT @li_es_dist_folder_id = a.gui_folder_id 
   FROM gui_folders a, gui_structures b
   WHERE a.name = dbo.ebf_static_lookup(N'Folder.Name', N'DISTRIBUTION')
   AND a.gui_folder_id = b.object_id AND b.object_type = 170
   AND b.gui_folder_id = @li_es_folder_id

