/*
Description
   Populates the default RepositoryGroup
*/
BEGIN 
   SET NOCOUNT ON;
   
   INSERT INTO repository_groups( repos_group_id, name, status, description )
   SELECT 1, 'Main', 'A', NULL
   WHERE NOT EXISTS ( SELECT 1 FROM repository_groups WHERE repos_group_id = 1 )      
   
   -- Add as an Object (Scope becomes 'Global')
   INSERT INTO objects( guid, object_id, object_type, scope_id, hide_flags, lock_flags, date_added, added_by, date_changed, changed_by )
   SELECT NULL, 1, 192, 1, 0, 0, GETDATE(), 1, GETDATE(), 1
   WHERE NOT EXISTS ( SELECT 1 FROM objects WHERE object_id = 1 AND object_type = 192 )   
END
GO


