-----------------------------------------------------------------------------------------

/*
Description
   Populates the default Role.
*/
BEGIN
   SET NOCOUNT ON;
   
-- TODO: upgrade must make sure that group 1 isn't used.

   -- If, for any reason there is already a Role name 'Users' then rename it to 'Users - Renamed by Update Script on yyyy'/MM/dd'
   UPDATE roles SET name = name + N' - Renamed by Update Script on ' + CONVERT( NVARCHAR(10), GETDATE(), 111 )
   WHERE name = N'Users' AND role_id <> 1

   INSERT INTO roles( role_id, namespace_id, name, sys_type )
   SELECT 1, 1, N'Users', N'A' WHERE 1 NOT IN ( SELECT role_id FROM roles )

   UPDATE roles SET namespace_id = 1, name = N'Users', parent_id = NULL, sys_type = 'A'
   WHERE role_id = 1
   
   -- Add as an Object (Scope becomes 'Global')
   INSERT INTO objects( guid, object_id, object_type, scope_id, hide_flags, lock_flags, date_added, added_by, date_changed, changed_by )
   SELECT NULL, 1, 114, 1, 0, 0, GETDATE(), 1, GETDATE(), 1
   WHERE NOT EXISTS ( SELECT 1 FROM objects WHERE object_id = 1 AND object_type = 114 )   
END
GO

