-- =====================================================================
-- FILE: schedule_defs.sql
-- =====================================================================

-----------------------------------------------------------------------------------------
-- $Copyright: (c) 2015 Bentley Systems, Incorporated. All rights reserved. $
-----------------------------------------------------------------------------------------

DECLARE @li_id INT
BEGIN
   IF NOT EXISTS(SELECT 1 FROM schedule_defs WITH (NOLOCK) WHERE name = 'Default Mail Job Retry')
   BEGIN 
      BEGIN TRANSACTION
      -- A default schedule definitions that runs every 10 minutes
      /* 
         pi_month_mask : 4095 - every month
         pi_week_of_month_mask: 31 - every week
         pi_day_of_week_mask: 127 - every day
         pi_start_date: 0101 - 1st of January MMDD
         pi_end_date: 1231 - 31st of December MMDD
         pi_start_time: 000000 - start time 0
         pi_end_time: 235959 - end time 11:59:59 PM
         pi_time_interval_type: 3 - Minutes 
         pi_time_interval: 10 - number of minutes 
      */
      EXEC ebp_add_schedule_def N'Default Mail Job Retry', 4095, 31, 127, 0, 0101, 1231, 000000, 235959, NULL, 1, 1, 1, 1, 0, 3, 10, 0, 1, @li_id OUT
      UPDATE objects SET lock_flags = 18 WHERE object_id = @li_id AND object_type = 304
      COMMIT TRANSACTION
   END
END
GO

BEGIN
   --register as a usable eB.Data.MethodDef
   IF NOT EXISTS ( SELECT 1 FROM method_info WITH (NOLOCK) WHERE code_ref = N'ebp_get_next_occurrences' )
   BEGIN
      BEGIN TRANSACTION
      DECLARE @li_method_id INT
      EXEC ebp_add_method_info N'ebp_get_next_occurrences', 
                               1, -- Indicates a Stored Procedure
                               N'Y', -- Y if the method should run in a transaction, N should only be used when the method will make no updates and only retrieve data.
                               N'ebp_get_next_occurrences',
                               1, -- Option 1 registeres parameters, 0 to register them manually
                               1, -- Session Id used to make the call
                              @li_method_id OUT

      COMMIT TRANSACTION
   END
   ELSE
   BEGIN
      BEGIN TRANSACTION
      SELECT @li_method_id = method_id FROM method_info WITH (NOLOCK) WHERE code_ref = N'ebp_get_next_occurrences'
      EXEC ebp_del_method_info @li_method_id, 1

      EXEC ebp_add_method_info N'ebp_get_next_occurrences', 
                               1, -- Indicates a Stored Procedure
                               N'Y', -- Y if the method should run in a transaction, N should only be used when the method will make no updates and only retrieve data.
                               N'ebp_get_next_occurrences',
                               1, -- Option 1 registeres parameters, 0 to register them manually
                               1, -- Session Id used to make the call
                              @li_method_id OUT
      COMMIT TRANSACTION
   END

END
GO

BEGIN
   IF EXISTS( SELECT 1 FROM schedule_defs WITH(NOLOCK) WHERE name = N'Default Mail Job Retry' AND time_interval_type = 4 )
   BEGIN
      UPDATE schedule_defs SET time_interval_type = 3
      WHERE time_interval_type = 4;
      UPDATE schedule_defs SET time_interval_type = 4
      WHERE time_interval_type = 8;
   END

END
GO

