-- FILE: scopes.sql
-- =====================================================================

-----------------------------------------------------------------------------------------
-- $Copyright: (c) 2015 Bentley Systems, Incorporated. All rights reserved. $
-----------------------------------------------------------------------------------------

/*
Description
   ...

Specification
   ...

Note
   The 'Global' Scope is the only scope to have no parent and never has a concrete underwriting Object.
*/
BEGIN
   SET NOCOUNT ON;

   INSERT INTO scopes( scope_id, name, namespace_id, is_enabled, usage_count )
   SELECT 1, N'Global', 1, 'Y', 1 WHERE 1 NOT IN ( SELECT scope_id FROM scopes )

   -- Add the Scopes's Scope here - a chicken-egg issue
   -- lock_flags=2|16 cannot be modified or deleted
   INSERT INTO objects( object_id, object_type, scope_id, hide_flags, lock_flags )
   SELECT 1, 227, 1, 0, 18
   WHERE NOT EXISTS ( SELECT 1 FROM objects WHERE object_id = 1 AND object_type = 227 )     

   UPDATE scopes SET name = 'Global', namespace_id = 1, object_id = NULL, object_type = NULL, parent_id = NULL
   WHERE scope_id = 1
   
   -- Add the Namespace's Scope here - another chicken-egg issue
   -- lock_flags=2|16 cannot be modified or deleted
   INSERT INTO objects( object_id, object_type, scope_id, hide_flags, lock_flags )
   SELECT 1, 226, 1, 0, 18
   WHERE NOT EXISTS ( SELECT 1 FROM objects WHERE object_id = 1 AND object_type = 226 )      
END
GO
BEGIN
   -- For references like templates on relationships 
   INSERT INTO objects( object_id, object_type, scope_id, hide_flags, lock_flags )
   SELECT 0, a.object_type, 1, 0, 0 FROM base_types a 
   WHERE scope_type <> 1
   AND NOT EXISTS ( SELECT 1 FROM objects b WHERE a.object_type = b.object_type AND b.object_id = 0 )
END
GO


