/*
Description
   Populates the ServiceDefinition master table with some of the default definitions

Specification
   ...
   
SR_TODO: REMOVE THIS FILE - FIX BentleyCONNECT SM so it doesn't need it
*/
DECLARE 
   @id INT
BEGIN
   -- Bentley.eB.ServiceModel.IDataReader   
   SET @id = 1;
   INSERT INTO service_defs( service_def_id, code, name, description, is_admin_service )
   SELECT @id, N'Bentley.eB.ServiceModel.IDataReader', N'DataReader', N'To read data from the database', 'N'
   WHERE NOT EXISTS ( SELECT 1 FROM service_defs b WHERE b.code = N'Bentley.eB.ServiceModel.IDataReader' )

   -- Add as an Object (Scope becomes 'Global')
   --    Simply assume that is there is no Scope info it must go into 'Global'
   --    lock_flags=2|16 because it cannot be modified or deleted
   INSERT INTO objects( guid, object_id, object_type, scope_id, hide_flags, lock_flags, date_added, added_by, date_changed, changed_by )
   SELECT NULL, @id, 268, 1, 0, 18, GETDATE(), 1, GETDATE(), 1
   WHERE NOT EXISTS(SELECT 1 FROM objects WHERE object_id = @id AND object_type = 268) 

   -- Bentley.eB.ServiceModel.IDataWriter
   SET @id = 2;
   INSERT INTO service_defs( service_def_id, code, name, description, is_admin_service )
   SELECT @id, N'Bentley.eB.ServiceModel.IDataWriter', N'DataWriter',  N'To write data to the database', 'N' 
   WHERE NOT EXISTS ( SELECT 1 FROM service_defs b WHERE b.code = N'Bentley.eB.ServiceModel.IDataWriter' )

   -- Add as an Object (Scope becomes 'Global')
   --    Simply assume that is there is no Scope info it must go into 'Global'
   --    lock_flags=2|16 because it cannot be modified or deleted
   INSERT INTO objects( guid, object_id, object_type, scope_id, hide_flags, lock_flags, date_added, added_by, date_changed, changed_by )
   SELECT NULL, @id, 268, 1, 0, 18, GETDATE(), 1, GETDATE(), 1
   WHERE NOT EXISTS(SELECT 1 FROM objects WHERE object_id = @id AND object_type = 268) 

   -- Bentley.eB.ServiceModel.IDataStorageAdmin
   SET @id = 3;
   INSERT INTO service_defs( service_def_id, code, name, description, is_admin_service )
   SELECT @id, N'Bentley.eB.ServiceModel.IDataStorageAdmin', N'DataStorageAdmin',  N'To configure the DataStorage (Reader and Writer) service and database', 'N'
   WHERE NOT EXISTS ( SELECT 1 FROM service_defs b WHERE b.code = N'Bentley.eB.ServiceModel.IDataStorageAdmin' )

   -- Add as an Object (Scope becomes 'Global')
   --    Simply assume that is there is no Scope info it must go into 'Global'
   --    lock_flags=1 because it cannot be modified
   INSERT INTO objects( guid, object_id, object_type, scope_id, hide_flags, lock_flags, date_added, added_by, date_changed, changed_by )
   SELECT NULL, @id, 268, 1, 0, 1, GETDATE(), 1, GETDATE(), 1
   WHERE NOT EXISTS(SELECT 1 FROM objects WHERE object_id = @id AND object_type = 268) 

   -- Bentley.eB.ServiceModel.IFileStorage
   SET @id = 4;
   INSERT INTO service_defs( service_def_id, code, name, description, is_admin_service )
   SELECT @id, N'Bentley.eB.ServiceModel.IFileStorage', N'FileStorage', N'To Reader and Writer files to persistent storage',  'N' 
   WHERE NOT EXISTS ( SELECT 1 FROM service_defs b WHERE b.code = N'Bentley.eB.ServiceModel.IFileStorage' )

   -- Add as an Object (Scope becomes 'Global')
   --    Simply assume that is there is no Scope info it must go into 'Global'
   --    lock_flags=2|16 because it cannot be modified or deleted
   INSERT INTO objects( guid, object_id, object_type, scope_id, hide_flags, lock_flags, date_added, added_by, date_changed, changed_by )
   SELECT NULL, @id, 268, 1, 0, 18, GETDATE(), 1, GETDATE(), 1
   WHERE NOT EXISTS(SELECT 1 FROM objects WHERE object_id = @id AND object_type = 268) 

   -- Bentley.eB.ServiceModel.IFileStorageAdmin
   SET @id = 5;
   INSERT INTO service_defs( service_def_id, code, name, description, is_admin_service )
   SELECT @id, N'Bentley.eB.ServiceModel.IFileStorageAdmin', N'FileStorageAdmin',  N'To configure the FileStorage service and repositories', 'N' 
   WHERE NOT EXISTS ( SELECT 1 FROM service_defs b WHERE b.code = N'Bentley.eB.ServiceModel.IFileStorageAdmin' )

   -- Add as an Object (Scope becomes 'Global')
   --    Simply assume that is there is no Scope info it must go into 'Global'
   --    lock_flags=2|16 because it cannot be modified or deleted
   INSERT INTO objects( guid, object_id, object_type, scope_id, hide_flags, lock_flags, date_added, added_by, date_changed, changed_by )
   SELECT NULL, @id, 268, 1, 0, 18, GETDATE(), 1, GETDATE(), 1
   WHERE NOT EXISTS(SELECT 1 FROM objects WHERE object_id = @id AND object_type = 268) 

   --!! NOTE ON ID VALUES (do not remove this comment) !!--
   --   When adding the next entry, ensure the Id used is the next value across all releases.
   --   If multiple code streams are worked on in parallel this can easily happen if both add different entries
END
