EXEC ebps_drop 'procedure', 'ebps_pop_setting_category'
GO
CREATE PROCEDURE ebps_pop_setting_category
(
   @pi_category_id INT,
   @ps_name        NVARCHAR(255),
   @ps_description NVARCHAR(2000)
)
AS
BEGIN
   SET NOCOUNT ON;

   INSERT INTO setting_categories ( category_id, name, description )
   SELECT @pi_category_id, @ps_name, @ps_description
   WHERE NOT EXISTS ( SELECT 1 FROM setting_categories WHERE category_id = @pi_category_id )
   IF @@ERROR <> 0 RETURN 1 -- Failure

   UPDATE setting_categories SET name = @ps_name, description = @ps_description
   WHERE category_id = @pi_category_id
   IF @@ERROR <> 0 RETURN 1 -- Failure
END
GO

EXEC ebps_drop 'procedure', 'ebps_pop_setting_def'
GO
CREATE PROCEDURE ebps_pop_setting_def
(
   @pi_object_type INT,
   @ps_code        NVARCHAR(100),
   @ps_description NVARCHAR(2000),
   @pi_data_type   INT,
   @ps_read_only   CHAR(1),
   @ps_managed     CHAR(1),
   @ps_browsable   CHAR(1),
   @pi_category_id INT
)
AS
BEGIN
   SET NOCOUNT ON;

   -- just forward to ebps_add_setting_def - for System-defined entries the intent will always be NULL
   EXEC ebps_add_setting_def @pi_object_type, @ps_code, @ps_description, @pi_data_type, @ps_read_only, @ps_managed, @ps_browsable, @pi_category_id, NULL
      IF @@ERROR <> 0 RETURN 1 -- Failure

   RETURN 0 -- Success
END
GO
EXEC ebps_drop 'procedure', 'ebps_link_setting_def'
GO
CREATE PROCEDURE ebps_link_setting_def
(
   @ps_parent_code      NVARCHAR(100),
   @pi_parent_type      INT,
   @ps_child_code       NVARCHAR(100),
   @pi_child_type       INT
)
AS
DECLARE
   @pi_parent_settting_id INT,
   @pi_child_settting_id INT
BEGIN
   SET NOCOUNT ON;

   SELECT @pi_parent_settting_id = setting_id
   FROM setting_defs
   WHERE code = @ps_parent_code AND object_type = @pi_parent_type
   IF @pi_parent_settting_id IS NULL
   BEGIN
      EXEC ebp_raise_error N'<Cannot link the settings, the parent setting definition does not exist.>', 1
      RETURN 1 -- Failure
   END

   SELECT @pi_child_settting_id = setting_id
   FROM setting_defs
   WHERE code = @ps_child_code AND object_type = @pi_child_type
   IF @pi_child_settting_id IS NULL
   BEGIN
      EXEC ebp_raise_error N'<Cannot link the settings, the child setting definition does not exist.>', 1
      RETURN 1 -- Failure
   END

   UPDATE setting_defs
   SET parent_id = @pi_parent_settting_id WHERE setting_id = @pi_child_settting_id
   IF @@ERROR <> 0 RETURN 1 -- Failure

   RETURN 0 -- Success
END
GO
EXEC ebps_drop 'procedure', 'ebps_pop_setting'
GO
CREATE PROCEDURE ebps_pop_setting
(
   @ps_code        NVARCHAR(100),
   @pi_object_id   INT,
   @pi_object_type INT,
   @pany_value     NVARCHAR(MAX)
)
AS
DECLARE
   @li_setting_id INT
BEGIN
   SET NOCOUNT ON;

   SELECT @li_setting_id = setting_id
   FROM setting_defs
   WHERE code = @ps_code AND object_type = @pi_object_type
   IF @li_setting_id IS NULL
   BEGIN
      EXEC ebp_raise_error N'<Cannot populate the settings, the setting definition does not exist.>', 1
      RETURN 1 -- Failure
   END

   -- Only populate if no value exists otherwise we will basically be reverting to defaults if this script
   -- is executed multiple times.
   IF NOT EXISTS(SELECT 1 FROM settings WHERE setting_id = @li_setting_id AND object_id = @pi_object_id)
   BEGIN
      INSERT INTO settings ( setting_id, object_id, value )
      SELECT @li_setting_id, @pi_object_id, @pany_value
      WHERE NOT EXISTS ( SELECT 1 FROM settings WHERE setting_id = @li_setting_id AND object_id = @pi_object_id )
      IF @@ERROR <> 0 RETURN 1 -- Failure
   END

   --UPDATE settings
   --SET value = @pany_value
   --WHERE setting_id = @li_setting_id AND object_id = @pi_object_id
   --IF @@ERROR <> 0 RETURN 1 -- Failure

   RETURN 0 -- Success
END
GO

