-- =====================================================================
-- FILE: sharepoint_items.sql
-- =====================================================================

-----------------------------------------------------------------------------------------
-- $Copyright: (c) 2015 Bentley Systems, Incorporated. All rights reserved. $
-----------------------------------------------------------------------------------------

/*
Description
   There MUST always be a root SharePoint Item [typically 'SharePoint'] with item_id = 1.

Note
   You must fix the ids after a manual insert.

Specification
   SAN03919 Rev 1.0
*/
BEGIN
   SET NOCOUNT ON;

   INSERT INTO sharepoint_items( item_id, name, item_type, origin, excluded, sync_options, status, synchronizing, hints )
   SELECT 1, 'SharePoint', 1, 'S', 'N', 0, 'N', 'N', 0
   WHERE NOT EXISTS ( SELECT 1 FROM sharepoint_items WHERE item_id = 1 )

   INSERT INTO sharepoint_items( item_id, name, item_type, origin, excluded, sync_options, status, synchronizing, hints, parent_id )
   SELECT 2, 'Historic References', 7, 'S', 'N', 0, 'N', 'N', 0, 1
   WHERE NOT EXISTS ( SELECT 1 FROM sharepoint_items WHERE item_id = 2 )

   -- Just to make sure noone renamed it.
   UPDATE sharepoint_items 
   SET name = 'SharePoint',
       description = '{ProductName} SharePoint Explorer contains all link information between {ProductName} and on [or many] SharePoint Libraries.'
   WHERE item_id = 1

   UPDATE sharepoint_items 
   SET name = 'Historic References',
       description = 'The Historic References contains information regarding files that where linked to SharePoint at some point in the past.'
   WHERE item_id = 2
   
   -- Add as an Object (Scope becomes 'Global')
   INSERT INTO objects( guid, object_id, object_type, scope_id, hide_flags, lock_flags, date_added, added_by, date_changed, changed_by )
   SELECT NULL, 1, 223, 1, 0, 0, GETDATE(), 1, GETDATE(), 1
   WHERE NOT EXISTS ( SELECT 1 FROM objects WHERE object_id = 1 AND object_type = 223 )   
   
   INSERT INTO objects( guid, object_id, object_type, scope_id, hide_flags, lock_flags, date_added, added_by, date_changed, changed_by )
   SELECT NULL, 2, 223, 1, 0, 0, GETDATE(), 1, GETDATE(), 1
   WHERE NOT EXISTS ( SELECT 1 FROM objects WHERE object_id = 2 AND object_type = 223 )      
END
GO

GO


-- =====================================================================
-- FILE: sites.sql
-- =====================================================================

-----------------------------------------------------------------------------------------
-- $Copyright: (c) 2015 Bentley Systems, Incorporated. All rights reserved. $
-----------------------------------------------------------------------------------------

-- Create the Default Site
DECLARE @li_int INT
BEGIN
   INSERT INTO sites(site_id, name, description) 
   SELECT 1, 'Main','Main Site' 
   WHERE NOT EXISTS(SELECT 1 FROM sites WHERE site_id = 1)

   -- Add as an Object (Scope becomes 'Global')
   INSERT INTO objects( guid, object_id, object_type, scope_id, hide_flags, lock_flags, date_added, added_by, date_changed, changed_by )
   SELECT NULL, 1, 255, 1, 0, 0, GETDATE(), 1, GETDATE(), 1
   WHERE NOT EXISTS ( SELECT 1 FROM objects WHERE object_id = 1 AND object_type = 255 )  

   -- Set the default site (used if none supplied or set against the person) to the Main site
   SELECT @li_int = setting_id FROM setting_defs
   WHERE code = 'LastLoggedInSiteId' AND object_type = 20;

   IF NOT EXISTS(SELECT 1 FROM settings WHERE setting_id = @li_int)
   BEGIN
      -- Don't use ebp_set_setting - persons will not be populated yet (because it in turn needs sites) so permission checks will fail so set this value directly.
     -- EXEC ebp_set_setting 'LastLoggedInSiteId', 1, 20, 1, 'N', 1
     INSERT INTO settings (setting_id, object_id, value) SELECT @li_int, 1, 1
   END
END
GO

GO


