-----------------------------------------------------------------------------------------

/*
Description
   Pre-populate system spatial connection types
*/
EXEC ebps_drop 'procedure', 'ebps_populate_conn_types'
GO
CREATE PROCEDURE ebps_populate_conn_types
(   
   @pi_connection_type_id   INT, 
   @ps_name                 NVARCHAR(255),
   @ps_description          NVARCHAR(2000)
)
AS
BEGIN
   SET NOCOUNT ON;

   INSERT INTO spatial_connection_types( connection_type_id, name, description)
   SELECT @pi_connection_type_id, @ps_name, @ps_description
   WHERE NOT EXISTS( SELECT 1 FROM spatial_connection_types WHERE connection_type_id = @pi_connection_type_id )
   IF @@ERROR <> 0 RETURN 1 -- Failure
   
   UPDATE spatial_connection_types SET name = @ps_name, description = @ps_description
   WHERE connection_type_id = @pi_connection_type_id
   IF @@ERROR <> 0 RETURN 1 -- Failure

   RETURN 0 -- Success
END
GO
BEGIN
   SET NOCOUNT ON;
   
   EXEC ebps_populate_conn_types 1, N'WMS', N'A connection to an OGC Server that supports the WMS or WFS protocols'
   EXEC ebps_populate_conn_types 2, N'Oracle', N'Information to instantiate a connection to an Oracle server'
   EXEC ebps_populate_conn_types 3, N'SQL Server', N'Information to instantiate a connection to Microsoft SQL Server'
   EXEC ebps_populate_conn_types 4, N'ODBC Spatial', N'Information to instantiate a database connection through ODBC'

END
GO   
EXEC ebps_drop 'procedure', 'ebps_populate_conn_types'
GO


GO


