/*
Description
   Pre-populate system spatial layer types
*/
EXEC ebps_drop 'procedure', 'ebps_populate_layer_types'
GO
CREATE PROCEDURE ebps_populate_layer_types
(   
   @ps_code                         NVARCHAR(15),
   @ps_is_reprojectable             CHAR(1),
   @pi_valid_conn_type              INT
)
AS
BEGIN
   SET NOCOUNT ON;

   INSERT INTO spatial_layer_types( code, is_reprojectable, valid_connection_type)
   SELECT @ps_code, @ps_is_reprojectable, @pi_valid_conn_type
   WHERE NOT EXISTS( SELECT 1 FROM spatial_layer_types WHERE code = @ps_code )
   IF @@ERROR <> 0 RETURN 1 -- Failure
   
   UPDATE spatial_layer_types SET is_reprojectable = @ps_is_reprojectable, valid_connection_type = @pi_valid_conn_type
   WHERE code = @ps_code
   IF @@ERROR <> 0 RETURN 1 -- Failure

   RETURN 0 -- Success
END
GO
BEGIN
   SET NOCOUNT ON;
   
   EXEC ebps_populate_layer_types N'SystemLayer', 'Y', NULL
   EXEC ebps_populate_layer_types N'WMSLayer', 'N', 1 --WMS connection type is 1
   EXEC ebps_populate_layer_types N'ExorLayer', 'Y', 2 --Oracle connection type is 2
   EXEC ebps_populate_layer_types N'SHPLayer', 'Y', NULL
   EXEC ebps_populate_layer_types N'SQLServerLayer', 'Y', 3 --SQL Server connection type is 3
   EXEC ebps_populate_layer_types N'OracleLayer', 'Y', 2 --Oracle connection type is 2
   EXEC ebps_populate_layer_types N'BingMapsLayer', 'N', NULL
   EXEC ebps_populate_layer_types N'ODBCLayer', 'Y', 4 --ODBC Spatial connection type is 4
END
GO   
EXEC ebps_drop 'procedure', 'ebps_populate_layer_types'
GO

