-- =====================================================================

-----------------------------------------------------------------------------------------
-- $Copyright: (c) Bentley Systems, Incorporated. All rights reserved. $
-----------------------------------------------------------------------------------------

-- All Invokable standard_reports which will not be allowed if the setting 'AllowUnsecureMethods' is disabled.

BEGIN
   DECLARE @li_method_id INT
   SELECT @li_method_id = method_id FROM method_info WHERE code_ref = N'ebpr_run_standard_report'
   IF @li_method_id > 0
   BEGIN
      EXEC ebp_del_method_info @li_method_id, 1
   END

   EXEC ebp_add_method_info 'ebpr_run_standard_report',
                            1, -- Indicates a Stored Procedure
                           'N', -- Y if the method should run in a transaction, N should only be used when the method will make no updates and only retrieve data.
                            'ebpr_run_standard_report',
                            1, -- Option 1 registers parameters, 0 to register them manually
                            1, -- Session Id used to make the call
                           @li_method_id OUT
END
GO

