/*
Description
   Populates StateMachines, States and StateTransitions for objects.
Note
   Please add your StateMachine in the 'Populate Items' part
*/

EXEC ebps_drop 'procedure', 'ebps_unlock_state_machine'
GO
 CREATE PROCEDURE ebps_unlock_state_machine
 (
 @pi_state_machine_id      INT
 )
 AS
 BEGIN
   UPDATE objects
   SET lock_flags = 0
   WHERE object_id = @pi_state_machine_id
   AND object_type = 323;
END
 GO

 EXEC ebps_drop 'procedure', 'ebps_lock_state_machine'
GO
CREATE PROCEDURE ebps_lock_state_machine
   (
   @pi_state_machine_id       INT
   )
AS
DECLARE
   @li_cnt INT;
BEGIN
   SELECT @li_cnt = COUNT(0) FROM objects WITH (NOLOCK) WHERE object_id = @pi_state_machine_id AND object_type = 323 AND lock_flags <> 18
   IF @li_cnt > 0
   BEGIN
      UPDATE objects
      SET lock_flags = 18
      WHERE object_id = @pi_state_machine_id 
      AND object_type = 323;
   END
END
GO


EXEC ebps_drop 'procedure', 'ebps_pop_state_machine'
GO
CREATE PROCEDURE ebps_pop_state_machine
   (
   @ps_state_machine_name  NVARCHAR(100),
   @pi_state_machine_id    INT OUTPUT
   )
AS
DECLARE
   @li_count INT;
BEGIN
   SELECT @li_count = COUNT(0) FROM state_machines WITH (NOLOCK) WHERE name = @ps_state_machine_name 
   IF @li_count = 0
   BEGIN
      EXEC ebp_add_state_machine @ps_state_machine_name, 1, @pi_state_machine_id OUTPUT
   END
   ELSE
   BEGIN
      SELECT @pi_state_machine_id = state_machine_id FROM state_machines WITH (NOLOCK) WHERE name = @ps_state_machine_name
      EXEC ebps_unlock_state_machine @pi_state_machine_id;
   END
END
GO

EXEC ebps_drop 'procedure', 'ebps_pop_state'
GO
CREATE PROCEDURE ebps_pop_state
   (
   @pi_state_machine_id       INT,
   @ps_state_code             NVARCHAR(100),
   @ps_state_name             NVARCHAR(100), 
   @ps_is_start               NCHAR(1), 
   @ps_is_end                 NCHAR(1),
   @pi_state_id               INT OUTPUT
   )
AS
DECLARE
   @li_count INT;
BEGIN
   SELECT @li_count = COUNT(0) FROM states WITH (NOLOCK) WHERE state_machine_id = @pi_state_machine_id  AND code = @ps_state_code;
   IF @li_count = 0
   BEGIN
      EXEC ebp_add_state @pi_state_machine_id, @ps_state_code, @ps_state_name, @ps_is_start, @ps_is_end, 1, @pi_state_id OUTPUT
   END
END
GO

EXEC ebps_drop 'procedure', 'ebps_pop_state_transition'
GO
CREATE PROCEDURE ebps_pop_state_transition
   (
   @pi_state_machine_id       INT,
   @ps_from_state_name        NVARCHAR(100),
   @ps_to_state_name          NVARCHAR(100),
   @ps_transition_name        NVARCHAR(100)
   )
AS
DECLARE
   @li_state_transition_id    INT,
   @li_from_state_id          INT,
   @li_to_state_id            INT,
   @li_cnt                    INT,
   @li_error                  INT
BEGIN
   SELECT @li_from_state_id = state_id FROM states WITH (NOLOCK) WHERE state_machine_id = @pi_state_machine_id AND name = @ps_from_state_name
   IF COALESCE(@li_from_state_id, 0) =0 
   BEGIN 
      EXEC ebp_raise_error_1 N'<State ''{0}'' Not found. Please make sure that you call ebps_pop_state before populating the transition.>', @ps_from_state_name, NULL, NULL, 1;
   END

   SELECT @li_to_state_id = state_id FROM states WITH (NOLOCK) WHERE state_machine_id = @pi_state_machine_id AND name = @ps_to_state_name
   IF COALESCE(@li_to_state_id, 0) =0 
   BEGIN 
      EXEC ebp_raise_error_1 N'<State ''{0}'' Not found. Please make sure that you call ebps_pop_state before populating the transition.>', @ps_to_state_name, NULL, NULL, 1;
   END
   
   SELECT @li_cnt = COUNT(0) FROM state_transitions t WITH (NOLOCK) WHERE t.from_state_id = @li_from_state_id AND t.to_state_id = @li_to_state_id
   IF @li_cnt = 0 
   BEGIN
      EXEC @li_error = ebp_add_state_transition @li_from_state_id, @li_to_state_id, @ps_transition_name, 1, @li_state_transition_id OUTPUT
      IF @@ERROR <> 0 OR @li_error <> 0 RETURN 1;
   END
   RETURN 0;
END
GO



/*
-- Populate Items
*/
DECLARE
   @li_state_machine_id    INT,
   @ls_state_machine_name  NVARCHAR(100),
   @li_id                  INT
BEGIN
   -- ConditionStatus
   SET @ls_state_machine_name = 'ConditionStatus';
   EXEC ebps_pop_state_machine @ls_state_machine_name, @li_state_machine_id OUTPUT

   IF COALESCE(@li_state_machine_id, 0) > 0
   BEGIN
      -- States
      EXEC ebps_pop_state @li_state_machine_id, N'U', N'Unavailable', N'Y', N'N', @li_id OUTPUT
      EXEC ebps_pop_state @li_state_machine_id, N'A', N'Available'  , N'N', N'N', @li_id OUTPUT
      EXEC ebps_pop_state @li_state_machine_id, N'S', N'Selected'   , N'N', N'N', @li_id OUTPUT
      EXEC ebps_pop_state @li_state_machine_id, N'I', N'Instructed' , N'N', N'N', @li_id OUTPUT
      EXEC ebps_pop_state @li_state_machine_id, N'T', N'Actioned'   , N'N', N'N', @li_id OUTPUT;
      EXEC ebps_pop_state @li_state_machine_id, N'C', N'Completed'  , N'N', N'Y', @li_id OUTPUT
      EXEC ebps_pop_state @li_state_machine_id, N'W', N'Written Off', N'N', N'Y', @li_id OUTPUT
      -- Transitions
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Unavailable', N'Available'  , N'Available'
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Unavailable', N'Written Off', N'Write Off'
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Unavailable', N'Completed'  , N'Complete'
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Available'  , N'Selected'   , N'Select'
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Available'  , N'Unavailable', N'Unavailable'
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Available'  , N'Written Off', N'Write Off'
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Available'  , N'Completed'  , N'Complete'
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Available'  , N'Instructed' , N'Instruct'
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Selected'   , N'Instructed' , N'Instruct'
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Selected'   , N'Available'  , N'Available'
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Selected'   , N'Completed'  , N'Complete'
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Selected'   , N'Written Off', N'Write Off'
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Instructed' , N'Completed'  , N'Complete'
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Instructed' , N'Selected'   , N'Select'
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Instructed' , N'Actioned'   , N'Act'
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Instructed' , N'Written Off', N'Write Off'
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Actioned'   , N'Completed'  , N'Complete'
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Actioned'   , N'Written Off', N'Write Off'
      EXEC ebps_lock_state_machine @li_state_machine_id;
   END;

   -- Task Order/WorkOrderStatus
   SET @ls_state_machine_name = 'WorkOrderStatus';
   EXEC ebps_pop_state_machine @ls_state_machine_name, @li_state_machine_id OUTPUT
      
   IF COALESCE(@li_state_machine_id, 0) > 0
   BEGIN
      -- States
      EXEC ebps_pop_state @li_state_machine_id, N'D', N'Draft'     , N'Y', N'N', @li_id OUTPUT
      EXEC ebps_pop_state @li_state_machine_id, N'A', N'Authorized', N'N', N'N', @li_id OUTPUT
      EXEC ebps_pop_state @li_state_machine_id, N'I', N'Instructed', N'N', N'N', @li_id OUTPUT
      EXEC ebps_pop_state @li_state_machine_id, N'X', N'Cancelled' , N'N', N'Y', @li_id OUTPUT
      EXEC ebps_pop_state @li_state_machine_id, N'C', N'Completed' , N'N', N'Y', @li_id OUTPUT
      -- Transitions
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Draft'     , N'Authorized', N'Authorize'    -- Submit For Approval
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Draft'     , N'Instructed', N'Instruct'     -- Approve
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Draft'     , N'Cancelled' , N'Cancel'       -- Cancel
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Authorized', N'Instructed', N'Instruct'     -- Approve 
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Authorized', N'Draft'     , N'Reject'       -- Reject Approval
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Instructed', N'Draft'     , N'Un-Instruct'  -- Unapprove
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Instructed', N'Completed' , N'Complete'     -- Complete
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Instructed', N'Cancelled' , N'Cancel'       -- Cancel
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Cancelled' , N'Draft'     , N'Draft'        -- Reset state (needed

      EXEC ebps_lock_state_machine @li_state_machine_id;
   END


   -- Task/RepairStatus
   SET @ls_state_machine_name = 'RepairStatus';
   EXEC ebps_pop_state_machine @ls_state_machine_name, @li_state_machine_id OUTPUT; 
   
   IF COALESCE(@li_state_machine_id, 0) > 0
   BEGIN
      -- States
      EXEC ebps_pop_state @li_state_machine_id, N'U', N'Unavailable', N'Y', N'N', @li_id OUTPUT
      EXEC ebps_pop_state @li_state_machine_id, N'A', N'Available'  , N'N', N'N', @li_id OUTPUT
      EXEC ebps_pop_state @li_state_machine_id, N'S', N'Selected'   , N'N', N'N', @li_id OUTPUT
      EXEC ebps_pop_state @li_state_machine_id, N'T', N'Actioned'   , N'N', N'N', @li_id OUTPUT
      EXEC ebps_pop_state @li_state_machine_id, N'I', N'Instructed' , N'N', N'N', @li_id OUTPUT
      EXEC ebps_pop_state @li_state_machine_id, N'C', N'Completed'  , N'N', N'Y', @li_id OUTPUT
      EXEC ebps_pop_state @li_state_machine_id, N'W', N'Written Off', N'N', N'Y', @li_id OUTPUT
      -- Transitions
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Unavailable'  , N'Available'  , N'Enable'
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Available'    , N'Unavailable', N'Disable'
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Available'    , N'Selected'   , N'Select'
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Available'    , N'Completed'  , N'Complete'  -- Required to promote a stand alone Defect
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Available'    , N'Written Off', N'Write Off' -- Required to promote a stand alone Defect
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Selected'     , N'Instructed' , N'Instruct'
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Instructed'   , N'Available'  , N'Not Done'
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Instructed'   , N'Selected'   , N'Unapprove'
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Instructed'   , N'Actioned'   , N'Action'
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Instructed'   , N'Written Off', N'Write Off'
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Instructed'   , N'Completed'  , N'Complete'
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Actioned'     , N'Written Off', N'Write Off'
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Actioned'     , N'Completed'  , N'Complete'
   -- lock the state machine again
      EXEC ebps_lock_state_machine @li_state_machine_id;
   END
    -- TaskOrderItemLineStatus
   SET @ls_state_machine_name = 'TaskOrderItemLineStatus';
   EXEC ebps_pop_state_machine @ls_state_machine_name, @li_state_machine_id OUTPUT;
   IF @li_state_machine_id > 0
   BEGIN
      -- States
      EXEC ebps_pop_state @li_state_machine_id, N'D', N'Draft'      , N'Y', N'N', @li_id OUTPUT;
      EXEC ebps_pop_state @li_state_machine_id, N'A', N'Authorized' , N'N', N'N', @li_id OUTPUT;
      EXEC ebps_pop_state @li_state_machine_id, N'I', N'Instructed' , N'N', N'N', @li_id OUTPUT;
      EXEC ebps_pop_state @li_state_machine_id, N'T', N'Actioned'   , N'N', N'N', @li_id OUTPUT;
      EXEC ebps_pop_state @li_state_machine_id, N'W', N'Written Off', N'N', N'Y', @li_id OUTPUT;
      EXEC ebps_pop_state @li_state_machine_id, N'C', N'Completed'  , N'N', N'Y', @li_id OUTPUT;
      EXEC ebps_pop_state @li_state_machine_id, N'N', N'Not Done'   , N'N', N'Y', @li_id OUTPUT;
      -- Transitions
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Draft'      , N'Authorized'  , N'Authorize';
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Draft'      , N'Instructed'  , N'Instruct';
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Draft'      , N'Not Done'    , N'Not Done';
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Draft'      , N'Written Off' , N'Write Off';
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Authorized' , N'Draft'       , N'Reject Authorize';
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Authorized' , N'Instructed'  , N'Authorize';
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Instructed' , N'Draft'       , N'Unapprove';
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Instructed' , N'Actioned'    , N'Action';
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Instructed' , N'Completed'   , N'Complete';
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Instructed' , N'Written Off' , N'Write Off';
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Instructed' , N'Not Done'    , N'Not Done';
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Actioned'   , N'Completed'   , N'Complete';
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Actioned'   , N'Written Off' , N'Write Off';
      EXEC ebps_pop_state_transition @li_state_machine_id, N'Actioned'   , N'Not Done'    , N'Not Done';
      EXEC ebps_lock_state_machine @li_state_machine_id;

   END
END
GO

BEGIN 
   EXEC ebps_drop 'procedure', 'ebps_pop_state_machine';
   EXEC ebps_drop 'procedure', 'ebps_pop_state';
   EXEC ebps_drop 'procedure', 'ebps_pop_state_transition';
   EXEC ebps_drop 'procedure', 'ebps_lock_state_machine';
   EXEC ebps_drop 'procedure', 'ebps_unlock_state_machine';
END
GO

-----------------------------------------------------------------------------------------
-- The upgrade scripts are executed before the populate, so when upgrading from older eb versions the related states do not exist
-- As a result it's not possible to upgrade the related Task Orders/Task Order Items/ Tasks properly.
-- A proper upgrade would require the creation/update of the state_machines in the same build.
-- TODO: A replacement of this code may be required.

EXEC ebps_drop 'function', 'tmp_get_state_machine_id'
GO
CREATE FUNCTION dbo.tmp_get_state_machine_id
(
   @ps_state_machine_name NVARCHAR(100)
)
RETURNS INT
AS
BEGIN
   DECLARE @li_state_machine_id INT =(SELECT state_machine_id FROM state_machines WITH(NOLOCK) WHERE namespace_id = 1 AND name = @ps_state_machine_name);
   RETURN @li_state_machine_id;
END
GO

EXEC ebps_drop 'function', 'tmp_get_state_id'
GO
CREATE FUNCTION dbo.tmp_get_state_id
(
   @pi_state_machine_id   INT,
   @ps_state              NVARCHAR(100)
)
RETURNS INT
AS
BEGIN
   DECLARE @state_id INT = (SELECT state_id FROM states WITH(NOLOCK) WHERE code = @ps_state AND state_machine_id = @pi_state_machine_id);
   RETURN @state_id;
END
GO

EXEC ebps_drop 'function', 'tmp_get_state_code'
GO
CREATE FUNCTION dbo.tmp_get_state_code
(
   @pi_state_id   INT
)
RETURNS NCHAR(1)
AS
BEGIN
   DECLARE @ls_state_code NCHAR(1) = (SELECT code FROM states WITH(NOLOCK) WHERE state_id = @pi_state_id);
   RETURN @ls_state_code;
END
GO

BEGIN -- Upgrade Task Orders block
   DECLARE @li_object_type_id    INT = 341;
   DECLARE @li_state_machine_id  INT =dbo.tmp_get_state_machine_id('WorkOrderStatus');

   INSERT INTO object_states (object_id, object_type, state_id, state_machine_id, date_effective, remark)
   SELECT 
      task_order_id, 
      @li_object_type_id,
      dbo.tmp_get_state_id(@li_state_machine_id,
          CASE  WHEN approval_status = N'N' AND status = N'N' THEN N'D'
                WHEN approval_status = N'S' AND status = N'N' THEN 'A'
                WHEN approval_status = N'A' AND status = N'A' THEN 'I'
                WHEN approval_status = N'A' AND status = N'X' THEN 'X'
                WHEN approval_status = N'A' AND status = N'C' THEN 'C'
                ELSE 'D'
          END),
      @li_state_machine_id,
      GETDATE(),
      'Upgrade'
   FROM task_orders WITH (NOLOCK)
   WHERE NOT EXISTS (SELECT 1 FROM object_states WITH(NOLOCK) WHERE object_id = task_order_id AND object_type = @li_object_type_id AND state_machine_id = @li_state_machine_id)
   
END
GO 

BEGIN -- Upgrade Tasks
   DECLARE @li_object_type_id    INT = 340;
   DECLARE @li_state_machine_id  INT =dbo.tmp_get_state_machine_id('RepairStatus');
   INSERT INTO object_states (object_id, object_type, state_id, state_machine_id, date_effective, remark)
   SELECT 
      tsk.task_id, 
      @li_object_type_id, 
      dbo.tmp_get_state_id(@li_state_machine_id,
          CASE WHEN tsk.approval_status = N'N' AND tsk.task_status = N'N' AND tsk.parent_type IS NULL THEN N'A'
                   WHEN tsk.approval_status IN ( N'N', N'S', N'A') AND task_status IN ( N'N', N'F', N'I') AND tsk.parent_type = 341 THEN N'S'
                   WHEN tsk.approval_status = N'A' AND tsk.task_status IN( N'A', 'E', 'P', 'S' ) AND tsk.parent_type = 341 THEN N'I'
                   WHEN tsk.approval_status = N'A' AND tsk.task_status = N'C' AND tsk.parent_type = 341 THEN N'C'
                   WHEN tsk.approval_status = N'A' AND tsk.task_status = N'X' AND tsk.parent_type = 341 THEN N'W'
              ELSE N'U'
              END),
      @li_state_machine_id,
      GETDATE(),
      'Upgrade'
   FROM tasks tsk WITH (NOLOCK)
   INNER JOIN objects obj WITH(NOLOCK) ON obj.object_id= tsk.task_id AND obj.object_type = 340
   INNER JOIN class_objects co WITH(NOLOCK) ON co.class_id = obj.class_id AND co.sys_type = 'P' -- Update only repair tasks
   WHERE tsk.parent_type <> 340 
      AND NOT EXISTS (SELECT 1 FROM object_states WITH(NOLOCK) WHERE object_id = task_id AND object_type = @li_object_type_id AND state_machine_id = @li_state_machine_id)

END
GO

BEGIN -- Upgrade Task Order Items
   DECLARE @li_object_type_id INT =342;
   DECLARE @li_state_machine_id  INT =dbo.tmp_get_state_machine_id('TaskOrderItemLineStatus');
   DECLARE @li_tsk_state_machine_id  INT =dbo.tmp_get_state_machine_id('RepairStatus');
   DECLARE @li_ord_state_machine_id  INT =dbo.tmp_get_state_machine_id('WorkOrderStatus');

   WITH line_items (line_item_id, object_type, is_excluded, approval_status, task_status)as 
   (
   SELECT 
    toi.line_item_id,
    @li_object_type_id,
    toi.is_excluded,
    dbo.tmp_get_state_code(ord.state_id),
    COALESCE(dbo.tmp_get_state_code(tsk.state_id), dbo.tmp_get_state_code(ord.state_id))  
    FROM task_order_items toi 
    INNER JOIN object_states ord ON ord.object_type = 341 AND ord.object_id = toi.task_order_id AND ord.state_machine_id = @li_ord_state_machine_id
    LEFT OUTER JOIN object_states tsk ON tsk.object_type = 340 AND tsk.object_id = toi.task_id AND tsk.state_machine_id = @li_tsk_state_machine_id
    WHERE NOT EXISTS (SELECT 1 FROM object_states WHERE object_id = toi.line_item_id AND object_type = @li_object_type_id AND state_machine_id = @li_state_machine_id)
   )
   INSERT INTO object_states (object_id, object_type, state_id, state_machine_id, date_effective, remark)
   SELECT line_item_id, object_type,
      COALESCE(dbo.tmp_get_state_id(@li_state_machine_id,
         CASE 
            WHEN is_excluded = 'Y' THEN 'N'
            WHEN approval_status IN (N'D', N'A') THEN approval_status
            ELSE task_status
         END), dbo.tmp_get_state_id(@li_state_machine_id, 'D')),
   @li_state_machine_id,
   GETDATE(),
   'Upgrade'
   FROM line_items;
END
GO

BEGIN
   -- Clean up helping functions.
   EXEC ebps_drop 'function', 'tmp_get_state_machine_id'
   EXEC ebps_drop 'function', 'tmp_get_state_code'
   EXEC ebps_drop 'function', 'tmp_get_state_id'

END 
GO

