EXEC ebps_drop 'procedure', 'ebps_pop_static_lookup'
GO
CREATE PROCEDURE ebps_pop_static_lookup
(   
   @ps_name         NVARCHAR(255),
   @ps_lookup_key   NVARCHAR(255),
   @ps_lookup_value NVARCHAR(255)
)
AS
DECLARE
   @li_cnt INT
BEGIN
   SET NOCOUNT ON;

   SELECT @li_cnt = COUNT(*)
   FROM static_lookups
   WHERE name = @ps_name AND lookup_key = @ps_lookup_key

   IF @li_cnt < 1
   BEGIN
      INSERT INTO static_lookups( name, lookup_key, lookup_value )
      VALUES ( @ps_name, @ps_lookup_key, @ps_lookup_value )
      IF @@ERROR <> 0 RETURN 1 -- Failure
   END
   ELSE
   BEGIN   
      UPDATE static_lookups 
      SET lookup_value = @ps_lookup_value
      WHERE name = @ps_name AND lookup_key = @ps_lookup_key
      IF @@ERROR <> 0 RETURN 1 -- Failure
   END

   RETURN 0 -- Success
END
GO

BEGIN
   EXEC ebps_pop_static_lookup N'AttributeDef.DataType',N'CH',N'String'
   EXEC ebps_pop_static_lookup N'AttributeDef.DataType',N'DA',N'Date'
