   EXEC ebps_pop_static_lookup N'AttributeDef.DataType',N'PD',N'Fixed Value'
   EXEC ebps_pop_static_lookup N'AttributeDef.DataType',N'RF',N'Object Reference'
   EXEC ebps_pop_static_lookup N'AttributeDef.DataType',N'GE',N'Geometry'
