   EXEC ebps_pop_static_lookup N'Class.SysTypeForDocument',N'R',N'Snapshot'
   EXEC ebps_pop_static_lookup N'Class.SysTypeForDocument',N'L',N'Item List'
   EXEC ebps_pop_static_lookup N'Class.SysTypeForDocument',N'P',N'Product Baseline'
   EXEC ebps_pop_static_lookup N'Class.SysTypeForDocument',N'I',N'Physical Item Baseline'
   EXEC ebps_pop_static_lookup N'Class.SysTypeForDocument',N'S',N'Serial List'
   EXEC ebps_pop_static_lookup N'Class.SysTypeForDocument',N'Y',N'Survey'
   EXEC ebps_pop_static_lookup N'Class.SysTypeForDocument',N'U',N'User Defined'
   EXEC ebps_pop_static_lookup N'Class.SysTypeForDocument',N'W',N'Virtual Item Baseline'
   EXEC ebps_pop_static_lookup N'Class.SysTypeForDocument',N'V',N'Virtual Item Structure'
   EXEC ebps_pop_static_lookup N'Class.SysTypeForDocument',N'F',N'File Container'   
   EXEC ebps_pop_static_lookup N'Class.SysTypeForTask',N'A',N'Approval Task'
   EXEC ebps_pop_static_lookup N'Class.SysTypeForTask',N'U',N'User Defined'
   EXEC ebps_pop_static_lookup N'Class.SysTypeForTask',N'I',N'Inspection'
   EXEC ebps_pop_static_lookup N'Class.SysTypeForTask',N'P',N'Repair'
   EXEC ebps_pop_static_lookup N'Class.SysTypeForTask',N'Y',N'Survey'
   EXEC ebps_pop_static_lookup N'Class.SysTypeForTask',N'R',N'Review'
   EXEC ebps_pop_static_lookup N'Class.SysTypeForTask',N'C',N'Consolidate'
   EXEC ebps_pop_static_lookup N'Class.SysTypeForTaskOrder',N'U',N'User Defined'
   EXEC ebps_pop_static_lookup N'Class.SysTypeForTaskOrder',N'I',N'Inspection'
   EXEC ebps_pop_static_lookup N'Class.SysTypeForTaskOrder',N'P',N'Repair'
   EXEC ebps_pop_static_lookup N'Class.SysTypeForWorkTask',N'U',N'User Defined'
   EXEC ebps_pop_static_lookup N'Class.SysTypeForWorkTask',N'A',N'Approval Task'
   EXEC ebps_pop_static_lookup N'Class.SysTypeForSharePoint',N'W',N'Web Application'
