-- =====================================================================

-----------------------------------------------------------------------------------------
-- $Copyright: (c) 2018 Bentley Systems, Incorporated. All rights reserved. $
-----------------------------------------------------------------------------------------

/*
Description
   Ensures that every person with a user account owns a temporary file area   
*/
DECLARE
   @li_person_id                    INT,
   @li_temporay_file_container_id   INT,
   @li_myeb_folder_id               INT,
   @li_gui_id                       INT
BEGIN
   DECLARE all_users_cursor CURSOR LOCAL FAST_FORWARD FOR 
   SELECT person_id FROM users
   OPEN all_users_cursor
   FETCH NEXT FROM all_users_cursor INTO @li_person_id
   WHILE (@@FETCH_STATUS = 0)
   BEGIN
      -- Add a Temporary File Area for the user if not already existing
      SET @li_temporay_file_container_id = dbo.ebf_setting_i(@li_person_id, 4, 'PersonalTemporaryFileContainerId', 0, NULL);

      IF COALESCE( @li_temporay_file_container_id, 0 ) < 1
      BEGIN
         EXEC ebps_add_temporary_file_area @li_person_id, 1
      END

      FETCH NEXT FROM all_users_cursor INTO @li_person_id
   END
   CLOSE all_users_cursor
   DEALLOCATE all_users_cursor
END
GO

