CREATE PROCEDURE ebps_populate_dimensions
(   
   @ps_code        NVARCHAR(100),
   @ps_name        NVARCHAR(255),
   @ps_description NVARCHAR(2000),
   @ps_derivation  NVARCHAR(2000)
)
AS
DECLARE @li_id INT,
        @ls_description NVARCHAR(2000)
BEGIN
   IF @ps_name = @ps_description
   BEGIN
      SET @ls_description = NULL;
   END
   ELSE
   BEGIN
      SET @ls_description = @ps_description;
   END
   IF NOT EXISTS(SELECT 1 FROM uom_dimensions WITH (NOLOCK) WHERE code = @ps_code )
   BEGIN
      EXEC ebp_add_dimension @ps_code, @ps_name, @ls_description, @ps_derivation, 1, @li_id OUT
   END
END
GO

