CREATE PROCEDURE ebps_populate_koqs
(   
   @ps_code             NVARCHAR(100),
   @ps_name             NVARCHAR(255),
   @ps_description      NVARCHAR(2000),
   @ps_dimension_code   NVARCHAR(100),
   @ps_parent_code      NVARCHAR(100),
   @ps_unit_code        NVARCHAR(100)
)
AS
DECLARE
   @li_id               INT,
   @li_dimension_id     INT,
   @li_def_unit_id      INT,
   @li_parent_id        INT
BEGIN

   -- Get the dimension id
   SELECT @li_dimension_id = dimension_id FROM uom_dimensions WITH (NOLOCK) WHERE code = @ps_dimension_code
   
   IF dbo.ebfs_compare_s ( @ps_parent_code, '' )  = 0
   BEGIN
      SELECT @li_parent_id = koq_id FROM uom_kind_of_quantities WITH (NOLOCK) WHERE code = @ps_parent_code
   END
   ELSE
   BEGIN
      SET @li_parent_id = NULL;
   END
   -- Get the unit 
   SELECT @li_def_unit_id = unit_id FROM uom_units WITH (NOLOCK) WHERE code = @ps_unit_code

   IF NOT EXISTS(SELECT 1 FROM uom_kind_of_quantities WITH (NOLOCK) WHERE code = @ps_code )
   BEGIN
      EXEC ebp_add_kind_of_quantity @ps_code, @ps_name, @ps_description, @li_dimension_id, @li_def_unit_id, @li_parent_id, 1, @li_id OUT
   END
END
GO

