EXEC ebps_drop 'procedure', 'ebps_populate_unit_systems'
GO
CREATE PROCEDURE ebps_populate_unit_systems
(   
   @ps_code        NVARCHAR(100),
   @ps_name        NVARCHAR(255),
   @ps_description NVARCHAR(2000)
)
AS
DECLARE 
   @li_id INT,
   @ls_code NVARCHAR(100)
BEGIN
   SET @ls_code = dbo.ebf_tidy_string( @ps_code, 1 );
   IF NOT EXISTS(SELECT 1 FROM uom_unit_systems WITH (NOLOCK) WHERE code = @ls_code )
   BEGIN
      EXEC ebp_add_unit_system @ls_code, @ps_name, @ps_description, 1, @li_id OUT
   END
END
GO

-- Use the UOM_Dump_ECUnits tool under Core/Helper Programs to generate these
BEGIN
   EXEC ebps_populate_unit_systems N'None',N'None',N'The standard None unit system.'
   EXEC ebps_populate_unit_systems N'SI',N'Si',N'International System of Units'
   EXEC ebps_populate_unit_systems N'US',N'UsCustomary',N'U.S. Customary'
   EXEC ebps_populate_unit_systems N'Both',N'Both',N'The standard Both unit system for units that are considered standard in both SI and US Customary systems.'
END
GO

EXEC ebps_drop 'procedure', 'ebps_populate_unit_systems'
GO

GO


