EXEC ebps_drop 'procedure', 'ebps_populate_units'
GO
CREATE PROCEDURE ebps_populate_units
(   
   @ps_code                 NVARCHAR(100),
   @ps_name                 NVARCHAR(255),
   @ps_symbol               NVARCHAR(255),
   @ps_dimension_code       NVARCHAR(100),
   @ps_unit_system_code     NVARCHAR(100),
   @ps_base_unit_code       NVARCHAR(100),
   @pdec_conversion_factor  NUMERIC(38,19),
   @pdec_conversion_offset  NUMERIC(38,19),
   @pi_converter            INT
)
AS
DECLARE 
   @li_id                   INT,
   @ls_name                 NVARCHAR(255),
   @li_dimension_id         INT,
   @li_unit_system_id       INT,
   @li_base_unit_id         INT
BEGIN 
   -- Changed procedure to be case insensitive because ECObjects units case may change over time.
   -- Get the dimension_id 
   SELECT @li_dimension_id = dimension_id FROM uom_dimensions WITH (NOLOCK) WHERE UPPER(code) = UPPER(@ps_dimension_code)
   -- Get the unit system id
   SELECT @li_unit_system_id = unit_system_id FROM uom_unit_systems WITH (NOLOCK) WHERE UPPER(name) = UPPER(@ps_unit_system_code)
   -- Get the base unit id

   IF @ps_base_unit_code = @ps_code 
   BEGIN
      SET @li_base_unit_id = NULL;
   END
   ELSE
   BEGIN
      SELECT @li_base_unit_id = unit_id FROM uom_units WITH (NOLOCK) WHERE UPPER(code)  = UPPER(@ps_base_unit_code)
   END

   SELECT @li_id = unit_id FROM uom_units WITH (NOLOCK) WHERE UPPER(code) = UPPER(@ps_code)
  
   IF @@ROWCOUNT = 0
   BEGIN
      EXEC ebp_add_unit @ps_code, @ps_name, NULL, @ps_symbol, @li_dimension_id, @li_unit_system_id, @li_base_unit_id, NULL, @pdec_conversion_factor, @pdec_conversion_offset, @pi_converter, 1, @li_id OUT
   END
   ELSE
   BEGIN
     EXEC ebp_chg_unit @li_id, @ps_code, @ps_name, NULL, @ps_symbol, @li_dimension_id, @li_unit_system_id, @li_base_unit_id, NULL, @pdec_conversion_factor, @pdec_conversion_offset, @pi_converter, 1
   END
END
GO

