/*
Description
   populate predefined usage reports
*/

EXEC ebps_drop 'procedure', 'ebps_pop_usage_report'
GO
CREATE PROCEDURE ebps_pop_usage_report
(   
   @ps_metric_key       NVARCHAR(255),
   @ps_metric_query     NVARCHAR(MAX)
)
AS
DECLARE 
   @li_error            INT,
   @ldt_last_run_date   DATETIME
BEGIN
   SET NOCOUNT ON;
   SET @ldt_last_run_date = DATEADD(DAY, -7, GETDATE()); -- This is going to be executed weekly. setting a week before the install will enable the first report being sent immediately.
   IF NOT EXISTS ( SELECT 1 FROM usage_reports WITH(NOLOCK) WHERE metric_key = @ps_metric_key )
   BEGIN
      INSERT INTO usage_reports ( metric_key, metric_query, metric_value, last_run_date ) VALUES ( @ps_metric_key, @ps_metric_query, 0, @ldt_last_run_date )
   END
END
GO

-- Populate usage report query
DECLARE
   @li_error          INT
BEGIN
   -- item query
   EXEC @li_error = ebps_pop_usage_report N'ALIMPhysicalItems', N'SELECT COUNT(*) FROM items i WITH(NOLOCK) WHERE i.template = ''N'' AND ( i.date_obsolete IS NULL OR DATEDIFF( DAY, i.date_obsolete, GETDATE() ) < 0  )'

   -- document query
   EXEC @li_error = ebps_pop_usage_report N'ALIMActiveDocuments', N'SELECT COUNT(*) FROM documents d WITH (NOLOCK) WHERE d.template = ''N'' AND d.prototype = ''N'' AND d.is_vig = ''N'' AND d.superceded = ''N'' AND ( d.date_obsolete IS NULL OR DATEDIFF(DAY, d.date_obsolete, GETDATE())<0 ) AND d.current_revision = ''Y'''

   -- serial query
   EXEC @li_error = ebps_pop_usage_report N'ALIMSerialItems', N'SELECT COUNT(*) FROM item_serial_nos s WITH(NOLOCK) WHERE s.template = ''N'' AND s.status <> ''S'''

   -- tag query
   EXEC @li_error = ebps_pop_usage_report N'ALIMActiveTags', N'SELECT COUNT(*) FROM tags t WITH(NOLOCK) WHERE t.template = ''N'' AND t.operational_status in (''P'',''O'') AND t.state_hint & 1 <> 0 AND t.state_hint & 2048 = 0 AND t.prototype = ''N'''

END
GO

BEGIN
   EXEC ebps_drop 'procedure', 'ebps_pop_usage_report'
END
GO

