-----------------------------------------------------------------------------------------

DECLARE @li_id INT
BEGIN
   SET NOCOUNT ON;
   
   -- There must alway be one user 'ADMIN' linked to the ADMIN person
   -- Let's make sure the ID is 1 as it might be used in special circumstances
   SET @li_id = 1; --SELECT @li_id = COALESCE(MAX(user_id), 0) + 1 FROM users;
   INSERT INTO users (user_id, person_id, claim_issuer, claim_type, claim_value)
   SELECT @li_id, 1, 'eB', 'http://schemas.bentley.com/ws/2011/03/identity/claims/ebusername', 'ADMIN' 
   WHERE NOT EXISTS ( SELECT 1 FROM users WHERE claim_issuer = 'eB' AND claim_type = 'http://schemas.bentley.com/ws/2011/03/identity/claims/ebusername' AND claim_value = 'ADMIN' )

   -- Add as an Object
   INSERT INTO objects( guid, object_id, object_type, scope_id, hide_flags, lock_flags, date_added, added_by, date_changed, changed_by, intent_id )
   SELECT NULL, @li_id, 116, 1, 0, 0, GETDATE(), 1, GETDATE(), 1, NULL   
   WHERE NOT EXISTS ( SELECT 1 FROM objects WHERE object_id = @li_id AND object_type = 116 )

   UPDATE users SET person_id = 1
   WHERE claim_issuer = 'eB' AND claim_type = 'http://schemas.bentley.com/ws/2011/03/identity/claims/ebusername' AND claim_value = 'ADMIN'
   
   SELECT @li_id = user_id FROM users WHERE claim_issuer = 'eB' AND claim_type = 'http://schemas.bentley.com/ws/2011/03/identity/claims/ebusername' AND claim_value = 'ADMIN'

   -- Default admin session, for where legacy internal calls are made to be executed as admin. It should
   -- really never be used.
   INSERT INTO sessions ( session_id, person_id, scope_id, namespace_id, site_id, date_added, date_refreshed, filter_flags, user_id, machine_name, application_name, token )
   SELECT 1, 1, 1, 1, 1, GETDATE() , GETDATE(), 0, @li_id, 'Unknown', 'Unknown', '00000000-0000-0000-0000-000000000000'
   WHERE NOT EXISTS ( SELECT 1 FROM sessions WHERE session_id = 1 )

   -- Ensure the default scope and namespace for this session is always 1 (if someone changed it, change it back since the scripts will asume this)
   UPDATE sessions SET scope_id = 1, namespace_id = 1 WHERE session_id = 1;

   INSERT INTO session_scopes( session_id, scope_id, default_visible )
   SELECT 1, 1, 'Y'
   WHERE NOT EXISTS ( SELECT 1 FROM session_scopes WHERE session_id = 1 )
END
GO

BEGIN
   IF NOT EXISTS(SELECT 1 FROM id_number_register WHERE id_type = 'user_id')
   BEGIN
      INSERT INTO id_number_register( id_type, last_number ) VALUES( 'user_id', 0 )
   END
   EXEC sp_executesql N'
   UPDATE id_number_register SET last_number = (SELECT MAX( user_id ) FROM users ) WHERE id_type = ''user_id''';
END
GO

